s_abi_mods_ex=[[
<b c=tg>能力値+2: </b>ヒューマンのキャラクターは、その多様な性質を表すために、作成時に選択した1つの能力値に＋2のボーナスを得る。

<b c=tg>敏捷力+2、知力+2、 <c=tr>耐久力-2: </c></b>エルフは身も心も軽快だが、その姿はか弱い。

<b c=tg>能力値+2: </b>ハーフエルフのキャラクターは、その多様な性質を表すために、作成時に選択した能力値1点に＋2のボーナスを得る。

<b c=tg>耐久力+2、判断力+2、<c=tr>魅力-2: </c></b>ドワーフはタフで賢明だが、少々不愛想でもある。

<b c=tg>知力+2、魅力+2、 <c=tr>筋力-2: </c></b>ノームは肉体的には弱いが、意外に頑健でその態度は自然に好感を抱かせる。

<b c=tg>敏捷力+2、魅力+2、 <c=tr>筋力-2: </c></b>ハーフリングは身軽で意志が強いが、小柄なため他の種族より弱い。

<b c=tg>筋力+2、耐久力+2、 <c=tr>知力-2,魅力-2: </c></b>ハーフオークは強いが、オークの血筋を引いているため、鈍く粗野である。
]]


-- 类人生物	Humanoid


s_hum			= "ヒューマン"
s_hum_d			= [[
ヒューマンは並外れた意欲と、耐え忍び拡大する偉大な能力を持っており、現在世界を支配している種族である。

彼らの帝国や国家は広大なもので、これらの社会の市民は剣の腕力と呪文の力で自らの名を刻む。

野心的で、時に英雄的で、常に自信に満ち溢れている人間は、共通の目標に向かって協力する能力を持っている。

他の種族に比べると短命だが、その無限のエネルギーと行動力によって、短い生涯で多くのことを成し遂げる。
]]
s_hum_eds={
[race_ed_dd1]=[[
人類は並外れた行動力と忍耐力、拡大力を持ち、現在世界を支配している種族である。彼らの帝国や国家は広大無辺であり、これらの社会の市民は剣の腕力と呪文の力で自らの名を刻んでいる。人間の文化は、野蛮だが高潔な部族から、退廃的で悪魔を崇拝する高貴な一族まで、国際的な都市に至るまでさまざまである。人間の好奇心と野心は、定住的なライフスタイルを好む傾向に勝ることが多く、多くの者が故郷を離れ、忘れ去られた無数の世界の隅々を探検したり、強大な軍隊を率いて隣国を征服したりする。

人間社会はノスタルジーと未来主義の奇妙な融合体であり、過去の栄光や切望に満ちた「黄金時代」に熱狂する一方で、伝統や歴史を捨て去り、新たな事業に打って出る。過去の遺物は貴重な骨董品や博物館の展示品として保管される。人間は無生物の遺物だけでなく、生き物をも収集するのが好きで、娯楽のために展示したり、自分の側に置いたりする。他の種族は、このような行動は人間の精神に深く根ざした支配欲や権力を主張する衝動によるもので、世界の野生のものや場所を奪い、支配し、手なずけようとする衝動によるものだと指摘する。より慈愛に満ちた見方をする人々は、人間は単なる経験の収集家であり、生きていようが死んでいようが生きていなかろうが、取っておいたり保管したりするものは、自分が行った場所や見たもの、成し遂げた行為を思い出させるための記念品に過ぎないと考えている。現在と未来の価値はおまけに過ぎず、本当の価値は、人類の必然的な進歩を継続的に思い起こさせるものなのだ。

人類は多くの場所で古い人種や文化に魅了されるが、時には古く（彼らにとっては）時代遅れの伝統に不満を抱いたり、軽蔑さえするようになる。そのため、他民族に対する態度は、異国趣味と偶像崇拝が奇妙に混ざり合ったものでさえある。しかし、たいていの場合、それらの文化に対する理解や評価はごく表面的なレベルであり、根深い傲慢さとともに、ほとんどの人間は自分たちを社会の基準以外の何ものでもないと考えることが難しい。他種族の研究に携わっている人間の学者は、最も国際的で、彼らの性質や文化に精通していると思われがちだが、社会的距離を縮めることに関しては、学識の浅い種族に劣ることが多い。人間は社交的で、しばしば友好的で、他人と交わり、交流することを厭わないが、他人を軽々しく疎外することに無頓着であることが、他種族が彼らと接するとき、とても苛立たせるのである。

もちろん、他民族に人間への疑念を抱かせるのは、善意や無知、数的優位だけではない。歴史上、人間の他国人恐怖症や不寛容が社会的孤立主義、市民弾圧、血なまぐさい粛清、異端審問、暴徒による暴力、そして公然たる戦争につながった例は、まったくもって枚挙にいとまがない。人種、言語、宗教、階級、性別、あるいはその他の違いについてであれ、恐怖を煽り、疑念を抱かせやすいのは人間だけではない。より過激な同胞が政治的・文化的な話題を独占している間、より穏健な人間市民はしばしば傍観している。しかし、過激派に対抗し、あらゆる人種、信条、国、種族を超え、垣根を越えて大小の同盟や関係を結び、違いを超えて団結する精神を体現している人々も大勢いる。
]],
[race_ed_dd2]=[[

]],
[race_ed_phy]=[[
人間の身体的特徴は、世界の風土と同じくらい多様である。南の大陸の黒い肌の部族から、北の大地の色白で野蛮な略奪者まで、人間はさまざまな肌の色、体型、顔の特徴を持っている。

一般的に、人間の肌の色は赤道に近いほど濃くなる。同時に、骨格、髪の色や質感、目の色、顔や体の表現型の特徴は、地域によって大きく異なる。頬骨は高かったり広かったり、鼻筋は通っていたり平らだったり、唇はふっくらとしていたり薄かったりする。

もちろん、外見はランダムではないし、家族的、部族的、あるいは国家的な共通点から、その人間の出身地が一目でわかる、あるいは少なくとも推測できることも多い。

身につける衣服や宝石だけでなく、手の込んだヘアスタイル、ピアス、タトゥー、さらには傷跡までもがそうである。
]],
[race_ed_soc]=[[
人間社会は、数多くの政府、考え方、ライフスタイルで構成されている。最も古い人類の文化は何千年も過去の歴史をたどっているが、エルフやドワーフなど他の種族の社会と比べると、帝国が分裂し、新しい王国が古い王国を吸収するように、人類社会は常に流動的な状態にあるように見える。

一般的に、人間はその柔軟性、独創性、野心で知られている。生物学的にというよりも、既知の枠を飛び越え、何が待っているかに向かって突き進むその意欲においてだ。

多くの、あるいはほとんどの人間は、個人としては快適な日常に満足しているが、人間という種には、あらゆる地平線の向こうの可能性に向かって努力する、勇敢な発見精神がある。
]],
[race_ed_rel]=[[
人間は繁殖力があり、その意欲と数の多さから、領土拡張や植民活動の際に他の種族と接触することがよくあります。この傾向は多くの場合、暴力や戦争につながりますが、人間はまた、暴力で対抗しようとしない種族とは迅速に和解し、同盟を築くこともあります。

プライドが高く、時には傲慢なまでに、人間はドワーフをみすぼらしい酔っ払い、エルフを飛んじゃったおバカさん、ハーフリングを卑劣な泥棒、ノームをひねくれた狂人、ハーフエルフやハーフオークを厄介者扱いするかもしれないが、種族間の多様性ゆえに、多くの人間は他者をありのままに受け入れることに長けている。

人間は自分のことに没頭するあまり、他人の言語や文化に無知なままであることがある。この無知を憎悪の極みとし、危険、奇妙、あるいは "不純 "と見なした他人を不寛容、抑圧、まれに絶滅させることさえある。ありがたいことに、このような事件や運動は、一部の人々の目には全人類を汚すものと映るかもしれないが、多くの場合、ルールというよりは例外である。
]],
[race_ed_aln]=[[
人類はおそらく、一般的な種族の中で最も多様性に富み、巨悪と無限の善の両方の能力を備えている。ある種族は広大な野蛮な大群を形成し、またある種族は数マイルに及ぶ広大な都市を建設する。全体として見れば、ほとんどの人間は中立であるが、一般的には特定の同盟を持つ国家や文明に集まる傾向がある。

人類はまた、最も幅広い神々や宗教を持ち、他の種族のような伝統との結びつきがなく、栄光や庇護を与えてくれる者なら誰にでも頼ろうとする。
]],
[race_ed_adv]=[[
野心だけで動く人間は数知れず、多くの冒険者は富、名声、社会的地位、アーケインの知識など、目的を達成するための手段として冒険をする。また、危険なスリルだけを求めて冒険の道を志す者も少なくない。

人間には様々な地域や背景があり、冒険者パーティの中でどのような役割も果たすことができる。
]],
[race_ed_nam]=[[
一般的に特定の伝統や共有する歴史に固執する他の人種とは異なり、人類の多様性はほぼ無限の名前を生み出した。

北部の野蛮な部族の人間の名前は、亜熱帯の船乗りや貿易商の国の人間の名前とはだいぶ違う。

同じ言語を話す人間であっても、その出自によって、信仰や外見と同じようにさまざまな名前を持つことがある。
]],
}


s_elf			= "エルフ"
s_elf_d			= [[
背が高く、気高く、しばしば高慢なエルフは長命で、荒野の繊細な支配者である。

エルフはアーケインを得意とする。彼らはしばしば自然との本質的な結びつきを利用して新しい呪文を鍛え、作り手と同じように、時の荒波をほとんどものともしないような不思議なアイテムを作り出す。

私的で内向的な種族であるエルフは、他人の苦境に無関心な印象を与えることがある。
]]
s_elf_eds={
[race_ed_dd1]=[[
長寿のエルフは自然界の子供であり、表面的にはフェイクリチャーとよく似ているが、重要な違いがある。フェイはその故郷の動植物と真に結び付き、ほぼ不滅の声として、また荒野の守護者として存在するが、エルフはその代わりに周囲の自然界と同調する人型生物である。エルフは自然とのバランスを保ちながら生きようとし、他の多くの人間よりも自然をよく理解している。この理解には神秘的なものもあるが、エルフの寿命の長さから来るものも大きい。エルフは同じ土地で何世紀も活動し続けることができる。そのためには、持続可能なライフスタイルを維持することを学ばなければならないが、それは自然を意のままにしようとするのではなく、自然とともに働くときに最も容易にできることである。

しかし、エルフと自然との結びつきは、実利主義によるものばかりではない。エルフの身体は時間の経過とともにゆっくりと変化し、精神的・霊的な状態を身体的に表現するようになる。また、ある地域に長期間住む者は、身体的に周囲の環境に適応するようになり、特にその土地の環境を反映した色彩を帯びるようになる。

エルフはプライバシーと伝統を重んじ、個人レベルでも国家レベルでも友人を作るのに時間がかかることが多いが、ひとたび部外者が同志として受け入れられると、その同盟関係は何世代にもわたって続くことがある。エルフは長い寿命を共有する種族、あるいはそれ以上の種族と同盟を結ぶことに大きな喜びを感じ、しばしばドラゴン、来訪者、フェイと親しくなろうと努力する。一方、寿命の短い種族の中で一生を過ごすエルフは、次々と目の前で仲間が老いて死んでいくのを目の当たりにした結果、死に対する偏った認識を持ち、不機嫌になることが多い。
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
一般的に人間よりも背が高いエルフは、優雅でほっそりとした体格をしており、長く尖った耳がそれを際立たせている。エルフの細い手足は驚くほどのパワーを秘めているからだ。

目は大きくアーモンド型で、鮮やかな色の大きな瞳孔を持つ。エルフ全体の色彩は千差万別で、人間のそれよりもはるかに多様である。しかし、エルフの色彩は周囲の環境と一致することが多いため、ひとつのコミュニティ内のエルフはよく似ているように見えることもある。森に住むエルフの髪、目、そして肌の色には、緑、茶色、褐色などのバリエーションがあることが多い。

エルフの服装は自然界の美しさを表現することが多いが、都市に住むエルフは最新のファッションに身を包む傾向がある。都会に住むエルフが他の都会人と出会う場所では、そのエルフが流行の最先端を行くことが多い。
]],
[race_ed_btl]=[[
エルフは用心深い戦士であり、可能な限り時間をかけて相手と戦闘場所を分析し、待ち伏せ、狙撃、カモフラージュを駆使して有利な状況を最大化する。エルフは隠れ家からの射撃を好み、見つかる前に退却し、敵が全員死ぬまでこの作戦を繰り返す。

ロングボウ、ショートボウ、レイピア、ロングソードを好む。近接戦闘では、エルフは優雅かつ大胆で、観察するのも美しい複雑な立ち回りを用いる。エルフの魔法使いは、他のエルフに影響を与えないため、戦闘中に睡眠魔法を使うことが多い。
]],
[race_ed_soc]=[[
多くのエルフは自然との絆を感じ、自然界と調和して生きようと努力する。多くのエルフがそうであるように、資源に恵まれた豊かな土地を好むが、厳しい気候に追いやられると、その地域の恵みを守り、羊飼いとして働き、わずかな収穫から最大限の利益を得る方法を学ぶ。砂漠や荒れ地で持続可能で信頼できる生活を切り開くことができたとき、彼らはその達成を社会として誇りに思う。そのため、そのような土地を旅しなければならない部外者と親しくなる際には優れたガイドとなるが、自分たちと同じように乏しい土地で生活することを学んでいない者を軽蔑するため、そのような友人は稀である。

エルフは、特に木、骨、象牙、皮革を扱う職人技と芸術性に天賦の才がある。しかし、ほとんどのエルフは土や石を扱うことを不快に感じ、鍛造や石工、陶芸を避けたがる。共同体の中でそのような仕事をしなければならない場合、少数のエルフはその仕事に惹かれるかもしれないが、職人としての技量にかかわらず、そのような "土の職人"は一般的に他のエルフから少しずれていると見られている。最も偏狭なエルフ社会では、下層階級として扱われることさえある。

エルフはまた、文字や魔法、丹念な研究にも造詣が深い。生まれつきの鋭敏な頭脳と感覚、そして先天的に備わった忍耐力が、ウィザードに特に適している。魔術の研究と達成は、兵士や建築家と同じように実用的な目標であると同時に、詩や彫刻と同じように芸術的な努力でもあると考えられている。エルフの社会では、ウィザードは力強さと美的価値を併せ持つ芸術の達人として非常に高い評価を得ている。他の呪文の使い手が軽蔑されることはないが、エルフのウィザードに惜しみなく注がれる賞賛を得ることはない。
]],
[race_ed_rel]=[[
エルフは他種族を軽率で衝動的だと決めつけ、見下す傾向があるが、個人レベルでは人格判断に優れている。多くの場合、エルフは他種族の特定のメンバーを評価するようになり、その個人は相応しく、尊敬に値すると見なす一方で、種族全体を見下すようになる。この行動を指摘された場合、そのエルフはなぜ "特別な友人 "が、その友人が "他の種族よりとても優れている "ことにエルフが気づいたことに腹を立てるのか理解できないことが多い。そのような偏見をありのままに受け止めているエルフでさえ、そのような見方が自分の思考を色づけてしまわないよう、常に自らを戒めなくてはならない。

しかしエルフは、他の種族や文化のあらゆる側面を否定するほど愚かではない。エルフはドワーフの隣人を望まないかもしれないが、ドワーフの鍛冶の技術やオークの脅威に立ち向かう粘り強さは真っ先に認めるだろう。エルフはノームを奇妙な（そして時には危険な）珍品と見なすが、彼らの魔法の才能は賞賛と尊敬に値すると考える。ハーフリングはしばしば憐れみの目で見られるが、この小さな民はエルフにとって伝統的な故郷を持たず、漂流しているように見えるからである。エルフは人間に魅了される。彼らは、エルフが何世紀もかけて築き上げたような充実した人生を、数年の短い年月で送っているように見える。実際、多くのエルフが人間に夢中になる。ハーフエルフの多さがそれを証明している。しかし、エルフはどのような種類の異種交配も受け入れ難く、そのような子孫は通常縁を切る。同様にハーフオークに対しても不信と猜疑の念を抱き、オークと人間の性格の悪い面を併せ持っていると考える。
]],
[race_ed_aln]=[[
エルフは感情的で気まぐれだが、優しさと美しさを大切にする。ほとんどのエルフは混沌として善良で、すべての生き物の安全と幸福を願うが、その目標を達成するために個人の自由や選択を犠牲にすることは望まない。

肉体的な満足を求めるのではなく、個人的な芸術性と表現の自由の見本となる。
]],
[race_ed_adv]=[[
多くのエルフは世界を探検したいという願望から冒険に乗り出し、忘れ去られたエルフの魔法を取り戻すために人里離れた領地を離れたり、祖先が数千年前に築いた失われた王国を探し求めたりする。

より広い世界を見たいという欲求は、成熟した経験豊かな人間になるための自然なこととして、彼らの社会に受け入れられている。そのようなエルフは、数十年後には再び故郷に戻り、財宝も世界観も豊かになって生活を始めることが期待されている。しかし、人間の中で育ったエルフにとって、故郷での生活は、友人や家族が急速に老いて死んでいくのを目の当たりにし、息が詰まることが多く、はかなく自由な冒険者の生活は、自然な魅力を秘めている。

エルフは比較的虚弱であるため、一般的に近接戦闘を避け、その代わりに射程距離で敵と交戦することを好む。ほとんどの者は、戦闘は必要であっても不愉快なものであると考え、できるだけ早く、できれば敵の匂いを嗅ぎ分けられるほど近づかずに終わらせることを好む。このような遠距離での戦闘を好む性質と、生まれつきの正確さ、アーケインの理解力が相まって、エルフはウィザードやレンジャーといったクラスを目指すようになる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
カラドレル,ヘルダレル,ランリス,メアドラレル,セルドロン,タラテル,ヴァリエル,ゾードロン。

<c=twa>女性名:</c>
アムルネララ,ダードララ,ファウンラ,ジャタール,メリシエル,オパラル,スムラル,テッサラ,ヤランドララ。
]],
}


s_drow="ドラウ"
s_drow_c="この浅黒い肌のエルフは、戦闘態勢に入ったポーズで立ち、髪は銀色、目は白く瞳孔が開いている。"
s_drow_fav_cls="男性のドラウは、兵士やスパイとして敵やその家の近くに身を置く武闘派や隠密系のクラスを好む。女性のドラウは一般的に、バードや特にクレリックのような、リーダーシップに適した職業に就く。男女ともにアーケインの才能があり、ウィザードやサモナーになることもある。"..add_hr("ドラウの得意クラスをウィザード（男性）またはクレリック（女性）からウィザードに一時的に変更。")
s_drow_traits=[[
<b c=tg>敏捷力+2、知力+2、魅力+2、 <c=tr>耐久力-2: </c></b>他のエルフに比べ、ドラウはエレガントで知的、不思議な魅力に溢れている。]]
.."\n\n"..xs_lbl("s_spl_res_11")
.."\n\n"..xs_lbl("s_res_spl_will_race_2")
.."\n\n"..[[
<b>武器の熟練度: </b>ショートソード、レイピア、ハンドクロスボウに熟練。<c=tr>この特性はハイエルフの武器熟練度に取って代わる。</c>

<b>感覚: </b><t=@pwr_darkvision_120 c=fc_b>夜目120フィート。</t> <c=tr>この特性は、ハイエルフの低照度視力を代替する。</c>]]
.."\n\n"..xs_lbl_r("s_lit_blind")
.."\n\n"..[[
<b>特別な資質: </b><t=@pwr_tox_drow c=fc_b>毒</t>。

<b>呪文に似た能力: </b>詠唱可<t=@pwr_sp_lt_0_dance c=fc_b>ダンシングライト</t>, <t=@pwr_sp_dk_2 c=fc_b>ダークネス</t>, <t=@pwr_sp_lt_1_fey c=fc_b>フェアリーファイア</t> 1日1回ずつ。呪文の使い手レベルはキャラクターレベルと等しい。
]]
s_drow_langs=[[
<b>自動習得言語: </b>共通語、エルフ語、地下共通語。
<b>ボーナス習得言語: </b>奈落語(アビサル)、水界語、竜語、ドラウ手話言語、ノーム語、ゴブリン語。

<c=twc>ドラウは共通語、エルフ語、地下共通語を話す。</c>
]]
s_drow_d=[[
地上のエルフの暗い反映であるドラウは、世界の光を消し去ろうとする影の狩人である。

ダークエルフとも呼ばれるドラウは、通常悪魔に仕える強力な魔法生物であり、その混沌とした性質だけが、彼らがさらに大きな脅威となることを阻止している。

堕落した虚無的な社会を捨て、英雄の道を歩む少数精鋭。
]]
s_drow_eds={
[race_ed_dd1]=[[
残酷で狡猾なドラウは、エルフの種族の暗黒の反映である。ダークエルフとも呼ばれる彼らは、サイクロペアの洞窟の岩で形作られた精巧な都市の地下深くに住んでいる。ドラウは地上のヒューマンにはめったに姿を見せず、伝説に留まりながら、代理人や諜報員を通して不吉な計画を進めることを好む。

ドラウは自分以外の誰にも愛情を持たず、他のクリーチャーを操ることに長けている。生まれつきの悪人ではないが、彼らの文化と社会には悪意が深く根付いており、不適合者が長く生き残ることはめったにない。

適切な状況が与えられれば、特に憎むべきエルフがドラウに変身するかもしれないという話もあるが、そのような変身には真に凶悪な人物が必要である。
]],
[race_ed_dd2]=[[
エルフとは血縁関係にあるが、ドラウは下劣で邪悪な従兄弟である。ダークエルフと呼ばれることもあるこの狡猾なクリーチャーは、地下世界の洞窟やトンネルを徘徊し、恐怖と力によって広大な地下都市を支配している。悪魔を崇拝し、遭遇するほとんどの種族を奴隷にするドラウは、地下世界で最も恐れられ、嫌われている住人である。

ドラウは地表に住む同族よりも背が低く、少し細身だが、それ以外は身体的に似ている。ドラウの皮膚は黒く、黒から霞んだ紫色まである。ほとんどのドラウは白髪か銀髪で、目は白か赤だが、他の色も珍しくない。

ドラウの社会は強力な貴族によって支配されており、虐待的で危険な家長によって統治されている。ドラウの大多数は一般兵と退廃した市民であり、基本ステータスはここに示した通りである。
]],
[race_ed_phy]=[[
ドラウの体格は人間に似ているが、華奢な体格とエルフの特徴（特徴的な長く尖った耳など）を持っている。

目は瞳孔がなく、通常白か赤である。ドラウの肌はコールブラックからくすんだ紫色まで幅広い。髪は白か銀が一般的だが、多少の違いはある。
]],
[race_ed_btl]=[[
戦闘において、ドラウは徹底的に冷酷で、公平さや慈悲をほとんど顧みない。

待ち伏せからの攻撃や、明らかに自分たちが優勢な状況に敵を誘い込むことを好む。ドラウは通常、矢に強力な毒を塗る。

事態が不利になると、ドラウはすぐに逃げ出し、奴隷や手下を残して逃走する。
]],
[race_ed_soc]=[[
ドラウの社会は伝統的に階級社会であり、母系社会である。男性のドラウは通常、外部の脅威から種族を守る武闘的な役割を果たし、女性のドラウは指導的で権威のある地位を占める。

このような性役割分担を強化するために、20人に1人のドラウが特別な能力を持って生まれ、その結果貴族とみなされる。

貴族の家はドラウの政治を規定し、各家は貴族の家長によって統治され、小家族、企業、軍団で構成される。各家はまた、魔王の支援者と関連している。

ドラウは個人の私利私欲と出世欲に強く突き動かされており、それが彼らの文化を陰謀と政治の渦巻くものに形成している。一般的なドラウは貴族の寵愛をめぐって争うし、貴族は暗殺、誘惑、裏切りの組み合わせによって権力を掌握する。
]],
[race_ed_rel]=[[
ドラウは人種的な優越感を強く持っており、非ドラウを奴隷とまだ奴隷でない者の2つのグループに分けている。

しかし実際には、同じような傾向を持つ種族（ホブゴブリンやオークなど）や、進んで奉仕する種族は奉仕種族として扱われ、ドラウ社会で一定の信頼とそこそこの地位が与えられることもある。ドワーフ、ノーム、ハーフリングのような他の種族は、鞭打ちにのみ適しているとみなされる。人を操るドラウは、ヒューマンの弱い性格を利用することに喜びを感じる。

最後に、ドラウのエルフに対する憎悪は、この種族を他のすべての種族から引き離すものであり、ダークエルフは地上の従兄弟のすべてを台無しにすることだけを望んでいる。
]],
[race_ed_aln]=[[
ドラウは権力と生存を重視し、生存を確保するためならどんな卑劣な選択も厭わない。結局のところ、彼らは逆境から生き残るだけでなく、逆境を征服するのだ。情けは無用で、古今東西の敵を容赦しない。

ドラウは強い感情と情熱というエルフの特徴を保持しているが、それを憎悪、復讐、権力欲、生々しい肉欲といった否定的な方向に向ける。その結果、ほとんどのドラウは混沌にして悪な存在となる。
]],
[race_ed_adv]=[[
征服者であり奴隷商人であるドラウは、領土を拡大することに躍起になり、その多くはエルフやドワーフの国々に古くからの恨みを晴らそうと、地表の権力を争う荒廃した場所で決着をつけようとする。

男性のドラウは、兵士やスパイとして敵やその家の近くに身を置く武闘派や隠密系のクラスを好む。女性のドラウは一般的に、バードや特にクレリックのような、リーダーシップに適した職業に就く。男女ともにアーケインの才能があり、ウィザードやサモナーになることもある。

ドラウは自然な反パラディンになれるが、女性貴族は自律的な本能を持ち、魔王と直接的な関係を持つ意志の強い男性という考えに不快感を覚えるため、男性はこの道を敬遠されることが多い。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アルカバト,ドロビッチ,フィリン,カエルムーン,ミレンディエ,ファーノックス,シレンドロス,ゾフ。

<c=twa>女性名:</c>
ベルマーニス,キュレリンス,イルヴァリア,ヨヒシス,ロスシヴィア,ティヴォルハン,ウルムブラルヤ,ヴォルンデイル。
]],
}


s_drow_n="ドラウ ノーブル"
s_drow_n_var_n="例外的なドラウ"
s_drow_n_var_d="特別な力を持って生まれた例外的なドラウであるドラウノーブルは、以下の例外を除き、ドラウのすべての人種的特徴を持っている。:"
s_drow_n_fav_cls="ドラウノーブルは圧倒的に女性が多く、クレリックのようなリーダーシップに適したクラスに就くのが一般的だ。"
s_drow_n_traits=[[
<b c=tg>敏捷力+4、知力+2、判断力+2、魅力+2、<c=tr>耐久力-2: </c></b>ドラウノーブルは非常に機敏で、観察力に優れ、威厳がある。

<b>呪文に似た能力: </b>詠唱可<t=@pwr_sp_lt_0_dance c=fc_b>ダンシングライト</t>, <t=@pwr_sp_dk_3 c=fc_b>ディープダークネス</t>, <t=@pwr_sp_lt_1_fey c=fc_b>フェアリーファイア</t>, <t=@pwr_sp_fear1 c=fc_b>コーズフィアー</t>, <t=@pwr_sp_false_life c=fc_b>フォルスライフ</t>そして、<t=@pwr_sp_shield_of_faith c=fc_b>シールドオブフェイス</t>各々は自由に使用できます。また、詠唱も可能です。<t=@pwr_sp_divine_favor c=fc_b>ディバインフェイバー</t>, <t=@pwr_sp_dispel c=fc_b>ディスペルマジック</t>そして、<t=@pwr_sp_hold_person c=fc_b>ホールドパーソン</t> 1日1回ずつ。呪文の使い手レベルはキャラクターレベルと等しい。{hr_splk}
]]
s_drow_n_hr_splk="ドラウノーブルはダンシングライト、ディープダークネス、フェアリーファイア、フェザーフォール、レヴィテイトをそれぞれ任意で唱えることができ、常時呪文のような能力としてディテクトマジックを持つ。また、ドラウノーブルはディヴァインフェイヴァル、ディスペルマジック、サジェスチョンをそれぞれ1日に1回唱えることができる。場合によっては、ドラウノーブルの呪文的能力は変化するかもしれないが、特定の呪文的能力のレベルは変化しない。ドラウノーブルの呪文的能力の呪文の使い手レベルはそのキャラクターレベルに等しい。"
s_drow_n_d=[[
20人に1人の割合で、生まれながらにして特別な力を授かっている。こうした例外的なドラウの圧倒的多数は女性で、その結果、ドラウの社会は母系制になる傾向がある。

このような特別な出産は支配者カーストの間で仕組まれ、奨励されており、母親が貴族の血筋である場合にはるかに起こりやすい。不思議なことに、父親の地位は、子供がドラウノーブルとして生まれる確率を増減させないようだ。

貴族との間に生まれた一般的なドラウの子どもは、通常死刑にされる。ドラウが崇拝する多くの魔神の1つに生け贄として捧げられるのだ。

ドラウノーブルが一般的な両親のもとに生まれることは稀であるが、そのような者は通常、自分の卑しい生い立ちの真実を隠すため、そして社会の貴族の家系のひとつに加わる過程を容易にするために、成人する前に両親や家族を殺害する。

ドラウノーブルはその近親者の大多数よりも権力が強く、そのため彼らはすぐに家の中で権力を握るようになる。ドラウ貴族の出世は通常、暗殺、誘惑、裏切りの組み合わせによって達成されるため、権力を持つほとんどのドラウは過剰な猜疑心を持つようになる。
]]


s_hfe			= "ハーフ エルフ"
s_hfe_d			= [[
ハーフエルフはしばしば祖先の種族との間に挟まれ、優美さと矛盾を併せ持つ種族である。

その二重の遺産と天賦の才能は、しばしば優秀な外交官や平和主義者を生み出すが、ハーフエルフはしばしば強烈で憂うつな孤独に陥りやすい。
]]
s_hfe_eds={
[race_ed_dd1]=[[
エルフは長い間、他の種族の羨望のまなざしを集めてきた。その大らかな寿命、魔法との親和性、生まれつきの優美さは、それぞれ隣人たちの賞賛や辛辣な羨望の的となっている。しかし、彼らの特徴の中で、その美しさほど人間の仲間を魅了するものはない。両種族が最初に接触して以来、人間はエルフを肉体的な完璧さの模範とし、これらの公正な民に自分自身の理想化された姿を見てきた。一方、多くのエルフは、人間が比較的野蛮であるにもかかわらず、魅力的であると感じ、若い種族のメンバーが短い人生を生き抜く情熱と衝動に惹かれている。

このような相互の熱愛が恋愛関係に発展することもある。通常、人間の基準からしても短命ではあるが、そのような逢瀬が、2つの文化の末裔でありながらどちらの文化も受け継がない種族、ハーフエルフの誕生につながることもある。ハーフエルフは互いに繁殖することができるが、"純血"のハーフエルフでさえ、人間やエルフからは私生児とみなされる傾向がある。運命と嘲笑の狭間にあるハーフエルフは、しばしば自らを世界の中間子とみなす。
]],
[race_ed_dd2]=[[

]],
[race_ed_phy]=[[
ハーフエルフは人間より背が高く、エルフより背が低い。エルフの血統を受け継ぐ痩せた体格と美しい顔立ちを持つが、肌の色は通常人間側の色である。

ハーフエルフはエルフの尖った耳を残しているが、その耳はより丸みを帯びており、あまり目立たない。彼らの目は人間のような形をしているが、琥珀色や紫色、エメラルドグリーンや深い青色など、特殊な色彩を持つ。

しかし、ドラウの血を引くハーフエルフの場合はこのパターンが変わる。そのようなエルフは、ほとんど例外なくドラウの親の白髪か銀髪を持ち、多くの場合、くすんだ灰色の肌を持ち、光が当たると紫がかった、あるいは青みがかった色になる。
]],
[race_ed_soc]=[[
統一された祖国や文化がないため、ハーフエルフはほとんどどのような環境にも適合できる万能性を保たざるを得ない。ハーフエルフは両親と同じ理由で両方の種族から魅力的な存在とみなされることが多いが、ハーフエルフが人間やエルフのどちらにもなじむことはめったにない。このような受け入れられなさが多くのハーフエルフに重くのしかかるが、その一方で、正式な文化を持たないことに究極の自由を見出し、そのユニークなステータスに支えられている者もいる。その結果、ハーフエルフは驚くほど順応性が高く、どのような社会に身を置いても自分の考え方や才能を適応させることができる。

片方の血統を歓迎されるハーフエルフであっても、しばしば文化の狭間に立たされることがある。多くのハーフエルフは、このような任務が自分の価値を両種族に証明するチャンスであると考え、積極的に参加する。しかし他の者は、両種族から押しつけられる圧力や思い込みに憤慨するようになり、人間とエルフの間で権力を仲介したり、和平を結んだり、交易を進めたりする機会を、個人的な利益のために利用するようになる。
]],
[race_ed_rel]=[[
ハーフエルフは孤独を理解し、性格が人生経験よりも種族によって左右されることが多いことを知っている。そのため、他の種族との友情や同盟に寛容であることが多く、新しい知人に対して第一印象を頼りに意見を述べることは他の種族よりも少ない。

多くの種族が混血し、ハーフオーク、ハーフドラゴン、ハーフフェンドなど、注目すべき力を持つ混血児を生み出す中、ハーフエルフはその祖先や世界の他の種族の目から見ても特異な位置にあるようだ。エルフを敬愛する人間たちは、ハーフエルフを2つの種族をつなぐ架け橋と見なしている。しかし、このような態度はしばしばハーフエルフに不当な期待や高い基準を押し付け、他人が設定した壮大な運命に沿えないとすぐに嘲笑に変わる。さらに、エルフに育てられたハーフエルフや、エルフの仲間になったハーフエルフは、両親の半分が人間であることを単なる障害とされ、エルフの道に没頭し、適切な教育を受ければ克服できるものとされることが多く、最も善意あるエルフの指導者であっても、しばしばハーフエルフの部下に、自分自身を「向上」させるために、自分自身の半分を拒絶するよう迫る。ただし、人間とドラウの間に生まれたハーフエルフは例外である。一般的なハーフオークとは異なり、そのようなハーフエルフは暴力と残忍性から生まれるのが普通である。さらに、ハーフドラウの身体的特徴は明らかに彼らの親であることを示すため、血筋ではなく行いや性格に基づいた評判を作り上げることは、彼らにとってより困難なことである。最も共感的なハーフエルフでさえ、ハーフドロウを見ると尻込みする。

他の種族の中でも、ハーフエルフはユニークで、しばしば予期せぬ絆を結ぶ。ドワーフは伝統的にエルフに不信感を抱いているにもかかわらず、ハーフエルフの親が人間であることを希望に満ちたこととして捉え、ハーフエルフというよりむしろハーフヒューマンとして扱う。さらに、ドワーフは長命だが、がっしりとしたこの民族の寿命は、両親の寿命よりもハーフエルフの寿命に近い。その結果、ハーフエルフとドワーフは、友情であれ、ビジネスであれ、あるいは競争上のライバル関係であれ、永続的な絆を結ぶことが多い。

ノームやハーフリングはハーフエルフを好奇の目で見ることが多い。自分たちが社会の片隅に追いやられ、本当に居場所のないハーフエルフは、一般的にノームやハーフリングを軽薄で軽蔑に値すると感じるが、彼らの一見のんきなやり方を密かに羨ましく思う。利口で進取の気性に富むノームやハーフリングは、時にハーフエルフと組んで冒険や事業を行うことがある。

ハーフエルフとハーフオークの間には、おそらく最も奇妙で二律背反的な関係が存在する。非人間的な親族の中で育ったハーフオークとハーフエルフは、通常、互いを憎むべき古くからの敵として見ている。しかし、社会から疎外されてきたハーフエルフは、ハーフオークに深い親近感を抱き、その外見と少々残忍な性質のために、彼らの重荷がより重くのしかかることを知っている。すべてのハーフオークがそのような共感を理解できるわけではないが、そのようなハーフオークはしばしば献身的な外交官、連絡係、謝罪係となる。ハーフオーク自身は、ボディーガードや威嚇役など、その屈強な体格に適した役割を担って恩返しをするのが一般的である。
]],
[race_ed_aln]=[[
ハーフエルフは孤立しているため、その性格や哲学に強い影響を与える。残酷さは彼らにとって自然なことではなく、社会に溶け込むことも、社会の慣習に従うこともできない。

ハーフエルフには統一された文化がないため、宗教に傾倒することは少ないが、宗教に傾倒する者は概して祖国の一般的な信仰に従う。また、信仰や聖職者の働きによって共同体の一員であると感じられるようになった場合は特にそうである。

ハーフエルフの中には、信仰なものに引け目を感じながらも、社会の正式な宗教的指導を超えて生きている者もいる。そのような者はしばしば、自由、調和、均衡のような観念や概念、あるいは世界の原初的な力を崇拝する。また、長い間忘れ去られていた神々に惹かれ、神々でさえも見過ごすことができるという考えに安らぎと親近感を見出す者もいる。
]],
[race_ed_adv]=[[
ハーフエルフは旅人となる傾向があり、最終的に故郷と呼べる場所を求めて各地を放浪する。地域社会で自分自身を証明し、個人的な自己認識、あるいは遺産を確立したいという欲求が、多くのハーフエルフの冒険者を勇敢な生き方へと駆り立てる。

ハーフエルフの中には、長寿であるにもかかわらず、エルフよりも人間に近い時間の経過を感じ、人生の早い段階で富や権力、名声を手に入れ、残りの年月をそれを享受するために費やすと主張する者もいる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
カラテス,エンシナル,イラドリ,カイラス,ナルシソ,クインレイ,セルティエル,ジルール。

<c=twa>女性名:</c>
カトラン,エルスベス,イアンドリ,キーヤンナ,リアルダ,マデラ,レダ,タマリー。
]],
}


s_dwf			= "ドワーフ"
s_dwf_d			= [[
背が低くがっしりとした体格で山岳要塞を守る彼らは、しばしば厳格でユーモアがないと見られがちだ。

大地の宝を採掘し、鉱石や宝石から見事なアイテムを作り上げることで知られる彼らは、深き大地の恵みに対して比類なき親和性を持っている。

ドワーフはまた、伝統主義と孤立主義の傾向があり、それが時に外国人恐怖症として現れる。
]]
s_dwf_eds={
[race_ed_dd1]=[[
ドワーフはストイックだが厳格な種族であり、山の中心から切り開かれた都市に居を構え、オークやゴブリンのような野蛮な種族の略奪を断固として退けている。他のどの種族よりも、ドワーフは気難しくユーモアのない大地の職人という評判を得ている。彼らは高い山々や地底の危険な領域に住み、常に巨人やゴブリン、その他のそのような恐怖と戦争しているからである。

ドワーフは歴史と伝統を愛し、寿命が長いため、態度やスタイル、流行、傾向の世代交代が、寿命の短い種族に比べてはるかに少ない。壊れていないものは直したり変えたりせず、壊れているものは取り替えるのではなく直す。原則的に倹約家であるドワーフは、本当にダメになって直せないものでない限り、何かを捨てることを嫌う。同時に、ドワーフは細部までこだわり、職人技の耐久性にはほとんど執着しないため、彼らが作るものは長持ちするように作られているため、そのようなことはめったに起こらない。その結果、ドワーフによって作られた建物、芸術品、道具、家庭用品、衣服、武器、その他事実上あらゆるものが、他の種族であればそのようなものが博物館の展示品や埃をかぶった骨董品の棚、あるいは廃品置き場の肥やしに追いやられるような時代になっても、いまだに普通に使われている。これらの特徴を総合すると、ドワーフは時が止まった種族という印象を与える。

ドワーフは思慮深く想像力に富み、実験を厭わないが、常に新しい技術や製品を改良し、完成させてから次の技術に移る。ドワーフは冶金学、石工学、工学において、他の種族の技術的進歩を常に凌駕する偉業を成し遂げてきたが、ドワーフ以外の種族の中には、同じ目的を達成するために、平凡な手段ではなく神秘的な手段で自らの創造物を補い、完成させるために魔法を用いる者もいる。ドワーフはまた、頑固な勇気と、危険を顧みず最後までやり遂げる献身に代表される種族でもある。このような特徴から、ドワーフは他の種族なら挫折して撤退してしまうような極限の環境でも探検し、定住するようになった。冥界の最も暗い深部から最も高い山頂まで、荒涼とした岩だらけの海岸沿いの錆びついた鉄の城塞から密林のこぢんまりとしたジッグラトまで、ドワーフは自分たちの飛び地や堡塁を築き、あらゆる来襲者に対抗し、あるいは最後まで滅びて、彼らの遺産として不朽のモニュメントだけを残してきた。

ドワーフは冒険心や創意工夫に欠けると言われるが、それよりも、引き受けた仕事や採用した変更に集中力と献身を保ち、そのような変更を心から採用する前に徹底的に吟味すると言った方が正確だろう。新しい状況や新しい要求に直面したときは、あらゆる状況に対して斬新な解決策を編み出そうとするのではなく、可能な限り既存の方法を使用し、試行錯誤を重ねた道具や技術を体系的に適用することで対応する。しかし、必要であれば、邪魔になる障害物を取り払うための次の完璧な手順を開発することに全力投球する。目的を達成した後は、新たな領土や概念の前進を固めることに集中する。そのため、ドワーフが無理をすることはめったにないが、主導権を握ったり、自分が作り出した利点を最大限に生かしたりする機会を逃すこともある。
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
ドワーフは背が低くがっしりした種族で、普通の人間より1フィートほど低い。

男性も女性もドワーフは髪の長さを誇り、男性は髭を様々な留め具や複雑な三つ編みで飾ることが多い。男性ドワーフの髭の剃り残しは狂気の兆候である。
]],
[race_ed_btl]=[[
ドワーフは戦闘のエキスパートであり、環境を効果的に利用し、綿密に計画された集団攻撃を実行する。

ドワーフにはウィザードやソーサラーがほとんどいないため、戦いで魔法を使うことはほとんどない（しかし、ドワーフのクレリックは仲間の戦士と同様に戦いに身を投じている）。

準備する時間があれば、落とし穴や石を使った罠を作ることもある。

ドワーフはウォーアックスとスローイングハンマーに加えて、ウォーハンマー、ピック、ショートボウ、ヘヴィクロスボウ、メイスも使う。
]],
[race_ed_soc]=[[
ドワーフの山小屋間の距離が遠いことが、彼らの社会に存在する文化の違いの多くを物語っている。

このような分裂にもかかわらず、世界中のドワーフは石細工を愛し、石や金属を使った職人技や建築に情熱を注ぎ、巨人やオーク、ゴブリノイドを激しく憎むという特徴を持っている。これらの種族が特殊、あるいは聞いたことがない地域のような辺境の地では、ドワーフは安全と安心に執着し、かなり喧嘩っ早い性格と相まって、どこに定住しても敵か、少なくともライバルを見つけることになる。

ドワーフは正確には軍国主義者ではないが、斧を持たない者はドワーフによって切り刻まれることを大昔に学んだため、ドワーフはどこでも武力によって自分たちの権利や主張を行使する用意があるように教育されている。ドワーフは交渉に我慢の限界に達したとき、躊躇なく "攻撃的な交渉 "を行う。"
]],
[race_ed_rel]=[[
ドワーフとオークは長い間互いに近接して暮らしており、両種族と同じくらい古い暴力の歴史を共有している。ドワーフは一般的にハーフオークに不信感を抱き、敬遠する。

エルフ、ノーム、ハーフリングは、か弱く、気まぐれで、"かわいい"存在であり、尊敬に値しないと考えている。

ドワーフが最も強い絆で結ばれているのは人間であり、人間の勤勉な性質と豊かな食欲がドワーフの理想に最も近いからである。
]],
[race_ed_aln]=[[
ドワーフは名誉と伝統を重んじる。

彼らはしばしば距離を置いたとされていますが、彼らには強い友情と正義の感覚があります。彼らの信頼を勝ち取った者は、彼らが一生懸命働く一方で、特に良いエールが絡む時はより一層楽しむことを理解しています。

ほとんどのドワーフは善良である。
]],
[race_ed_adv]=[[
ドワーフの冒険者は人間に比べれば稀ではあるが、世界のほとんどの地域で見かけることができる。ドワーフは一族の栄光を求め、生まれ故郷の要塞を豊かにするための富を求め、あるいは種族の敵から陥落したドワーフの城塞を取り戻すために、しばしば堡塁を離れる。

ドワーフの戦いはトンネルでの戦闘や近接戦闘が特徴で、そのためほとんどのドワーフはファイターやバーバリアンといったクラスに属する傾向がある。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
ドルグリン,グルニャール,ハルスク,カズムク,モルグリム,ローガール。

<c=twa>女性名:</c>
アグナ,ボディル,イングラ,コトリ,ルシルカ,ヤンリット。
]],
}


s_dwf_u="デュエルガー"
s_dwf_u_c="このハゲでヒゲの長いドワーフは、くすんだグレーの肌、低いアーチ型の眉、光を反射するのではなくむしろ吸収しているような目をしている。"
s_dwf_u_traits=[[
<b c=tg>耐久力+2<c=tr>魅力-4: </c></b>デュエルガーは気性が荒いが、好戦的でもある。]]
.."\n\n"..xs_lbl_post_r("s_dwf_u_imms", "この特性は、ヒルドワーフの毒に対するセーヴィングスローの種族ボーナス＋2に取って代わる。")
.."\n\n"..[[
<b>隠密: </b>静かな移動判定に+4の種族ボーナス。

<b>鋭敏な感覚: </b>視認と聞き耳の判定に種族ボーナス+1。

<b>感覚: </b><t=@pwr_darkvision_120 c=fc_b>夜目120フィート。</t> <c=tr>この特性は、ヒルドワーフの夜目能力（60フィート）に取って代わる。</c>]]
.."\n\n"..xs_lbl_r("s_light_sensitivity")
.."\n\n"..[[
<b c=tr>-武器の熟練度: </b>他のドワーフとは異なり、デュエルガーはドワーフウォーアックスとドワーフウルグロッシュという武器に精通していない。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_bulls_strength c=fc_b>ブルズストレングス</t>と<t=@pwr_sp_protection_from_arrows c=fc_b>プロテクションフロムアロー</t> デュエルガーのクラスレベルの2倍のウィザード（最低呪文の使い手レベル3）として1日1回ずつ、これらの能力はデュエルガーとその持ち物にのみ影響する。{hr_splk}
]]
s_dwf_u_hr_splk="エンラージパーソン,インビジビリティ。"
s_dwf_u_langs=[[
<b>自動習得言語: </b>共通語、ドワーフ語、地下共通語。
<b>ボーナス習得言語: </b>竜語、ジャイアント語、ゴブリン語、オーク語、地界語。

<c=twc>デュエルガーはドワーフ語、共通語、地下共通語を話す。</c>
]]
s_dwf_u_d=[[
灰色ドワーフと呼ばれることもあるデュエルガーは、地下深くの集落に住み、同族の中でもより暗く、より歪んだ姿をしている。

ドワーフとデュエルガーはかつて一つの種族であったが、ドワーフは山の砦のために深淵を去った。デュエルガーは今でも自分たちこそが真のドワーフであり、地底のすべてのものの正当な継承者であると考えている。

この邪悪な存在は、肌の白いいとこたちを憎んでいる。彼らは他のドワーフと戦争し、時折他の地底生物と手を組むことさえある。デュエルガーは人生を死によってのみ終わる絶え間ない労苦とみなしている。
]]
s_dwf_u_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
外見は灰色の肌のドワーフに似ており、ひげを生やしているが禿げており、冷たく光のない目をしている。

皮膚は埃や灰でこすられたようなくすんだ灰色だが、これは地下の環境に溶け込むための自然な色合いである。

ほとんどのデュエルガーは（女性でさえも）ハゲであり、石に溶け込むようにデザインされた質素な服装をしている。隠れ家では宝石を身につけることもあるが、それは常にくすんだものである。
]],
[race_ed_btl]=[[
戦闘では、デュエルガーは遠くからクロスボウを撃ち、数ラウンド後にウォーハンマーに移行する。多勢に無勢、あるいは十分な脅威を与えられた場合、デュエルガーは呪文のような能力を使い、敵に怒りをぶつけ始める。

彼らは乱暴な殺戮よりも戦闘で捕虜を取ることを好みますが、地上のドワーフだけはためらいなく殺されます。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
ドワーフの従兄弟であるデュエルガーは、地下の領域への侵入者を嫌う気性の荒いクリーチャーである。彼らは光の届かない地下の洞窟に住んでいる。彼らは太陽の下に住むすべての種族を憎んでいるが、その憎悪は地表に住むドワーフの従兄弟に対する憎悪に比べれば微々たるものである。

彼らは奴隷商人の一族ですが、非ドワーフの捕虜は通常、骨の折れるような仕事に従事させられますが、ドワーフの捕虜は一般的に即座に殺されます。
]],
[race_ed_aln]=[[
このドワーフは一般的に邪悪で、下劣で残酷としか言いようがないが、名誉を重んじ、約束を守ることは彼らにとってすべてであり、まれに忠実な冒険仲間になる者もいる。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_gnm			= "ノーム"
s_gnm_d			= [[
フェイという見知らぬ土地から移住してきたこの小さな民族は、気まぐれで風変わりな行動で知られている。

多くのノームは気まぐれな職人であり、魔法や錬金術、風変わりな想像力を動力源とする奇妙な装置を作り出すいじくり屋である。

ノームは新しい経験に対する飽くなき欲求を持っており、しばしばトラブルに巻き込まれる。
]]
s_gnm_eds={
[race_ed_dd1]=[[
ノームはフェイの遠い親戚であり、その歴史は彼らがフェイの神秘的な領域に住んでいた時代を物語っている。未知の力が古代のノームをその領域から追い出し、この世界に避難することを余儀なくされた。にもかかわらず、ノームはフェイのルーツを完全に捨てたり、人間の文化に適応したりすることはなかった。それにもかかわらず、ノームはフェイのルーツを完全に捨てたり、人間の文化に適応したりすることはなかった。ノームはもはや真のフェイではないが、そのフェイの遺産は彼らの生来の魔法の力、しばしば気まぐれな性格、人生や世界に対する考え方に見ることができる。

ノームは他の種族と同じような心配事や動機を持っていることもあるが、ノーム以外の種族から見ればよくても風変わりで、悪く言えばナンセンスとしか思えないような情熱や欲望に突き動かされていることもよくある。ノームは巨人の食卓の料理を味わうために命を賭けるかもしれないし、今までで一番低い場所だからという理由で穴の底に到達するかもしれないし、ドラゴンに冗談を言うかもしれない。ノームにとって、これらの目標は新しい呪文を研究したり、莫大な富を得たり、強力な悪の勢力を鎮圧したりするのと同じくらい価値がある。このような一見気まぐれで衝動的な行動はノームに普遍的なものではないが、種族全体としては十分に一般的であり、せっかちで少なくとも少し気が狂っているという評判を得ている。

小柄な体格、鮮やかな色彩、他人の意見を気にしない性格も相まって、ノームは他の種族から異質で奇妙な存在として広く見なされている。ノームは逆に、他の一般的で文明的な種族がいかに似ているかにしばしば驚かされる。ノームにとっては、人間とエルフに多くの共通点があることの方が、ノームにないことよりも不思議に思えるのだ。実際、ノームはしばしば、ノームでないすべての者を、ノームでない単一の広大な集団種族の一部とみなして味方を困惑させる。
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
ノームは一般的な種族の中では最も小さい部類に入り、一般的に身長は3フィート（約1.5メートル）強である。しかし、その小さな体にもかかわらず、ノームは非常に回復力があり、多くの敵が想定しているほど弱くはない。その小柄な体格のために素早く動く能力は低いが、ノームは特に自分よりはるかに大きな敵と戦うときに、その体格を生かす訓練をすることが多い。

ノームの色調は実に様々であるため、多くの部外者はノームが一般的に染料やイリュージョンを使って肌や髪の色調を変えていると思い込んでいる。確かにノームは化粧品で美を磨くことはしないが（どれだけ奇抜に見えるかを見るために外見を変えたいと思うかもしれない）、彼らの自然な色合いは実に虹色の範囲に及ぶ。彼らの髪は、秋の葉の燃えるようなオレンジや、春の森の青々とした緑、咲き誇る野草の深い赤や紫など、鮮やかな色になる傾向がある。同様に、肌の色も土のような茶色から花のようなピンクまで幅広く、黒やパステルブルー、あるいは緑の肌を持つノームも珍しくない。ノームの色彩は遺伝をほとんど考慮しておらず、ノームの両親や他の親族の色はノームの外見に明白な関係はない。

ノームは非常に変わりやすい顔立ちをしており、そのプロポーションは他の人型生物種族の標準とは一致しないことが多い。多くのノームは口と目が大きすぎる。また、極端に小さな顔立ちのノームもいれば、衝撃的なほど大きな目に、小さくすぼまった口と尖った鼻が混在しているノームもいる。ノームは自分の顔立ちに誇りを持ったり、恥ずかしがったりすることはほとんどないが、他の種族はしばしばノームの最も目立つ特徴に執着し、侮辱や愛着の対象として利用しようとする。
]],
[race_ed_btl]=[[
ノームは直接対立よりも、見せかけと欺瞞を好む。

彼らは（ゴブリンやコボルド以外の）敵を撃破するよりも、撹乱させたり恥ずかしい思いをさせたりしたいと思っています。

ノームは幻惑魔法を多用し、周到に準備された待ち伏せや罠を隙あらば仕掛けてくる。
]],
[race_ed_soc]=[[
一般的な種族とは異なり、ノームは通常、古典的な社会構造の中で自己を組織しません。ノームの都市は珍しく、ノームの王国はほとんど知られていません。さらに、多数のノームが他の種族と共存している場合でも、ノームは特定の地区に集まる傾向がありません。ノームが社会に与える潜在的な影響を抑えるための特定の法律は「ノーム区」を必要とする場合もありますが、社会的な圧力により、高いノーム人口の地域から全ての非ノーム人が離れることがある一方で、ノームは自分たちの手段で、自分たちを許可してくれるコミュニティ全体に均等に広がる傾向があります。

しかし、ノームが集団としてコミュニティ内で一般的であっても、個々のノームは常に移動している傾向がある。元来気まぐれな生き物である彼らは、通常一人で、あるいは一時的な仲間と旅をし、常に新しい、よりエキサイティングな経験を求めている。彼ら自身や他の種族のメンバーと永続的な関係を築くことはほとんどなく、代わりに熱狂に近い情熱をもって工芸品や職業、コレクションを追求する。ノームがある地域に定住したり、ある集団に長期滞在したりする場合は、ほとんどの場合、その地域がノームが身を捧げてきた職業やこだわりに対して何らかの恩恵を与えた結果である。

非常に多様な背景を持ち、統一された故郷がないにもかかわらず、ノームはいくつかの共通の文化的特徴を持っている。男性ノームは変わった帽子や頭飾りを好み、しばしば最も高価で仰々しい頭飾りを身につける。女性はほとんど頭を覆わないが、宝石のついた複雑な櫛や頭飾りを使った、手の込んだ風変わりなヘアスタイルを誇らしげにする。
]],
[race_ed_rel]=[[
ノームは他の種族と感情的にも物理的にも交流するのが難しい。多くの点で、他の種族がノームを奇妙に見ているという事実そのものが、ノームにとって他の種族の最も奇妙な点であり、これが理解と関係を築くための共通の基盤の欠如につながる。2人のノームが互いに出会うとき、彼らは一般的に、彼らの信念や伝統がどんなに異なっていても、何らかの互恵的な取り決めに達することができると考える。そうでないことが判明しても、ノームたちは互いの取引に共通点を探し続ける。他の種族がノームと接するときに同じ努力をすることができないか、する気がないことは、ほとんどのノームにとっていらだたしいことであり、混乱させることでもある。

多くの点で、ノームが一見何のつながりもないように見えるさまざまな考えと強く結びついていることが、他の種族が彼らと関係を築くことを難しくしている。例えば、ノームのユーモアは、しばしば肉体的ないたずらや、無意味な韻を踏んだあだ名、あらゆる信憑性を疑わせるようなとんでもない嘘を他人に信じ込ませようとする努力に重点が置かれている。ノームはそのような努力をヒステリックに面白がるが、彼らのいたずらはしばしば他の種族には悪意や無意味なものと映り、逆にノームは背の高い種族を鈍重でのろまな巨人と考える傾向がある。

ノームはハーフリングや人間とそれなりにうまくやっていける。彼らは少なくとも、ノームらしい奇妙なユーモアの伝統を持っている。ノームは一般的に、ドワーフやハーフオークにはもっと明るくなる必要があると感じており、気難しい種族には理解できないようなトリックやジョーク、とんでもない話で彼らの生活に明るさをもたらそうとしている。ノームはエルフを尊敬しているが、長命な種族のメンバーが決断を下すペースが遅いことに苛立ちを覚えることが多い。ノームにとって、行動しないよりは行動したほうがいいに決まっており、多くのノームは休息時間中も自分たちを楽しませるために、常にいくつかの高度に関与したプロジェクトを持ち歩いている。
]],
[race_ed_aln]=[[
ノームは衝動的なトリックスターであり、時に不可解な動機と同様に不可解な方法をとるが、彼らの心はおおむね正しい場所にある。

ノームでない人には悪意ある行為に見えるかもしれないが、それは新しい知り合いに新しい経験を紹介するための努力である可能性が高い。

ノームは感情の起伏が激しく、自然界の中で最も平穏な生活を送ることができる。
]],
[race_ed_adv]=[[
ノームは放浪癖があり、好奇心が旺盛で、奇妙な技術やアーケインの技術、言語を習得したがるため、天性の冒険家である。冒険者が直面する数え切れないほどの危険ほど斬新なものはないからだ。多くのノームは冒険を唯一の生きがいと考え、冒険を体験すること以外の動機はないと考えている。

また、自分の選んだ職業に関係する失われた伝承や資料を見つけたいと願い、ドラゴンの宝庫や古代の遺跡にしか必要な伝承はないと信じているノームもいる。その結果、パン職人や織物職人だと考えているノームが、魔道士や斥候だと宣言しているノームと同じように立派な冒険者になることもある。

ノームは多くの種族に比べて身体的に弱く、これを人生の単純な事実としてとらえ、それに応じて計画を立てる。ほとんどの冒険者ノームはその弱点を魔術や呪歌で補っており、また錬金術や特殊武器で戦いを有利に進める者もいる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アブロシュトール,バスターグレ,ハルンガロム,クロルムナイト,ポッシュメント,ザルズケット,ザトクォルミー。

<c=twa>女性名:</c>
ベシュ,フィジット,リニ,マジェ,ネジ,パイ,クエック,トリッグ。
]],
}


s_gnm_s="スヴァーフネブリン"
s_gnm_s_c="このハゲのノームは岩のような灰色の肌を持ち、ひょろひょろとした体格をしている。青白い目は大きく、表情豊かだ。"
s_gnm_s_fav_cls="スヴァーフネブリンは隠密性が高く、素早く、観察力に優れており、ローグという職業が自然に身につく。"
s_gnm_s_traits=[[
<b c=tg>敏捷力+2,判断力+2, <c=tr>筋力-2,魅力-4: </c></b>スヴァーフネブリンは素早くて観察力に優れているが、比較的弱く、感情的に距離を置いている。]]
.."\n\n"..xs_lbl("s_spl_res_11")
.."\n\n"..xs_lbl_post_r("s_save_race_2"	,"この特性は、ロックノームの幻惑に対するセーヴィングスローの種族的ボーナスに取って代わる。")
.."\n\n"..xs_lbl_post_r("s_ac_dodge_4"	,"この特性は、ジャイアントに対するロックノームの回避ボーナスに取って代わる。")
.."\n\n"..xs_lbl_2("s_stonecunning"		,"ドワーフ同様、ディープノームも石工に関する第六感を持っている。")
.."\n\n"..[[
<b>極意: </b>隠れ身判定に+2の種族ボーナス、地下では+4に向上する。

<b>感覚: </b><t=@pwr_darkvision_120 c=fc_b>夜目120フィート。</t>と<t=@pwr_low_light_vision c=fc_b>低照度視覚</t>。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_blindness_deafness c=fc_b>ブラインドネス/デフネス</t>、<t=@pwr_sp_blur c=fc_b>ブラー</t>、<t=@pwr_sp_doom c=fc_b>ドゥーム</t> 1日1回ずつ。呪文の使い手レベルはキャラクターレベルと等しい。セーヴ難易度(DC)は魅力ベースで、＋4の種族修正を含む。{hr_splk}

<b>探知阻止（超能力）: </b>連続的<t=$s_pwr_nondetection_nd c=fc_b>探知阻止</t>能力を呪文として使用する。呪文の使い手レベルはキャラクターレベルに等しい。
]]
s_gnm_s_hr_splk="ブラインドネス/デフネス,ブラー,変装。"
s_gnm_s_langs=[[
<b>自動習得言語: </b>共通語、ノーム語、地下共通語。
<b>ボーナス習得言語: </b>ドワーフ語、エルフ語、ジャイアント語、ゴブリン語、オーク語、地界語。
 
<c=twc>スヴァーフネブリンはノーム語、共通語、地下共通語を話す。</c>
]]
s_gnm_s_d=[[
ディープノームとも呼ばれるスヴァーフネブリンは、ノーム族から派生した隠遁者である。彼らは地下深くの大きな都市に住んでいると言われている。彼らは天敵から身を守るため、これらの都市の場所を秘密にしている。

スレートグレーの肌をした真面目なクリーチャーであるこのノームは、地上の従兄弟たちとは大きく異なり、陰の深みに住むことを選択し、彼らの部屋、丸天井、トンネルを共有する不潔なクリーチャーから上の世界を守っている。

彼らは地下の環境を共有する邪悪なクリーチャーの魔法に耐性があり、強力な保護魔法を行使する。
]]
s_gnm_s_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
スヴァーフネブリンはひょろひょろとした岩のような色をした皮膚をしており、通常は中褐色から茶色がかった灰色をしている。オスはハゲで、メスは筋張った灰色の毛が生えている。

スヴァーフネブリンの平均寿命は250歳。
]],
[race_ed_btl]=[[
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
スヴァーフネブリンはノーム族の分派で、隠遁生活を送っている。彼らはダークエルフや他の地下種族から安全な、隠れた都市の地下に住んでいる。

スヴァーフネブリンは部外者に不信感を抱き、近づくと身を隠すことが多い。スヴァーフネブリンは、表層の従兄弟たちが気まぐれであるのと同様に、真面目である。

スヴァーフネブリンは不気味なフェイの領域との結びつきが、地表に住むノーム族のそれよりもはるかに強く、そのため感情から奇妙に切り離されるか、暴力的に突発的になる。

スヴァーフネブリンは長い間デュエルガーと戦争をしてきたため、デュエルガーと他のドワーフの違いを見分けるのが難しい。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_hfl			= "ハーフリング"
s_hfl_d			= [[
この小さな種族のメンバーは、家族、コミュニティ、そして生来の無尽蔵とも思える幸運に強さを見出している。

その旺盛な好奇心は、時に本質的な常識と相反することもあるが、ハーフリングは永遠の楽天家であり、最悪の状況を切り抜ける驚異的なコツを持つ狡猾な日和見主義者である。
]]
s_hfl_eds={
[race_ed_dd1]=[[
楽観的で陽気な性格で、不思議な幸運に恵まれ、強い放浪欲に駆られるハーフリングは、その小柄な体格を補って余りある勇敢さと好奇心の持ち主である。興奮しやすく、またのんびり屋でもあるハーフリングは、平静を保ち、チャンスを逃さないことを好む。大惨事に見舞われても、ハーフリングはユーモアのセンスを失うことはほとんどない。どんなに悲惨な状況であっても、不条理なことにユーモアを見出すことができるため、ハーフリングは自分を取り巻く危険から少し距離を置くことができる。このような感覚は、味方を動けなくするような恐怖から身を守るのにも役立つ。

ハーフリングは根っからの日和見主義者である。彼らはどんな状況も有利に転じられると固く信じており、物事がうまくいかなくなったときに脱出するための確固とした計画もなく、嬉々としてトラブルに飛び込むこともある。世界の厳しさから物理的に身を守ることができないことも多く、風と共に去り、いつ身を隠すべきかを心得ている。しかし、ハーフリングの好奇心はしばしばその良識を圧倒し、判断を誤ったり、間一髪のところで逃げ遅れたりする。過酷な経験がハーフリングに用心深さを教えることはあっても、彼らが自分の運を完全に信じなくなったり、宇宙は奇妙な方法で自分たちを楽しませるために存在し、決して自分たちに危害を加えることを許さないと信じることをやめたりすることはほとんどない。

好奇心旺盛で新しい場所や経験を求めるハーフリングだが、家庭を大切にする気持ちも強く、家庭生活の快適さを高めるために身の丈以上の出費をすることも多い。ハーフリングが贅沢で快適な生活を楽しんでいるのは間違いないが、彼らには自分の家をショーケースにしたいという強い理由もある。住まいを改善するために時間、お金、エネルギーを費やすこの衝動は、見知らぬ人への敬意と愛する人への愛情の表れだとハーフリングは考えている。血のつながった親族のためであれ、大切な友人のためであれ、賓客のためであれ、ハーフリングは自分の家を美しくすることで、中に迎える人々への気持ちを表現する。旅をしているハーフリングも、ワゴンを飾ったり、キャンプ場を飾るために大切な記念品をいくつか持ち歩くのが一般的だ。
]],
[race_ed_dd2]=[[
]],
[race_ed_phy]=[[
ハーフリングの身長は3フィート（約1.5メートル）と低い。彼らは裸足で歩くことを好み、足の裏にはざらざらとした角質ができる。太い巻き毛が、日焼けした広い足の甲を温めている。肌はシナモン色に、髪は明るい茶色に近い。ハーフリングの耳は尖っているが、比例して人間のそれよりもそれほど大きくない。

ハーフリングはシンプルで控えめな服装を好む。状況に応じて着飾ることは厭わないが、ひっそりと身を潜めていたいという人種的な衝動から、たいていの状況では控えめな服装を好む。一方、ハーフリングのエンターテイナーは注目を集めることで生計を立てているため、派手で派手な衣装を身にまとう傾向がある。
]],
[race_ed_btl]=[[
ハーフリングは防御的な戦いを好み、通常は隠れて敵が近づいてきたときに範囲攻撃を仕掛ける。

彼らの戦術はエルフとよく似ているが、隠蔽と隠蔽に重きが置かれ、機動性はあまり重視されない。
]],
[race_ed_soc]=[[
多くのハーフリングは帝国や大義を信頼するよりも、家族や地域社会のよりシンプルで謙虚な美徳に焦点を当てることを好む。ハーフリングは文化的な故郷を主張することはなく、農村の自由な町の集まり以上の集落を支配することもない。たいていの場合、人間の都市で人間のいとこたちの膝元に住み、より大きな社会の残骸からできる限りの生計を立てている。多くのハーフリングは、大きな隣人たちの影に隠れて充実した生活を送っているが、より遊牧的な生活を好み、世界中を旅してあらゆることを経験する者もいる。

ハーフリングは自分たちの文化を維持するために習慣や伝統に頼っている。ハーフリングの美徳の模範となる民俗的英雄についての重要な物語に満ちた広範な口承史を持っているが、それ以外の点では歴史を学ぶこと自体にほとんど意味を見出さない。無意味な真実と有益な寓話のどちらかを選べと言われれば、ハーフリングはほとんどの場合寓話を選ぶ。この傾向は、ハーフリングの有名な順応性の少なくとも一部を説明するのに役立つ。ハーフリングは未来に目を向け、他の多くの種族の足を引っ張るような古くからの恨みや義務の重荷を非常に簡単に捨てることができる。
]],
[race_ed_rel]=[[
典型的なハーフリングは、他の種族に気づかれないことを誇りとしており、そのおかげで多くのハーフリングが盗みや策略を得意としている。ほとんどのハーフリングは、他の種族が自分たちをステレオタイプに見ていることをよく知っている。

ほとんどのハーフリングはノームという風変わりな生き物を警戒しているが、ノームとはかなりうまくやっている。ハーフリングはエルフやドワーフを尊重するが、これらの種族はハーフリングが享受する快適な文明から遠く離れた辺境の地に住んでいることが多く、交流の機会は限られている。概して、ハーフリングから敬遠されるのはハーフオークだけである。彼らの大きな体格と凶暴な性質は、ほとんどのハーフリングにとって少し威圧的すぎるからである。

一般的にハーフリングは人間とうまく共存しているが、より攻撃的な人間社会の中にはハーフリングを奴隷として重んじるところもあるため、彼らはあまり満足しないようにしている。ハーフリングは自由を重んじ、特に新しい経験を求めて旅をする能力と、そのために必要な自律性を重んじる。しかし、現実的で柔軟なハーフリングは、主人に対して直接反撃することはめったにない。可能であれば、絶好の機会を待って、そのまま逃げ出す。長い間奴隷にされたハーフリングは、飼い主を新しい家族として迎え入れることさえある。逃亡と自由を夢見ながらも、ハーフリングたちは自分の人生を最大限に楽しむ。
]],
[race_ed_aln]=[[
ハーフリングは友人や家族には忠実だが、自分たちの2倍も大きな種族が支配する世界に住んでいるため、生き残るためには、時には身を削り、物色する必要があるという事実を理解している。その結果、ほとんどのハーフリングは中立である。

ハーフリングは通常、法律を尊重し、地域社会の偏見を是認する姿勢を見せるが、それ以上に個人の生来の常識を重視する。ハーフリングは社会全体の意見に反対するときは、自分が最善と考えることをする。

常に現実的なハーフリングは、大きくて力のある隣人たちが最も好む神を崇拝することが多い。幸運と旅の女神はほとんどのハーフリングにとって自然な存在であり、時折彼女に祈りを捧げるのは常識的なことだ。
]],
[race_ed_adv]=[[
生来の幸運と飽くなき放浪癖が相まって、ハーフリングは理想的な冒険生活を送ることができる。貴重品をポケットに入れることは厭わないが、ハーフリングは物質的な報酬よりも、冒険がもたらす新しい体験のほうを重視することが多い。ハーフリングは金銭を、それ自体が目的ではなく、生活をより楽に、快適にするための手段と考える傾向がある。

他の放浪者たちは、自分たちの神秘的な幸運が少しは報われることを期待して、この好奇心旺盛な種族と一緒にいることが多い。ハーフリングは、旅の仲間だけでなく、より広い世界においても、このような信念を奨励することを悪いことだとは思わない。船やキャラバンで旅をするとき、あるいは宿屋に一泊するときでさえ、彼らの幸運の評判を利用して運賃を値切ろうとする者が多い。その成功はまちまちだが、ハーフリングと一緒に旅をする人々に幸運が舞い降りるという話は、疑い深い人々でさえ躊躇させるほど多く出回っている。もちろん、そのような理由でハーフリングが意図的にそのような話を広めていると疑う者もいる。
]],
[race_ed_nam]=[[
