s_hfo			= "ハーフ オーク"
s_hfo_d			= [[
しばしば獰猛で野蛮であり、時に気高く毅然としているハーフオークは、母種族の長所と短所を併せ持つ。

ハーフオークの多くは、人間の最も英雄的な価値観を体現するために、より獣性的な本性を抑え込もうと奮闘している。

残念なことに、来訪者の多くはハーフオークを、憐れみも寄合いもするに値しない怪物とは言わないまでも、礼節を欠いた絶望的な醜悪な存在とみなしている。
]]
s_hfo_eds={
[race_ed_dd1]=[[
文明種族から見れば、ハーフオークは倒錯と暴力の結果生まれた怪物である。

ハーフオークは愛情に満ちた結婚の結果生まれることは稀であり、そのため通常は厳しく急成長を余儀なくされ、身を守るため、あるいは自分の名を上げるために常に戦っている。ハーフオークは全体的にこのような扱いに憤慨しており、被害者面をするのではなく、周囲の偏見を無意識のうちに確認しながら暴れる傾向がある。

恐れられ、疎まれ、唾棄されてきたハーフオークの中には、偉大な功績と思いがけない知恵で、敵対する者たちを驚かせる者もいる。ハーフオークの中には、自分たちが同じように獰猛であることを生粋のオークに証明するために一生を費やす者もいる。また、人間社会に溶け込むことを選び、自分がモンスターではないことを常にアピールする者もいる。常に自分に価値があることを証明する必要があるため、ハーフオークは周囲の社会の中で権力と偉大さを手に入れようと努力する。
]],
[race_ed_dd2]=[[

]],
[race_ed_phy]=[[
ハーフオークは通常、両親の身体的特徴をうまくブレンドして受け継ぐ。背丈は人間と同じくらいで力強い体格をしており、筋肉のおかげで体重は少し重い。

緑がかった、あるいは灰色がかった色素、なだらかな額、突き出た顎、目立つ歯、粗い体毛を持つ。犬歯は口から突き出るほど長く伸びていることが多く、この「牙」が重い眉毛とわずかに尖った耳と相まって、悪名高い獣のような外見をしている。

ハーフオークは印象的ではあるが、彼らを美しいと評する者はほとんどいない。このような明らかなオークの特徴にもかかわらず、ハーフオークは人間の親と同じように多様性に富んでいる。

オークの間や近くで暮らしてきたハーフオークには、オークの伝統に則って傷跡がある。
]],
[race_ed_soc]=[[
少なくとも社会の差別の一部が嫉妬や魅力から生まれるハーフエルフとは異なり、ハーフオークは両方の悪い面を併せ持つ。身体的にオークの同族よりも弱く、また、完全なオークと半血をわざわざ区別しない人間たちから恐れられたり、真っ向から攻撃されたりする傾向がある。文明社会におけるハーフオークは、たとえ条件が良くても受け入れられることはなく、その身体能力だけが評価される傾向にある。その一方で、オークの指導者たちは意図的にハーフオークを産ませることが知られている。混血種は体力の不足を狡猾さと攻撃性の向上で補うため、天性の指導者であり戦略的助言者となるからだ。

オークの部族内では、ハーフオークは常に戦いと力の誇示に努めている。オークの部族内で育ったハーフオークは、牙を削り、部族のタトゥーで身を隠す傾向が強い。部族の指導者たちは、ハーフオークがオークの従兄弟たちよりも賢いことが多いことを静かに認識しており、しばしば彼らを部族の祈禱師に弟子入りさせる。しかし、祈禱師に弟子入りするのは残酷なことであり、短命に終わることも多い。祈禱師に弟子入りして生き残ったハーフオークは、部族内で影響力を持つようになるか、最終的には部族を去ることになる。

ハーフオークは人間社会ではもっと複雑な経験をしており、多くの文化が彼らを怪物程度にしか見ていない。彼らはしばしば通常の仕事に就くことすらできず、軍務に就かされたり、奴隷として売られたりする。このような文化圏では、ハーフオークは可能な限りその本性を隠し、隠微な生活を送ることが多い。社会の暗黒の裏社会はしばしば最も歓迎される場所であり、多くのハーフオークは盗賊ギルドやその他の組織犯罪の執行者として仕えることになる。

あまり一般的ではないが、人間の都市はハーフオークに普通の生活を許し、彼ら自身の小さなコミュニティを発展させることさえある。こうしたコミュニティは通常、闘技場地区や軍隊、傭兵組織が中心となっており、そこでは彼らの力強さが評価され、その外見が見過ごされる可能性が高い。同族に囲まれていても、ハーフオークの生活は楽ではない。いじめや肉体的な対立は、他の模範となるような行動をほとんどとらずに育ってきた彼らにとっては容易なことなのだ。しかし、若いハーフオークにとっては偏見なく成長できる最良の場所のひとつであり、こうした小さな飛び地はハーフオークの結婚や子供たちが真に受け入れられ、時には大切にされる数少ない場所のひとつである。

さらに稀なことだが、ある種の人間の文化では、ハーフオークをその強さゆえに受け入れるようになる。人々がハーフオークの子供を祝福とみなし、ハーフオークやオークの恋人を求める場所の話もある。こうした文化圏では、ハーフオークは生粋の人間と大差ない生活を送っている。
]],
[race_ed_rel]=[[
エルフとドワーフはハーフオークを最も受け入れない傾向にあり、彼らの種族の敵にあまりにも似ていると見ている。

迫害の生涯を送ったため、平均的なハーフオークは警戒心が強く、怒りっぽいが、その野蛮な外見を打ち破った者は、隠された共感の核を見出すかもしれない。オークの問題が少ない人間社会は最も寛容な傾向にあり、そこに住むハーフオークはしばしば傭兵や執行者として仕事を見つけることができる。しかし、一般的にハーフオークに寛容な場所であっても、多くの人間は逃げられるとハーフオークを虐待する。

ハーフオークはハーフエルフが人間やエルフの社会で受け入れられていることを妬んでおり、ハーフオークの残忍な外見とは対照的な彼らの肉体美に憤りを感じている。ハーフオークはハーフエルフと直接敵対することは避けるが、隙あらばハーフエルフを貶めることも辞さない。

他の種族の中で、ハーフオークはハーフリングに最も同情的である。ハーフオークはハーフリングの紛れ込んで姿を消す能力を尊敬し、苦難にもかかわらず常に明るい人生観を賞賛する。ハーフリングはこの事実を理解できない。なぜなら、彼らは通常、大きくて威圧的なハーフオークを避けることで精一杯だからだ。
]],
[race_ed_aln]=[[
残忍なオークの間で生きるか、文明化された土地で孤独な追放者として生きることを余儀なくされたハーフオークのほとんどは、辛辣で暴力的で、引きこもりがちである。悪は彼らにとっては容易なことだが、彼らはもともと邪悪な存在ではない。むしろ、ほとんどのハーフオークは混沌にして中立であり、長い経験によって、自分に直接利益をもたらすこと以外は何をしても意味がないことを教え込まれている。

ハーフオークは育った地域で崇拝されている人間やオークの神々を崇拝する。人間と共に暮らす者は、戦争、自由、破壊を司る人間の神々を崇拝することが多い。オークの部族で育ったハーフオークは、血、火、鉄の神々に最も惹かれるが、これはハーフオークの個人的な好みというよりも、その部族がどの神を崇拝しているかによる。

多くのハーフオークは宗教に対して否定的であり、宗教を完全に無視するか、宗教に深く関わり、憎しみと誤解に満ちた人生に意味を見出そうとする。ハーフオークの信仰呪術師でさえ、宗教や信仰に対する疑念や怒りと格闘することがある。
]],
[race_ed_adv]=[[
独立心の強いハーフオークの多くは、辛い過去から逃れるため、あるいは武力によって地位を向上させるために、必要に迫られて冒険の旅に出る。また、より楽観的であったり、受け入れられたいと切望している者は、自分の価値を世界に証明するために十字軍の外套を身につける。

オークの社会で育ったハーフオークは、しばしば周囲の人々の残忍なやり方を取り入れ、ファイター、バーバリアン、レンジャーとなる。祈禱師の訓練を生き延びたハーフオークは、最終的に部族の祈禱師として主人の後を継ぐか、部族から逃れて追放者や探検家として魔法を実践する。ハーフオークは他の種族と同様に生来の魔術の才能を持つ子供を持つ可能性が高く、最も一般的なタイプのソーサラーである。

人間社会では、ハーフオークにはもう少し選択肢がある。傭兵やキャラバンの警備員として働くのが簡単だ。犯罪もまたハーフオークにとって容易な道である。腕っ節の強い者を求める犯罪者はいくらでもいるからだ。人間社会でハーフオークのクレリックになるのはかなり稀である。信心深いハーフオークほど、宗教的な奉仕の武術的な側面に傾倒し（あるいは傾倒させられ）、パラディンになることが多い。ハーフオークは通常、ウィザードになるのに必要な忍耐力と資金を持ち合わせていない。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アウスク,ダヴォル,ハカク,キジール,マコア,ネステルク,ツァドク。

