s_orc			= "オーク"
s_orc_c			= "この野蛮な生き物は、野蛮な人間を獣化したような姿をしており、緑灰色の肌と脂ぎった黒髪をしている。"
s_orc_d			= [[
野蛮で、残忍で、殺すのが難しいオークは、しばしば遠く離れた荒野や洞窟の奥地の災いとなっている。

オークの多くは筋肉質で血なまぐさい暴れ方をするため、恐ろしいバーバリアンとなる。

血への渇望をコントロールできる少数の者は、優れた冒険家になる。
]]
s_orc_eds={
[race_ed_dd1]=[[
オークは攻撃的で無情で支配的です。その性質上、彼らは強さと力を最高の美徳として尊重します。

ほとんど本能的なレベルで、オークは、より強い者がそれを奪うのを止めない限り、欲しいものは何でも手に入れる権利があると信じている。このような態度は、単に怠け心から来るものだけではなく、仕事は弱い者の肩に落ちるまで、序列を経て徐々に下降していくものだという、染み付いた信念から来るものでもある。

彼らは他種族から奴隷を奪い、オークの男はオークの女に残忍な仕打ちをし、子供や年長者には虐待を加える。常に怨敵に囲まれているオークは、痛みに無関心な態度を養い、凶暴な気性を持ち、自分たちに逆らう勇気のある者に対しては、言いようのない復讐を行う激しい意志を持つ。
]],
[race_ed_dd2]=[[
オークと文明化された人型生物の最大の違いは、その野性的な強さと比較的低い知性に加えて、その態度である。文化として、オークは暴力的で攻撃的であり、最も強いものが恐怖と残忍さによって残りを支配する。

彼らは力ずくで欲しいものを奪い、村全体を虐殺したり奴隷にしたりすることを何とも思わない。

彼らのキャンプや村は、酔っ払いの喧嘩や落とし穴での戦い、その他のサディスティックな娯楽で満たされた、不潔で荒れ果てたものになりがちだ。

農耕をする忍耐力がなく、最も丈夫で自給自足ができる動物の世話をすることしかできないオークは、ほとんどの場合、自分で物を作るよりも、誰かが作った物を奪う方が簡単だと考える。

彼らは傲慢で、挑発されるとすぐに怒るが、そうすることが自分に直接利益をもたらす限りにおいてのみ名誉を気にする。

成人男性のオークの身長はおよそ180センチ、体重は210キロである。オークと人間は頻繁に交配するが、そのほとんどは合意の上での結婚ではなく、襲撃や奴隷奪取の結果である。多くのオーク部族は意図的にハーフオークを繁殖させ、自分たちの種族として育てている。
]],
[race_ed_phy]=[[
大人のオークの身長は180センチ強、体重は210キロほどだ。メスはやや小さい。力強い体格のオークの身長は、一般的な人間より数インチ高いだけだが、筋肉量ははるかに多く、広い肩幅と太く屈強なヒップは、ややのけぞったような歩き方をすることが多い。

彼らは通常、くすんだ緑色の肌、荒々しい暗い髪、狼耳、小さな赤い目、突き出た、牙のような歯を持っています。オークは傷を区別の証と考え、しばしばそれをボディアートの形態として使用します。

オークは、血のような赤、マスタードイエロー、黄緑、深い紫など、多くの人間が不快に思うような鮮やかな色を好んで身につける。彼らの装備は汚く、手入れされていない。
]],
[race_ed_btl]=[[
オークはあらゆる単純武器を使いこなすが、最も短時間で最も大きなダメージを与える武器を好む。戦士やファイターのクラスを取るオークの多くは、ファルシオンやグレートアックスも武器の1つとして熟練する。

彼らは潜伏からの攻撃や待ち伏せを楽しんでおり、戦争のルール（休戦を尊重するなど）を、それが彼らにとって便利である限りにおいてのみ従います。
]],
[race_ed_soc]=[[
オークは通常、不潔で絶え間ない騒乱の中で暮らしており、威嚇と残忍な暴力がオーク文化を支えている。彼らは、ライバルが引き下がらないとき、争いが実際の流血にエスカレートするまで、ますます残忍な脅しをかけて争いを解決する。このような獰猛な乱闘に勝ったオークは、敗者から欲しいものを何でも自由に奪えるだけでなく、屈辱的な肉体的暴力や、さりげない切断、さらには完全な殺人にまで手を染めることが頻繁にある。

オークは自分の家や持ち物を改良することにあまり時間をかけない。実際、可能な限り、彼らは元々他の種族が建てた建物や共同体に住むことを好む。
]],
[race_ed_rel]=[[
オークは何よりも強さを賞賛する。敵対する種族の一員であっても、鼻を何度もへし折れば、オークの恨みを買い、少なくとも寛容になることがある。

オークはドワーフとエルフを、激しい憎悪と不機嫌な憤り、そして一抹の警戒心の入り混じった奇妙な目で見ている。彼らは権力を尊重し、この2つの種族が数え切れないほど長い間、自分たちを寄せ付けなかったことをある程度は理解している。彼らの魔手にかかったドワーフやエルフを苦しめるチャンスは決して逃さないが、勝利を確信しない限りは慎重に行動する傾向がある。オークはハーフリングやノームを奴隷にする価値のない弱虫と見なす。彼らはしばしば、生粋のエルフほど脅威には見えないがエルフの特徴を多く持つハーフエルフを、特に魅力的な標的として見なす。オークは人間を羊の一種であり、その中に数匹の狼が住んでいると見なしている。彼らは自分たちを追い払うには弱すぎる人間を自由に殺したり虐げたりするが、手ごわい人間に出くわしたときのために、常に最寄りの出口に片目を光らせている。

オークはハーフオークを侮蔑と羨望と誇りの入り混じった奇妙な目で見ている。一般的なオークよりも弱いが、ハーフオークの方が賢く、狡猾で、優れた指導者でもある。ハーフオークが率いる部族、あるいは少なくともその助言を受ける部族は、純血のオークが率いる部族よりも成功することが多い。より根本的なレベルでは、オークはハーフオークが弱い種族を支配していると考えている。
]],
[race_ed_aln]=[[
オークにはほとんど良いところがない。多くは暴力的で残酷、そして利己的である。名誉や忠誠といった概念は通常、弱い種族を苦しめる奇妙な欠点として彼らを捉える。オークは一般的に単なる悪ではなく、混沌な性格を持つが、自制心の強い者は秩序にして悪に傾倒することもある。

オークは火、戦争、血の神に祈りを捧げ、しばしばこれらの側面をオーク独自の概念に組み合わせて部族の "パンテオン "を作り上げる。
]],
[race_ed_adv]=[[
オークは通常、権力闘争に敗れて初めて部族を離れる。屈辱、奴隷、あるいは同族の手による死に直面した彼らは、代わりに他の種族のメンバーと暮らし、働くことを選ぶ。

短気な性格と本能的な支配欲を抑えられないオークは、ひとたび独立すると長続きしない。

他の社会で何とか生活しているオークは、しばしばその社会がもたらす贅沢や快適さを享受しているが、それでも故郷に戻り、権力を掌握し、復讐することを夢見る傾向がある。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アーカス,カルルグ,フェルザック,ムルドゥット,プラバー。

<c=twa>女性名:</c>
ドゥラ,グリルギス,イリヤット,クルッガ,レフィット,オルビン,トリスグラーク。
]],
}


s_goblinoid		= "ゴブリノイド"
s_goblinoid_d	= [[ゴブリノイドは狩りと略奪を生業とする隠密型の人型生物だ。

一般的なゴブリノイドにはゴブリン、バグベア、ホブゴブリンがいる。彼らはすべてゴブリン語を話す。]]-- …raiding and who all speak Goblin

s_goblinoid_aln		= "ゴブリノイドの悪の本質"
s_goblinoid_aln_d	= [[ゴブリン、ホブゴブリン、バグベアは、表面的な類似性はあるものの、それぞれ異なる悪の顔を表している。

ホブゴブリンは秩序正しく、几帳面に悪を行い、巨大な軍隊や軍団、専制国家を形成する。

ゴブリンは原始的な悪であり、同族間であれ隣人に対してであれ、残酷さと些細な犠牲を求める。

しかし、バグベアによって擬人化された悪は、可能な限り破壊的な方法で痛みや苦しみを積極的に与えようとするため、最も恐ろしいかもしれない。

ホブゴブリンが殺すのは伝統と秩序のためだ。ゴブリンが殺すときは楽しむためだ。バグベアにとって殺人の真の目的とは、犠牲者ではなく、犠牲者を大切に思っていた人々を攻撃することなのだ。]]


s_gob	= "ゴブリン"
s_gob_c	= "このクリーチャーの身長は3フィート（約1.5メートル）しかなく、痩せこけた人型の体は、幅広の不格好な頭部に矮小化されている。"
s_gob_d	= [[
言いようのない暴力を振るう傾向のある狂気の放火魔で、ゴブリノイド種族の中では最小の種族である。

楽しいことが大好きな人種だが、彼らのユーモアはしばしば残酷で傷つく。

冒険者であるゴブリンは、他人とうまくやっていくために、常に暗いやんちゃな面と格闘している。本当に成功する者は少ない。
]]
s_gob_eds={
[race_ed_dd1]=[[
ゴブリンは破壊的で貪欲な性質を持つ子供のようなクリーチャーの種族であり、ほとんど誰からも軽蔑されている。弱く臆病なゴブリンは、破壊的で使い捨ての歩兵を必要とする強いクリーチャーに操られたり奴隷にされたりすることが多い。生き残るために自らの知恵を頼りにするゴブリンは社会の片隅に住み、ゴミやより文明的な種族の弱いメンバーを餌としている。他のほとんどの種族はゴブリンを駆除不可能な寄生虫とみなしている。

ゴブリンはほとんど何でも食べることができるが、肉食を好み、人間やノームの肉は希少で入手困難な珍味と考えている。ゴブリンは大きな種族を恐れているが、ゴブリンの短い記憶と底なしの食欲のために、しばしば戦争に出たり、他の種族に対して襲撃を行ったりする。
]],
[race_ed_dd2]=[[
ゴブリンは洞窟の中や、アザミやワラビが生い茂る大きな雑木林の中、あるいは他人が建てた後に放棄された建造物の中に住むことを好む。自分で建造物を建てようとする意欲を持つゴブリンはほとんどいない。海岸線が好まれるのは、ゴブリンがガラクタや漂流物をふるいにかけ、文明化した種族のゴミの中から宝物を見つけ出そうとする終わりのない探求を好むからである。

ゴブリンの憎悪は深く、ノーム（彼らは長い間ゴブリンと戦ってきた）、馬（彼らはゴブリンを非常に怖がらせる）、普通の犬（ゴブリンはゴブリンの犬を薄い模造品とみなしている）ほど彼らの怒りを刺激するものはない。

また、ゴブリンはかなり迷信深く、畏怖と恐怖が入り混じった媚び諂った態度で魔法を扱う。平凡なものにも魔法を適用する習性があり、ゴブリン社会では火も文字も神秘的な力を持つ。火は大きな破壊をもたらすことができるため、また振り回すのに大きさや力を必要としないため、ゴブリンにとても愛されているが、書かれた言葉は嫌われている。ゴブリンは文字を書くと頭から言葉が抜け落ちると信じており、その結果、ゴブリンは普遍的に文字を読めない。

ゴブリンは貪欲で、自分の体重分の食料を毎日食べても太らない。ゴブリンの隠れ家には常に多くの貯蔵庫と食料庫がある。人間やノームの肉を好むが、ゴブリンはどんな食べ物でも断らない。
]],
[race_ed_phy]=[[
ゴブリンは背が低く醜い人型生物で、身長は3～3フィート半、体重は40～45ポンドである。痩せこけた体に、巨大な耳と毛のない頭部を持つ。彼らの旺盛な食欲は、ギザギザの歯が生えた巨大な口がよく物語っている。

ゴブリンの肌の色は、黄色からオレンジのような色合い、そして深い赤色まで様々である。目の色は通常、赤から黄色までさまざまで、つぶらな瞳をしている。

ゴブリンは黒っぽい革の服を着ており、無骨で汚れたような色が多い。
]],
[race_ed_btl]=[[
大きくて強い生き物にいじめられることで、ゴブリンは自分たちの数少ない長所、つまり数の多さと悪意ある創意工夫を利用することを学んだ。彼らの社会では、公平な戦いという概念は無意味である。待ち伏せ、圧倒的な勝算、汚い手口、その他考えつく限りの優位を好む。

ゴブリンは戦略を理解するのが苦手で、元来臆病で、戦いが不利になると戦場から逃げ出す傾向がある。しかし、適切な監視があれば、それなりに複雑な計画を実行することができ、そのような状況ではその数は致命的なアドバンテージとなる。
]],
[race_ed_soc]=[[
暴力的だが多産なゴブリンは、絶えず権力が入れ替わる原始的な部族構造の中に存在する。農耕や狩猟採集で自分たちの必要を維持できることはまれで、ゴブリン部族は食料が豊富な場所か、食料を盗める場所の近くに住んでいる。彼らは大きな砦を築くことができず、容易にアクセスできる場所のほとんどから追い出されているため、ゴブリンは不快で人里離れた場所に住む傾向があり、彼らの建築能力や計画能力の低さから、主に粗末な洞窟や荒れ果てた村、廃墟となった建造物に住むことになる。ゴブリンは道具の扱いに長けていたり、農耕に長けていたりする者はほとんどおらず、ゴブリンが持っている貴重な品々はたいてい人間や他の文明文化圏から持ち去られたものである。

ゴブリンの食欲と計画性のなさは、最強の戦士が支配する小さな部族を生み出す。最も頑健なゴブリンのリーダーでさえも、自分たちの生存が、食料源を確保し、部族内の攻撃的な若者を殺すために頻繁に襲撃を行うことにかかっていることにすぐに気づく。ゴブリンの男女はともに醜く凶暴であり、男女ともに部族内で権力の座に就く可能性が高い。

ゴブリンの赤ん坊は生まれて間もなくほとんど自給自足できるようになり、そのような赤ん坊はほとんどペットのように扱われる。多くの部族は、大人がほとんど無視できるような檻や檻の中で子供を共同で育てる。若いゴブリンの死亡率は高く、大人が食事を与えなかったり、食料が少なくなると、若者はゴブリン部族で生き残るためには共食いが最良の手段であることを幼いうちに学ぶ。
]],
[race_ed_rel]=[[
ゴブリンは他の生物を食料源と見なす傾向があるため、ほとんどの文明種族とは関係が悪い。ゴブリンはしばしば人間の文明の片隅で生き延び、弱い者や道に迷った旅人を捕食し、時には貪欲な食欲を満たすために小さな集落を襲うこともある。

彼らはノームに対して特別な反感を抱いており、そのような犠牲者を捕らえたり殺したりすると、祝宴を開いて祝う。最も一般的な種族の中で、ハーフオークはゴブリンに対して最も寛容であり、同じような祖先を持ち、多くの社会で同じ憎しみを経験している。しかし、ゴブリンはハーフオークの同情をほとんど知らず、彼らが他の人型生物よりも大きく、意地悪で、味が薄いという理由で避けている。
]],
[race_ed_aln]=[[
ゴブリンは元来貪欲で、気まぐれで、破壊的であるため、そのほとんどは中立か混沌にして悪である。
]],
[race_ed_adv]=[[
ゴブリンの冒険者はたいてい好奇心が強く、世界を探検したがるが、自らの愚かな悪行によって殺されたり、無差別な破壊行為のために狩られたりすることが多い。その凶悪な性質から文明種族との交流はほとんど不可能であるため、ゴブリンは文明の片隅や荒野を冒険することが多い。

長く生き残る冒険好きな者は、ゴブリンの犬や他の特殊な馬に乗ることが多く、大きな敵との接近戦を避けるために弓術に重点を置いている。ゴブリンの呪文の使い手は、他のほとんどすべての騒乱を広げる方法よりも、火の魔法や爆弾を好む。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
ブールガブ,ゴグマルチ,ロットフット,ゾブマグル。

<c=twa>女性名:</c>
ギードラ,グームルーガ,ホグロブ,ラックムス。
]],
}


s_gob_h		= "ホブゴブリン"
s_gob_h_c	= "人間の背丈ほどもあり、筋肉質でオレンジ色の肌をしたこの生き物は、小さな観察眼で周囲を見回す。"
s_gob_h_d	= [[
ホブゴブリンはゴブリンの従兄弟にあたる大型の種族である。このクリーチャーはゴブリノイド種族の中で最も規律正しく、軍国主義的である。

背が高く、タフで力強い体格のホブゴブリンは、残酷で悪意があり、しばしば奴隷を飼うという事実がなければ、どの冒険者グループにとっても有益な存在だろう。
]]
s_gob_h_eds={
[race_ed_dd1]=[[
獰猛で軍国主義的なホブゴブリンは、征服によって生き延びる。彼らの戦争機械の燃料となる原材料は襲撃からもたらされ、武器や建物は死ぬまで働かされた奴隷の労苦から生まれる。

生来、野心的で嫉妬深いホブゴブリンは、他の種族を犠牲にしてでも自分を高めようとするが、戦いにおいては些細な相違を捨て、最高の兵士に匹敵する規律をもって戦う。

ホブゴブリンは互いにほとんど愛情も信頼もなく、来訪者に対してはなおさらである。ホブゴブリンたちの生活は、地位の高い者への義務、地位の低い者への支配、そして個人的な栄光を掴み、地位を向上させる稀な機会から成り立っている。
]],
[race_ed_dd2]=[[
ホブゴブリンは軍国主義的で多産であり、この組み合わせが地域によっては非常に危険な存在となっている。彼らは素早く繁殖し、戦死者を新しい兵士と入れ替え、戦況にもかかわらずその数を維持する。ホブゴブリンの隠れ家での奴隷としての生活は残酷で短く、倒れたり食べられたりした者の代わりに新しい奴隷が常に必要とされる。

ゴブリノイド種族の中で、ホブゴブリンは圧倒的に文明的である。彼らは、より大きく孤独なバグベアを、通常は暗殺や隠密を含む特定の任務のために雇い入れられ、適切な場所で使用される道具と見なし、その小さなゴブリンの親族を恥と不満の入り混じった目で見ている。ホブゴブリンはゴブリンの粘り強さを賞賛するが、その小さな同族の予測不可能な性質と火を好むことから、ホブゴブリンの部族や集落には歓迎されない。とはいえ、ほとんどのホブゴブリン部族にはゴブリンの小集団が含まれており、通常、集落の最も好ましくない一角にしゃがんでいる。

多くのホブゴブリン部族は戦争好きと鋭い知性を兼ね備えている。攻城エンジンの科学、錬金術、複雑な技巧はほとんどのホブゴブリンを魅了し、特に熟練した者は英雄として扱われ、必ず部族内で高い地位を確保する。分析的な頭脳を持つ奴隷は非常に重宝され、そのためドワーフの都市を襲撃することは日常茶飯事である。

ホブゴブリンが魔法、特にアーケインの魔法に不信感を抱き、軽蔑さえしていることはよく知られている。彼らの祈禱師は恐怖と尊敬が入り混じった態度で扱われ、通常は部族の隠れ家の片隅で孤独に暮らすことを余儀なくされる。ホブゴブリンがアーケインの魔法（ホブゴブリンは "エルフマジック "と呼ぶ）を使うことは前代未聞である。これがホブゴブリンが魔法を憎む根源であり、ホブゴブリンがエルフを憎む理由である。
]],
[race_ed_phy]=[[
ホブゴブリンの身長は5フィート（平均的な人間より数インチ低い）、体重は160ポンド（約8.5kg）である。体格を除けば、ホブゴブリンは従兄弟のゴブリンによく似ている。

たくましく筋肉質で、長い腕、太い胴体、比較的短い脚は、ほとんど猿のような体格をしている。

ホブゴブリンの髪の色は暗赤褐色から暗灰色まである。皮膚は暗橙色か赤橙色をしている。大きなオスの鼻は青か赤である。ホブゴブリンの目は黄褐色か暗褐色で、歯は黄色である。

彼らの衣服は鮮やかな色彩のものが多く、血のような赤に黒を基調とした革が使われることが多い。
]],
[race_ed_btl]=[[
ホブゴブリンは戦略と戦術を熟知しており、高度な戦闘計画を遂行することができる。熟練した戦略家や戦術家の指揮の下、彼らの規律が決め手となることもある。

ホブゴブリンはエルフを憎んでおり、他の敵よりもまずエルフを攻撃する。
]],
[race_ed_soc]=[[
ホブゴブリンは軍国主義的な専制国家に住んでおり、各集落はホブゴブリン将軍の絶対的な支配下にある。集落のすべてのホブゴブリンが軍事訓練を受け、優秀な者は軍隊に、それ以外はより下働きの役割に任される。軍務に適さないと判断された者の社会的地位は低く、かろうじて寵愛された奴隷より上の地位にある。にもかかわらず、ホブゴブリン社会は一応平等主義である。性別や生まれは出世の妨げにならず、ほぼ個人の実力だけで決まる。

ホブゴブリンは、たとえ子供であっても強い執着を避ける。結婚は便宜的なものであり、ほとんどの場合、同格のホブゴブリンに限られる。生まれた子供は生後3週間で母親から引き離され、強制的に離乳させられる。子供の成熟は早く、会話や身の回りのことができるようになるまで6ヶ月はかからない。ホブゴブリンの幼年期はわずか14年で、戦争術の残酷な訓練に明け暮れる。
]],
[race_ed_rel]=[[
ホブゴブリンは他の種族を奴隷にし、隷属させ、働かせる道具としか見ていない。奴隷がいなければ、ホブゴブリン社会は崩壊してしまうほど、奴隷労働に依存している。怪我をしたり、病気になったり、反抗的な奴隷は、壊れた道具のようなもので、その日のゴミと一緒に捨てられる役立たずの廃棄物だ。驚くなかれ、ホブゴブリン社会は他の種族を友人とせず、味方とする者もほとんどいない。

エルフとドワーフは特別な敵意を買い、両種族ともにゴブリンに対する血の仇に恨みを持っているため、適切な奴隷に仕立てるのは非常に難しい。ハーフリングとハーフオークは特に貴重な奴隷と見なされる。前者はその俊敏な技能と首輪に簡単に従うことができるため、後者は最も過酷な環境でも生き残る才能があるためである。ホブゴブリンはゴブリンの他の種族に対してあまり愛情を持っていないが、通常は他の種族よりもゴブリン系の奴隷をより良く扱う。
]],
[race_ed_aln]=[[
ホブゴブリンの生活は極めて秩序があり階層的で、ホブゴブリンは強く秩序属性に傾いている。生来は悪ではないが、ホブゴブリンの短すぎる子供時代を満たす無慈悲で残忍な訓練は、ほとんどの者に恨みと憎悪を残す。善の属性を持つホブゴブリンは最も数が少なく、ほとんど他の文化圏で育った者に限られる。より数は多いがまだ稀なのは混沌な傾向のホブゴブリンで、その多くは祖国の専制君主によって追放された亡命者である。

大半のホブゴブリンにとって、宗教は非軍事的な追求と同様、ほとんど重要ではない。ほとんどのホブゴブリンは1つ以上の神々に口先だけの奉仕を捧げ、時折供物を捧げて寵愛を受けたり、不運を退けたりする。より強い宗教的使命を感じるホブゴブリンは、恐ろしく暴虐な神々や悪魔を崇める。
]],
[race_ed_adv]=[[
ホブゴブリンの冒険者たちは、軍生活の厳しい序列体系に不満を抱く一匹狼の象徴的な存在である。また、弱さや臆病さを露呈したために、不名誉のうちに逃亡したり追放されたりした者もいる。ある者は、いつか富と偉大な功績の物語を携えてホブゴブリンの群れに戻ることを夢見ている。数人は先見の明のあるホブゴブリン将軍に仕え、最も有望な若者を世に送り出し、いつの日かホブゴブリンの大義のために強大な英雄として戻ってくるかもしれない。

ホブゴブリンは武闘派、特にファイター、モンク、ローグに傾倒している。アーケインの術はホブゴブリン社会では信用されておらず、そのためその実践者は稀である。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アロノク,バンカニール,ドルドゥケン,フェンタナス,グルール,ハゴルス,カルマント,マルグロア,スラターク,タロガン。

<c=twa>女性名:</c>
アリネット,エロチ,エスカニ,ホリニア,コルムン,モラナッサ,モリトラ,ニマニシ,ノラニリム,ヴォルティガ。
]],
}


s_gob_b		= "バグベア"
s_gob_b_c	= "その小さな乳白色の目は、これから始まる殺しのスリルに輝いている。"
s_gob_b_d	= [[
バグベアはゴブリノイド種族の中で最も大きく、ほとんどの人間よりも少なくとも頭1つ分身長が高い。

バグベアはもともと残酷で、楽しむために殺す。人間はバグベアが好む獲物であり、ほとんどのバグベアは人間の肉を主食としている。耳や指の無惨な戦利品は、バグベアの一般的な装飾品である。

彼らは一匹狼であり、同族の部族を形成するよりも自分たちだけで生きて殺すことを好むが、バグベアの小集団が一緒に行動することも珍しくない。彼らは小規模な騒乱を好み、その方が好きな行為（殺人や拷問）をより個人的なレベルで行えるからだ。
]]
s_gob_b_fav_cls="バグベアは可能な限り相手を待ち伏せすることを好む。ローグとして優れている。"
s_gob_b_traits=[[
<b c=tg>筋力 +4、敏捷力 +2、耐久力 +2、 <c=tr>魅力 -2: </c></b>バグベアは強くて健康だが、その残酷で殺戮的な性質にはうんざりさせられる。

<b>種族ヒットダイス(HD): </b>バグベアは3レベルの人型生物からスタートし、3d8のヒットダイス(HD)を得る。

<b>種族技能: </b>バグベアの人型生物レベルは6×（2＋知力修正値）に等しい技能点を与える。クラス技能は登攀、隠れ身、聞き耳、忍び足、捜索、視認である。

<b>種族特技: </b>バグベアの人型生物レベルは2つの特技を与える。

<b>武器と防具の熟練度: </b>簡単純武器、軽装鎧、盾の扱いに習熟する。

<b>鎧: </b>外皮ボーナス+3。

<b>S隠密: </b>忍び足の判定に+4の種族ボーナスを与える。
]]
s_gob_b_langs=[[
<b>自動習得言語: </b>共通語とゴブリン語。
<b>ボーナス習得言語: </b>竜語、エルフ語、ジャイアント語、ノール語、オーク語。

<c=twc>バグベアはゴブリン語と共通語を話す。</c>
]]
s_gob_b_eds={
[race_ed_dd1]=[[
バグベアは一匹狼で、同族の部族を形成するよりも自分たちだけで生き、殺すことを好む。

とはいえ、バグベアの小集団が一緒に行動したり、ゴブリンやホブゴブリンの部族に住み着いてエリート衛兵や処刑人として機能することも珍しくない。

バグベアはゴブリンのように大規模な戦場を形成したり、ホブゴブリンのように国家を形成したりはしない。

バグベアは他のゴブリノイドよりも孤独に生きる傾向が強い。他人の弱さや必要性に足を引っ張られることを嫌うため、本来は自分の一族や肉親にさえ不信感を抱いている。

バグベアは単独でのサバイバルに適している。その優れた感覚は、克服するには大きすぎる脅威を避けるために十分な距離を保ちながら脅威を識別することを可能にし、その天性の隠密性は、寝床や物資の隠し場所まで気付かれずに移動するのに役立つ。

もちろん、一匹でいるバグベアは病気や怪我をしているときは狩られやすく、その弱点を知っているために用心深くなる。負傷したバグベア単独では、危険の少ない弱い獲物を探すが、たとえ獲物が数週間から数ヶ月の間苦しめられるのに十分な強さを持っていることを望んでいてもである。
]],
[race_ed_dd2]=[[
一匹のバグベアが年を取って衰弱し始めると、集団に引き取られるよう説得するか、影に隠れて危険を避け、過去の栄光を懐かしむかのどちらかにならざるを得ない。

バグベアは寛大な生物ではありませんが、かなりの規模のバグベア族はしばしば長老を受け入れることを喜びます。

第一に、新参者は病弱であるため、既存の一族のリーダーにとっては脅威ではなくなる。

第二に、年老いたバグベアは狡猾なバグベアとみなされ、静かにストーキングしたり殺したりする秘訣を知っている可能性が高い。バグベアは他のほとんどの知識はほとんど使わないが、これらのテーマに関する信頼できる教訓や逸話は、知恵としても娯楽としても重宝される。
]],
[race_ed_phy]=[[
バグベアはゴブリノイドの中で最も大きく、身長は7フィート近くある--まっすぐ立てばそうなるが、ほとんどのバグベアは猫背の姿勢を好む。この巨大なクリーチャーの体重は400ポンドに達する。

ゴブリンやホブゴブリンに似た顔立ちをしているが、よりふにゃふにゃとした広い顔をしている。顔は剥き出しだが、体の他の部分は粗くボサボサの毛で覆われており、しばしばつや消しになっていたり、奇妙な角度で突き出ていたりする。

膨れ上がった筋肉と巨体にもかかわらず、バグベアは驚くほどの優雅さと隠密性をもって動く。その丸々とした頭でっかちな体型が、通り抜けるには狭すぎるような空間を静かに滑空しながら獲物を追うバグベアを見るだけで、観察者を不安にさせるには十分だ。
]],
[race_ed_btl]=[[
バグベアは可能な限り相手を待ち伏せすることを好む。

狩りをするときは通常、本隊の前に斥候を送り、獲物を発見したら戻って報告し、援軍を呼び寄せる。

バグベアの攻撃は連携が取れており、その戦術は見事とは言えないまでも健全だ。
]],
[race_ed_soc]=[[
典型的なバグベア一族は、お互いを過度に裏切らない歴史を持つ一族に過ぎず、そのため非常に脆い。バグベアは遠くの犠牲者よりも自分の一族のメンバーを捕食したいと考えるかもしれないし、欠乏によってバグベア一族が食料やシェルターのために争うこともしばしばあるし、あるバグベアが理由もなく他のバグベアを攻撃することもある。法律も安定させる伝統もないため、ひとつの事件が全面的な紛争に発展することはない。殺戮の中から新たなリーダーが立ち上がり、秩序のようなものを強制しない限り、紛争はしばしば脆弱な一族を引き裂く。

安定したバグベア社会はほとんどないが、一般的には2つの大きなカテゴリーに分かれる。1つはバグベアの隔離集団であり、もう1つは秘密結社である。バグベアの秘密結社では、いくつかの生き物がより安定した統治の下で（規則と警戒心に従って）生活している。場合によっては、これは巨人やドラゴンなどの1人の強力な支配者である。その支配者はバグベアに十分な恐れを抱かせるほどの強力さや狡猾さを持っていなければならず、その領地内でトラブルを引き起こさないようにすることはめったに簡単ではない。このような支配者はバグベアをスパイ、拷問者、秘密警察として雇用し、他の派閥を牽制するために彼らの自然な残酷さ、警戒心、ひそかさを利用する。

バグベアの隔離集団は組織化された社会、特にホブゴブリンの間でも時折形成される。このような場合、バグベアは二級市民として扱われ、斥候や傭兵として奉仕させられる。各バグベアは任意のホブゴブリンを殺すことができるかもしれないが、組織化されたホブゴブリンの民兵は、しばしば分裂した利己的なバグベアを統率し、ホブゴブリンの支配に対する反乱を鎮圧することができる。

このような秩序ある社会のバグベアは、しばしば自由な親族よりも野蛮で怒りっぽく、パニックや騒乱を好きなように起こせない制限に怒り狂う。単独で生きようとして逃げ出す者もいるが、よく組織された軍隊や専制政治は、反乱を起こして死ぬよりも、奉仕して生きる方がよいということを、バグベアの小集団に印象づけることができる。

バグベア社会の第二の形態はさらに稀な陰謀団で、バグベアの小集団が他の人型生物（しばしばゴブリン、オーク、コボルドなど）の大集団を支配している。バグベアーの陰謀団は政府とも、その言葉の本当の意味での氏族ともみなされない。その代わり、純粋ないじめと恐喝によって他の集団を支配することに成功した凶悪犯の一団である。陰謀団は共同体における最終的な決定権を持つが、統治の細部は対象集団の機能員に任せている。

そのような集落の中では、陰謀団のエージェントであることが最高の地位であるように思えるかもしれないが、バグベアは下級の臣下に恐怖と不幸を与えるのと同じくらい、最も重要なエージェントを恐怖に陥れることを楽しんでいる。バグベアの陰謀団は恐怖と無差別な力の誇示によって支配し、その臣下は生き残るための最善の方法は注意を全く引かないことだとすぐに学ぶ。しかし、誰かが政府の必要を見なければならないので、バグベアは民衆の上級メンバーにその仕事をさせ、彼らがその職務に失敗すれば拷問する。
]],
[race_ed_rel]=[[
バグベアは他の人型生物に夜を恐れさせる恐怖の存在だ。彼らは残酷な殺人鬼であり、恐怖、苦痛、不幸を与える必要性に駆られ、食物や避難所を求めるのと同じくらい強く駆り立てられている。

バグベアは他のクリーチャー、たとえ自分の家族の一員であっても何も気にかけず、自分の暗い情熱を満たす最善の方法を見つける以上の動機はない。
]],
[race_ed_aln]=[[
バグベアはもともと残酷で、楽しむために殺す。

バグベアは宗教に傾倒すると、殺人と暴力の神々を寵愛し、さまざまな魔王がお気に入りだ。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_kobold	= "コボルド"
s_kobold_c	= "この小柄な爬虫類の人型生物は、鱗状の皮膚、小さな歯が詰まった口先、そして長い尾を持っています。"
s_kobold_d	= [[
コボルドは暗闇の生き物で、地下の巨大な巣窟や、太陽の光が届かない森の暗い隅に多く生息している。

ドラゴンの子孫であるコボルドは、小柄だが自我は強い。

ごく一部の者は同族よりもドラコニックな特徴を持つことができ、その多くは強力なソーサラーや狡猾なローグである。
]]
s_kobold_eds={
[race_ed_dd1]=[[
コボルドは弱く、卑屈で、世界の他の種族、特に自分たちより強く、賢く、何かと優れているように見える種族の一員に対する怨念が渦巻いている。コボルドは誇らしげにドラゴンと同族であることを主張するが、その威勢の良さの裏には、輝かしいいとこたちとの比較による深い劣等感がある。

彼らは勤勉で賢く、機械装置や採掘の天賦の才に恵まれているが、自らの才能を讃える代わりに恨みや憎しみを抱いて日々を過ごしている。コボルドの戦術は罠と待ち伏せに特化しているが、コボルドは自分を危険にさらすことなく他者に危害を加えることができるものなら何でも楽しむ。

多くの場合、殺すことよりも捕らえることを目的とし、閉所恐怖症の巣に引きずり込まれた無力な犠牲者に不満をぶつける。
]],
[race_ed_dd2]=[[
コボルドは暗黒の生き物で、地下の巨大な巣窟や、太陽の光が届かない森の片隅に最も多く生息している。その身体的類似性から、コボルドは自分たちはドラゴン族の子孫であり、偉大なる神の従兄弟の翼の下で地上を支配する運命にあると声高に宣言するが、ほとんどのドラゴンはこの不愉快な蟲をほとんど利用しない。

コボルドは、神の権利や明白な運命を声高に語る一方で、自らの弱さを痛感している。臆病で策略家である彼らは、できることなら正々堂々と戦わず、待ち伏せや裏切りを仕掛けたり、粗末だが巧妙な罠を無数に仕掛けて巣窟に籠もったり、巨大な雄叫びを上げる大群で敵を転げ回ったりする。

コボルドの色合いは、同じ卵塊から生まれた兄弟の間でも異なり、赤が最も一般的ですが、白、緑、青、黒のコボルドも珍しくありません。
]],
[race_ed_phy]=[[
コボルドは背の低い爬虫類のような人型生物で、臆病でサディスティックな傾向がある。ほとんどの場合、身長は2～2フィート半、体重は35～45ポンドである。

コボルドのうろこ状の皮膚は暗い錆びた茶色から錆びた黒色まで様々である。この分厚い皮の色はさまざまで、ほとんどの鱗はクロマティックドラゴンのいずれかの品種の色合いに似ており、赤い鱗が優勢である。しかし、少数のコボルドはオレンジ色や黄色など、より特殊な色をしており、部族によっては仲間の目から見た個体の地位を上下させる。

赤く光る目を持ち、巻き尾はない。コボルドの顔には不思議なことに表情がないことが多く、尻尾を振るだけで感情を表すことを好む。その大きさにしては強力な顎を持ち、手足には目立つ爪がある。

コボルドはボロボロの服を着ており、赤とオレンジを好む。
]],
[race_ed_btl]=[[
コボルドは、少なくとも2対1という圧倒的な勝算か策略で攻撃することを好む。勝算がこの閾値を下回ると、通常は逃げる。しかし、数が同じであれば、見つけ次第ノームを攻撃する。

彼らはまず弾丸を投げつけ、敵が弱ったのを確認してから戦闘を開始する。コボルドは可能な限り、罠にかかった場所の近くに待ち伏せを仕掛ける。
]],
[race_ed_soc]=[[
コボルドは太陽の光から遠く離れた窮屈な場所で成長する。大半は地中深くにある広大な巣穴に住んでいるが、その代わりに生い茂った木々や草木の絡まる場所に住処を構える者もいる。

コボルドは他種族への悪意は抑えて、ほとんどの種族とはうまくやっている。小競り合いや確執が起こることもあるが、コボルドのコミュニティを支配する長老たちは、そのような争いを速やかに解決する傾向にある。

コボルドは奴隷を手に入れることを喜び、彼らを苦しめ、辱める機会を喜ぶ。彼らはまた臆病で現実的であり、しばしばより強力な存在に屈服することになる。これらのクリーチャーが他の人型生物種族である場合、コボルドはできるだけ早く服従から解放されようと画策することが多い。しかし、その支配者がドラコニックやモンスターのような強力なクリーチャーである場合、コボルドは服従を恥と思わず、しばしば新しい指導者を崇拝する。コボルドが真のドラゴンに仕えている場合は特にそうで、ドラゴンを崇拝する傾向がある。
]],
[race_ed_rel]=[[
コボルドはしばしば憎悪と嫉妬にかられるが、生来の用心深さから、こうした衝動に駆られるのは自分が優位に立ったときだけである。他種族に物理的な危害を加えたり、品位を落としたりしたいという衝動を安全に満たすことができない場合は、代わりに慎重な侮辱や "悪ふざけ "に頼る。

彼らはドワーフもエルフも宿命のライバルと考えている。コボルドはハーフオークの武力を恐れ、その種族が享受している支配的な地位について人間を恨んでいる。ハーフエルフは両方の種族の長所を兼ね備えていると考えており、コボルドにとっては根本的に不公平な存在である。コボルドは、小柄なハーフリングは素晴らしい奴隷になり、コボルドの怒りや悪ふざけの標的になると考えている。ノームが初めて人間界にやってきたとき、コボルドは彼らを完璧な犠牲者と見なした。これが報復と報復の波を巻き起こし、何世紀にもわたりコボルドの永遠の恨みを買うことになった。
]],
[race_ed_aln]=[[
コボルドは優れた武力に対しては容易に屈服するが、圧制者よりも優位に立とうとする策謀を止めることはめったにない。ほとんどのコボルドは秩序にして悪であるが、個人的な利益よりも手続きを重視するため、代わりに秩序にして中立になる者もいる。

これらの神々に加え、コボルドは極めて日和見主義的で、モンスターをなだめたり、好意を得たりするために、近くにいるモンスターを崇拝することもある。
]],
[race_ed_adv]=[[
コボルドが自らの意思で居心地の良い巣を出ることはめったにない。冒険の旅に出る者のほとんどは、その部族の最後の一人であり、そのような者は、受け入れてくれる他のコボルドの共同体を見つけると、すぐにまた定住することが多い。

憎しみや悪意に満ちた本性を抑えることができない、あるいは少なくとも隠すことができないコボルドは、大きな世界で生き残ることは非常に困難である。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
ドラアジン,イードゥ,イプメルク,ジャマダ,キブ,マクルオ,オルプ,イラーリク,ゾルネスク。

<c=twa>女性名:</c>
アドリアック,ハルカイル,ネーラル,オズラ,ポロ,サースラー,タルカ。
]],
}


s_liz_man	= "リザード フォーク"
s_liz_man_c	= "この爬虫類のような人型生物は、緑色のうろこ、短くて歯のような鼻、ワニのような太い尾を持っている。"
s_liz_man_d	= [[リザードフォークは、その起源が失われた古代の種族である。急速に進化するこの世界では、より高速に繁殖する温血種によって、リザードフォークはますます無用の存在となりつつある。

それでもリザードフォークは努力を続けている。彼らは誇り高く強力な肉食動物であり、沼地や湿地の奥深くに点在する村に共同生活を営んでいる。乾いた土地の植民地化には興味がなく、何千年もの間、自分たちの役に立ってきた単純な武器と儀式に満足しているため、リザードフォークは他の多くの種族から僻地の野蛮人と見られている。

しかし、隔離されたコミュニティの中では、リザードフォークは実は伝統に満ちた活気に満ちた人々であり、人類が直立歩行する以前にまでさかのぼる口承の歴史がある。]]
s_liz_man_fav_cls="リザードフォークは生涯成長し続け、稀に老化を超越できる者（高レベルのドルイドやアルケミストなど）は100歳前後で大きなサイズに達することもある。このような者はその大きさと幅広い部族的知識の両方によって、リザードフォーク社会における権力の座を確保し、過去の残党が再び目覚めたと考えられている。"
s_liz_man_traits=[[
<b c=tg>筋力+2、耐久力+2、<c=tr>知力-2: </c></b>リザードフォークは強くタフだが、迷信深く頑固だ。

<b>種族ヒットダイス(HD): </b>リザードフォークはまず2レベルの人型生物になり、2d8のヒットダイス(HD)を得る。

<b>種族技能: </b>リザードフォークの人型生物レベルは5×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は平衡感覚、跳躍、水泳である。尻尾があるため、リザードフォークは跳躍、水泳、平衡感覚判定に＋4の種族ボーナスを持つ。

<b>種族特技: </b>リザードフォークの人型生物レベルは1つの特技を与える。

<b>武器と防具の熟練度: </b>単純な武器と盾を使いこなす。

<b>鎧: </b>外皮ボーナス+5。

<b>肉体武器: </b>2つの爪（1d4）と噛みつき（1d4）。{hlp_nwpn}

<b>息を止める（特殊能力）: </b>リザードフォークは溺れる危険があるまで、自分の耐久力値の4倍に相当するラウンド数、息を止めることができる。
]]
s_liz_man_langs=[[
<b>自動習得言語: </b>共通語と竜語。
<b>ボーナス習得言語: </b>水界語、ゴブリン語、ノール語、オーク語。

<c=twc>リザードフォークは一般的に竜語のみを話すが、比較的知能の高い者は共通語も話す。</c>
]]
s_liz_man_eds={
[race_ed_dd1]=[[
リザードフォークは古代種族で、その起源は時の流れの中で失われている。彼らは自分たちのことを世界そのものと同じくらい古いと信じており、ディノサウルスと一緒に誕生したと主張している。この信念が、伝統と古めかしい技術に頑なにしがみつく文化を生み出した。

それでもリザードフォークは努力を続けているが、その数は、より早く繁殖するウォームブラッド（温血動物）がますます無用の存在となりつつある世界と交流するよりも、湿地帯の原生地の奥深くに引きこもることで減少している。

リザードフォークは誇り高く強力な爬虫類の肉食動物であり、沼地や湿地の奥深くに点在する村に共同住居を構えている。乾いた土地の植民地化には興味がなく、何千年もの間役に立ってきた単純な武器と儀式に満足しているため、リザードフォークは他の多くの種族から僻地の野蛮人と見られている。

しかし、隔離されたコミュニティの中では、リザードフォークは実は伝統に満ちた活気に満ちた人々であり、人類が直立歩行する以前にまでさかのぼる口承の歴史がある。
]],
[race_ed_dd2]=[[
ほとんどのリザードフォークは温帯の沼地に、頑丈に造られた野営地を構える。来訪者には無防備なキャンプに見えるかもしれないが、リザードフォークは川や沼地の防御可能な場所、特に複数の水没した入り口があり、隠れた逃げ道があり、泳げない者でもアクセスできる場所を注意深く選んで居住している。そのようなキャンプには通常1つの部族が住んでおり、そのテリトリーだけで生活している。

リザードフォークは昼間に最も活発に活動する。夜目がなく、爬虫類の血を引いているため寒さに弱いからだ。ほとんどのリザードフォークは日中に狩りや仕事をし、日が暮れると暖かく安全な土の隠れ家に引きこもり、大きな泥炭の焚き火の暖かさを共有しながら他の部族と丸くなる。

リザードフォークは、強力な尾の動きで水中を上手に泳ぎます。彼らは水中で完全に自在に動きますが、空気を呼吸し、繁殖や睡眠のために集合的な丘の住居に戻ります。

ほとんどのリザードフォークは沼地の環境に生息しています。ただし、特別な理由で他の環境に住む共同体もあります。これらの代替リザードフォークは水泳能力を失い、代わりに登攀に熟練しています。
]],
[race_ed_dd3]=[[
メスのリザードフォークは生涯に数個しか卵を産まない。これらの卵はデリケートで、生息地の変化、餌の不足、捕食などの理由から、出産にこぎつけるものはほとんどいない。極端な飢餓の時代には、孵化させることなくその卵塊が部族の糧になることさえある。

有効な卵は常に世話が必要だ。多くの爬虫類がそうであるように、孵化していない子供は温度の変化に反応して性転換する。次の世代の存続がかかっている場合、この現象は非常に重要な意味を持つ。デリケートな卵から孵るのとは対照的に、リザードフォークの子どもは非常にたくましく、歯や爪が生えそろっている。

このように繁殖サイクルの遅い種族には、戦争で損失を出す余裕はない。リザードフォークは他の爬虫類種族や両生類種族と同盟を結ぶこともあるが、自分たちのテリトリーの資源を過度に圧迫しない存在だけを選ぶ。一頭のドラゴン、ナーガの集会、草食ディノサウルスの群れは確立されたリザードフォークの部族と快適に共存できるが、希少な土地を多数のボガードやグリプリと共有することは紛争につながる可能性が高い。
]],
[race_ed_dd4]=[[
数世代に一度、リザードサイオンがリザードフォーク部族に生まれます。通常のリザードフォークの寿命の2倍の寿命と大柄で筋肉質な体格を持つ末裔は、通常、部族のリーダーになることがあります。リザードフォークは、しばしば疑いなく、末裔に対する大きな献身を示し、彼らが精霊からの祝福であり、信仰の存在であると信じています。部族は、彼らを失われた自分たちの偉大さの生きた記念碑と見なし、かつてのリザードフォークがすべて末裔と同じくらい大きくて印象的だった時代の歌を歌います。

リザードサイオンは100歳の誕生日を迎えるまで正式には認められない。その時点で部族は儀式を執り行い、新たに称号を得たリザードサイオンに、地位の印として特別なウォートライデントを贈る。この古代のトライデントは普通のリザードフォークが使うことはなく、ほとんどが何世代にもわたって部族に受け継がれてきた。

リザードサイオンの中には、部族の中で偉大な守護者となり、知恵の代弁者となり、部族をそれまで未知であった偉業へと導き、その隠れ里の中で安定させる者もいる。また、他のリザードフォークの部族と同盟を築こうとしたり、2つの部族を1つにまとめようとする者もいる。しかしながら、先祖代々の領土から組織的に押し出されているリザードフォークの部族は、リザードサイオンの到来を戦争が迫っている兆候と見なし、いわゆる「文明化」された侵入者に対してきっぱりと武器を取るよう駆り立てられるかもしれない。

ある密林や沼地の奥深くには、ディノサウルスを従えたリザードサイオンの部族全体が存在し、種族として真に繁殖しているという噂があるが、そのような話は探検家やトレジャーハンターの過剰な想像に過ぎないのかもしれない。

リザードサイオンの平均身長は10フィートで、体重は500ポンドですが、これは部族や年齢によって異なる場合があります。ボガードの祭司王とは異なり、リザードサイオンは決して太っていませんが、むしろ筋肉質で反応神経の優れた標本です。
]],
[race_ed_phy]=[[
リザードフォークは身長6～7フィート、体重200～250ポンドである。その力強い筋肉は緑、灰色、茶色の鱗に覆われている。背中に短いトゲや鮮やかな色のフリルを持つ種族もいる。

リザードフォークの尾は3～4フィートの長さがあり、平衡感覚を取ったり水泳したりするのに使う。
]],
[race_ed_btl]=[[
リザードフォークは組織化されていない個体として戦う。彼らは正面からの攻撃や集団での突進を好み、時には敵をリザードフォークが有利な水中に押し込もうとする。

多勢に無勢、あるいは自分たちのテリトリーが侵略されている場合は、罠を仕掛け、待ち伏せを計画し、敵の補給を妨げるために襲撃を行う。上級部族はより洗練された戦術を用い、より優れた罠や待ち伏せを用意する。
]],
[race_ed_soc]=[[
リザードサイオンを除いて、ほとんどのリザードフォークは60歳から80歳まで生きる。オスもメスも生涯成長し続け、稀に老化を超越できる者（高レベルのドルイドやアルケミストなど）は100歳前後で大きなサイズに達することもある。このような者はその大きさと部族に関する幅広い知識の両方により、リザードフォーク社会における権力の座を確保することができるが、過去の名残が再び目覚めたと考えられているリザードサイオンのような精神的崇敬を得ることはない。

年老いたリザードフォークは死ぬ日まで部族の生活に貢献します。ほとんどの集落には無活動のメンバーを支援する資源がありませんし、長老は教師、癒し手、または保育士になります。孵化したばかりの幼体でさえ、必要な手先の器用さを達成したら作業に従事します。その作業には、漁網を編む、食事の準備をする、または年少の兄弟姉妹の世話をするなどが含まれます。これらのいずれの作業も部族の生存に不可欠であるため、孵化したばかりの子供たちは少なくとも1人の大人の監督下に置かれますが、それでも人間の同じ年齢の者よりもはるかに高い自律性と責任感を持つようになります。

リザードフォークは悪な存在ではないが、その現実主義が他の種族から忌み嫌われることもある。リザードフォークにとって、肉は肉であり、欠乏の時代に、部族を養うためにその肉を使うのではなく、戦いで倒れた者を腐らせるのは侮辱である。

この固有の実用主義は、リザードフォークの社会関係にも現れています。犯罪、政治活動、内部抗争は、人間の集落とほぼ同じくらい一般的ですが、秩序にして中立の強い感覚がこれらの社会が混乱に陥るのを防いでいます。部族の正義は迅速かつ公平に適用され、ほとんどの紛争は関係者間の致命的でない戦闘で解決されます。場合によっては、これらの紛争を代理の決闘で処理することもあり、片方または両方の側がチャンピオンをスポンサーとして出場させることがあります。
]],
[race_ed_rel]=[[
リザードフォークは非常に孤立しており、長期間にわたって確立された関係を持つグループとのみ取引したり同盟を結んだりします。彼らの社会がそれほど外国人嫌いでなかったとしても、部族を安全に保ち、食料を確保するために必要な作業は、リザードフォークが外部との交流に余裕のある時間がほとんどないことを意味します。これにより、接触は短くて無愛想になる可能性があり、使者の外交的なトリックが、まだ食事の準備をし、自分の卵を守る魔法をかけ、戦士たちの傷を治療しなければならない祈禱師とはあまりうまくいかないかもしれません。しかし、リザードフォークと長い時間を過ごす人々は、これらの生物が何千年もの知識と知恵を伝える豊かな口承伝統を持っていることを見出します。

リザードフォークは外部人を自分たちのキャンプに入れることはほとんどなく、代わりにサブキャンプや目立つ自然の地点で会います。リザードフォークは同盟者や取引パートナーに文化的または宗教的な要求を課しませんが、同様の扱いを期待します。しかし、生態学的な要求をすることがあり、これが摩擦を引き起こす可能性があります。人型生物は、そのような要求を迷信や「未開人」の誤った土着信仰と誤解することがよくありますが、リザードフォークが土地自体に宗教的な意味を置くことはほとんどありません。代わりに、彼らが保護することを決めた地点は、環境を保護するための懸念から行うものであり、彼らの生息地にわずかな変化さえも致命的な影響を及ぼす可能性があるためです。
]],
[race_ed_aln]=[[
一般的には中立だが、リザードフォークはにらみつけるような態度をとり、文明の "贈り物 "を断固として拒否し、戦闘では伝説的な獰猛さを発揮するため、ほとんどの人型生物から否定的に見られている。

というのも、彼ら自身の繁殖速度の遅さは、温血動物である人型生物にはかなわないからであり、湿地帯のテリトリーを死守しない部族は、すぐに哺乳類の大群に圧倒されてしまう。敵も味方も死んだらその死体を食べてしまう彼らの傾向について、現実的なリザードフォークは、沼地での生活は厳しく、無駄なものは何もないとすぐに指摘する。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_liz_pc2="リザード サイオン"
s_liz_pc2_c="この筋骨隆々のリザードフォークは、精巧なデザインで描かれた原始的な巨体で、同種のものの中でもひときわ高くそびえ立っている。"
s_liz_pc2_var_n="部族のリーダー"
s_liz_pc2_var_d="失われた民族の偉大さの生ける記念碑として、リザードサイオンは以下の例外を除き、リザードフォークのすべての人種的特徴を持っている。:"
s_liz_pc2_traits=[[
<b c=tg>筋力+4、敏捷力+2、耐久力+4、判断力+2、魅力+2、<c=tr>知力-2: </c></b>一般的なリザードフォークに比べ、リザードサイオンはより強くたくましく、また柔軟で賢く、リーダーシップの資質を持っている。

<b>鎧: </b>外皮ボーナス+8。

<b>肉体武器: </b>2つの爪（1d6）と噛みつき（1d8）。{hlp_nwpn}

<b>リザードフォークの血（特殊能力）: </b>リザードサイオンは種族に関するすべての効果においてリザードフォークとして扱われる。
]]
s_liz_pc2_d=[[数世代に一度、リザードフォークの部族にはリザードサイオンが誕生する。一般的なリザードフォークの2倍の寿命を持ち、大柄で筋肉質な体格を持つ穂先は、通常部族のリーダーにまで上り詰める。

リザードフォークは、時に疑問を持たずに、リザードサイオンに対して大きな信頼を示し、彼らが霊的な祝福であり信仰存在であると信じています。多くの点で、部族は彼らを自分たちの民族の失われた偉大さの生きた記念碑と見なし、全てのリザードフォークがリザードサイオンと同じくらい大きくて印象的だった時代の歌を歌います。

リザードサイオンの中には、部族の中で偉大な保護者となり、知恵の代弁者となり、部族をそれまで未知であった偉業へと導き、その隠れ里の中で安定させる者もいる。また、他のリザードフォークの部族と同盟を築こうとしたり、2つの部族を1つにまとめようとする者もいる。]]


s_stench="ステンチ"
s_stench_d=[[トログロディートが怒ったり恐れたりすると、ほぼすべての動物生命形態が嫌う油状の、筋肉のような化学物質を分泌します。

トログロディートから30フィート以内にいるすべての生物（トログロディートを除く）は、難易度(DC)13の頑健セーヴに成功しなければ、10ラウンドの間気分が悪くなる。セーヴの難易度(DC)は耐久力に基づく。

セーヴに成功したクリーチャーは24時間、同じトログロディートのステンチの影響を受けなくなる。

ディレイポイズンやニュートラライズポイズンの呪文は、病気になったクリーチャーからその効果を取り除く。

毒に対する免疫を持つクリーチャーは影響を受けず、毒に対する耐性を持つクリーチャーはセーヴィングスローに通常のボーナスを受ける。]]

s_trog="トログロダイト"
s_trog_c="この人型生物のうろこ状の皮はくすんだ灰色をしている。骨格は洞窟トカゲに似ており、長い尾と頭と背中に紋章がある。"
s_trog_fav_cls="トログロダイト部族の間では宗教が強く、祈禱師や司祭は一族の中で最も高く評価されている。"
s_trog_traits=[[
<b c=tg>耐久力+4, <c=tr>敏捷力-2、知力-2:</c></b>トログロダイトは非常に丈夫だが、不器用で原始的で野蛮だ。

<b>種族ヒットダイス(HD): </b>トログロダイトは2レベルの人型生物を持ち、2d8のヒットダイス(HD)を得る。

<b>種族技能: </b>トログロダイトの人型生物レベルは5×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は 隠れ身と 聞き耳である。トログロダイトの皮膚はいくらか色が変わり、カメレオンのように周囲に溶け込むことができ、隠れ身判定に＋4の種族ボーナスを与える（岩場や地下では＋8）。

<b>種族特技: </b>トログロダイトの人型生物レベルは特技を1つ与える。トログロダイトはボーナス特技として複数回攻撃を得る。

<b>鎧: </b>外皮ボーナス+6。

<b>肉体武器: </b>2つの爪（1d4）と噛みつき（1d4）。

<b>武器の熟練度: </b>単純武器に熟練している。

<b>特殊攻撃: </b><t=@pwr_stench c=fc_b>悪臭</t>。
]]
s_trog_langs=[[
<b>自動習得言語: </b>竜語。
<b>ボーナス習得言語: </b>共通語、ジャイアント語、ゴブリン語、オーク語。

<c=twc>トログロダイトは竜語を話す。</c>
]]
s_trog_d=[[
トログロダイトは野蛮な洞窟の住人である。彼らは地下世界の果てしなく続く洞窟の上層部に住む最も人口の多い住人の一人であり、地上や地下に住む者たちの集落を荒らすのはお手の物であるが、彼らの種族が多産で広大な割には、全体としては小さな脅威でしかない。

トログロダイトは最も古い知的種族のひとつである。黎明期、トログロダイト文明は他の人型生物種族より何世代も進んでいた。それらの種族が洞窟に隠れて火を崇拝していたのに対し、トログロダイトは石のジグラット（塔等の構造物）と曲がりくねった運河からなる広大な都市を築き上げた。しかし、他の種族が進化し、文明化が進むにつれて、かつてのトログロダイトの圧制者を凌駕するようになった。今やトログロダイトは洞窟に隠れ、野生の野蛮人の生活を送っている。

トログロダイト部族の間では宗教が強く、祈禱師や司祭は一族の中で最も高く評価されている。
]]
s_trog_eds={
[race_ed_dd1]=[[
トログロダイトは野蛮な洞窟の住人である。彼らは地下世界の果てしなく続く洞窟の上層部に住む最も人口の多い住人の一人であり、地上や地下に住む者たちの集落を荒らすのはお手の物であるが、彼らの種族が多産で広大な割には、全体としては小さな脅威でしかない。

時には、偉大な指導者がトログロダイトの軍団を引き連れて、巨大で致命的な軍隊を作ることもあるが、トログロダイトの部族は自分たちに任せておけば、数多くの確執や人肉食の襲撃、苛烈な内戦で互いを支配下に置いて満足する。

トログロダイトは最も古い知的種族のひとつであり、人里離れた洞窟で発見された遺跡は、かつて彼らの帝国が世界最大規模であったことを物語っている。

黎明期、トログロダイト文明は他の人型生物種族より何世代も進んでいた。それらの種族が洞窟に隠れて火を崇拝していたのに対し、トログロダイトは石造りのジグラット（塔等の構造物）や曲がりくねった運河からなる広大な都市を築き、他の種族を奴隷として飼い、古代の非人間的な神々や悪魔を崇拝していた。

しかし、他の種族が進化して文明化が進むにつれて、かつてのトログロダイトの圧制を凌駕するようになった。現在では役割が変わり、トログロダイトが洞窟に隠れて野生の野蛮人の生活を送っている。
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
トログロダイトは身長約150センチ、体重約150キロである。トログロダイトは竜語を話す。
]],
[race_ed_btl]=[[
トログロダイトの集団の半数は爪と歯だけで武装しており、残りは1、2本の槍と棍棒を持っている。

通常は身を隠し、槍の一撃を放ち、接近して攻撃する。戦闘が不利になると後退し、身を隠そうとする。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
トログロダイトの部族間では宗教が強く、祈禱師や司祭は普遍的に一族の中で最も高く評価されるメンバーである。トログロダイトの酋長が常にクレリックやドルイドであるとは限らないが、神の力を持たない者は通常、地元の予見者や祈禱師の言いなりになる単なる口先番長や操り人形の領主にすぎない。

トログロダイトは一般的に無数の魔王のうちの1人を崇拝しており、特に爬虫類や原始的な姿や形をした魔王や、トログロダイトが好む絡み合った洞窟に最もよく似た深淵の領域を持つ魔王を崇拝している。

トログロダイトドルイドは通常、同族と一緒に暮らしている場合は中立にして悪である（そして、獣に対する不気味な統率力を持つことから、誰からも恐れられ、尊敬されている）。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_gnoll		= "ノール"
s_gnoll_c	= "猫背で野性的なこのハイエナ頭の人型生物は、平均的な人間よりもわずかに背が高い。"
s_gnoll_d	= [[ノールはハイエナの頭をした邪悪な人型生物で、緩やかな部族を形成して放浪している。

ノールは単なる外見だけでなく、ハイエナによく似ている。ハイエナをペットとして飼うほど、ハイエナとの親和性が高く、ハイエナ以下の生き物の行動の多くを反映している。

ノールは夜行性の肉食動物で、知能の高い生き物の方がよく鳴くため、食料として好む。]]
s_gnoll_fav_cls="ノールのリーダーは通常レンジャーであるが、クレリックも高く評価されている。ほとんどのノールはアーケインの魔法を使いこなすことが難しく、そのためノールのバード、ソーサラー、ウィザードを見かけることは比較的稀である。"
s_gnoll_traits=[[
<b c=tg>筋力 +4、耐久力 +2、<c=tr>知力 -2、魅力 -2: </c></b>ノールは強くて丈夫だが、頭の回転が遅く、ハイエナのような外見からほとんどの種族は嫌悪感を抱く。

<b>種族ヒットダイス(HD): </b>ノールはまず2レベルの人型生物を得て、2d8のヒットダイス(HD)を得る。

<b>種族技能: </b>ノールの人型生物レベルは5×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は聞き耳と視認である。

<b>種族特技: </b>ノールは人型生物レベルで特技を1つ得る。

<b>武器と防具の熟練度: </b>単純武器、軽装鎧、盾の扱いに習熟する。

<b>鎧: </b>外皮ボーナス+1。
]]
s_gnoll_langs=[[
<b>自動習得言語: </b>ノール語。
<b>ボーナス習得言語: </b>共通語、竜語、エルフ語、ゴブリン語、オーク語。

<c=twc>ノールは通常ノール語しか話さないが、比較的知能の高い者は共通語も話す。</c>
]]
s_gnoll_eds={
[race_ed_dd1]=[[
ノールは単なる外見だけでなく、ハイエナに似た巨体の人型生物の種族である。彼らはハイエナをペットとして飼うほど、ハイエナとの著しい親和性を示し、ハイエナ以下のクリーチャーの行動の多くを反映している。

ノールは有能なハンターであるが、外に出て獲物を追いかけるよりも、獲物をあさったり盗んだりする方がはるかに幸せである。この怠け癖のために、彼らはどんな種類の奴隷でも手に入れることができ、その奴隷に巣穴を掘らせたり、物資や水を集めさせたり、さらにはノールの主人のために狩りをさせたりする。
]],
[race_ed_dd2]=[[
ノールは戦闘を好むが、それは明らかに数の優位がある場合に限られる。それ以外の状況では、他のハンターから獲物を仕留める手段や、大物を仕留めるための巧妙な待ち伏せ以外の戦闘は避けたがる。このハイエナ族は勇気や勇敢さに価値を見いださず、勝利が不可能だとわかると逃げることを好む。

戦闘中、ノールは群れでの戦術と個々でのにらみ合いの奇妙な混合を用いる。ノールは自分が勝っていると感じると、仲間を助けるのではなく、より弱い存在を倒そうとする。ノールたちが苦戦している場合は、強力なリーダーに集団で近づき、そのクリーチャーを倒そうとし、味方を逃走させようとする。

ノールのリーダーは通常レンジャーであるが、クレリックも高く評価されている。ほとんどのノールはアーケインの魔法を使いこなすことが難しく、そのためノールのバード、ソーサラー、ウィザードを見かけることは比較的稀である。
]],
[race_ed_phy]=[[
ノールの群れは母系制をとっており、その理由はメスの方がオスよりも体が大きく、攻撃的で狡猾な傾向があるからだ。大きさはさておき、メスとオスのノールの外見に肉体的な違いはほとんどない。

平均的なノールのオスの身長は7フィート、メスの身長は7フィート、体重は300ポンドだが、ノールは前かがみの姿勢のため、男女ともに背が低く見える。

ほとんどのノールは汚れた黄色か赤茶色の毛をしている。
]],
[race_ed_btl]=[[
ノールは数の有利な時に攻撃することを好み、大群戦術と体力を駆使して相手を圧倒し、打ちのめす。

強力なリーダーがいない限り、戦闘時に規律をほとんど示さない。そのような時は隊列を維持し、一丸となって戦うことができる。

通常、罠を仕掛けることはないが、待ち伏せを使ったり、側面から攻撃しようとしたりする。

盾を持つノールは隠れるのが苦手であるため、待ち伏せを仕掛ける際には常に有利な条件（暗闇、隠れ家、その他の有利な地形など）を求めて特別な注意を払う。
]],
[race_ed_soc]=[[
ノールの群れは、支配力を競い合うことを基本とする重層的な構造をしており、その頂点に立つのが1頭のアルファ（通常、最も大きく力のある雌のノール）である。まれに、群れの集団がさらに複雑で移り変わりの激しい序列体系の中でかみ合い、部族や大群を形成することもある。これは極めて強力なリーダー、つまりアルファノールや虐待者の来訪者が統率している場合に限られる。

ノールは生まれや地位よりも、権力とそれをうまく行使する冷酷さを重んじる。ノールが群れの権力を握っているのは、彼または彼女が恐れられ、尊敬されているからであり、彼がそうであり続ける限りそうである。このため、群れのリーダーが死んだり、病弱になったり、面目を失ったりすると、権力への渇望と優位を主張する能力を持つあらゆるノールが、短時間で血みどろの権力争いを繰り広げた後に権力が交代する。このような出世争いはしばしば群れを分裂させ、失敗したアルファとその支持者は群れから追われることになる。これは分裂した群れの間に強力なライバル関係を生み出すこともあるが、しばしば追放されたノールは過去を捨て去り、新しい土地で狩りを追求し、繁殖を増やし、新たな獲物を求めて暴れまわることで新たな権力基盤を築こうとする。
]],
[race_ed_rel]=[[
ハイエナや他のノール以外の生き物は、部族の気質によって肉か奴隷のどちらかになる。死んだり倒れたりした仲間であっても、ノールにとっては新鮮な食事である。優れた部族の一員には短い祈りを捧げて敬意を表したり、衰弱した病気で死んだ仲間には徹底的に調理したりするが、そうでなければ死んだノールを他の生き物とほとんど変わらないと見なす。より "文明的 "なノールは捕虜を食べることはないが、その代わりに奴隷として飼育し、自分たちの隠れ家を守ったり、改良したり、他の部族や奴隷商人たちとの交易に使ったりする。

たとえノールの群れが群れの外から来た強力な主人に仕えるとしても、それは自分たちの生存だけを考えてのことであり、その主人に仕え続けることが自殺行為になるなら、すぐにその主人を見捨てる。他の種族はノールを利己的で怠け者で、最終的には破壊的だと見下すかもしれないが、ノールはそのような判断をただクスクスと笑うだけである。ノールにとって生存こそが唯一の道徳であり、敵を食べることこそが究極の力の誇示なのだ。群れに属さない生き物は、動く肉以外の何物でもない。
]],
[race_ed_aln]=[[
ノールは厳格な肉食動物であり、非常に困った時や宗教的儀式の時、ライバルを倒した後に自分の優位性を示すために共食いに走ることもある。しかし、彼らの肉の大半は狩りで得たものである。

ほとんどどんな種類の肉でも栄養を補給することができるが、彼らは知覚を持つ生物の肉を強く好む。この嗜好は実用的であると同時に（知覚を持つクリーチャーは群れの安定と生存にとって大きな脅威であるため）、クリーチャーを食べることでそのパワーを吸収できるというノールによくある迷信と結びついている。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_catfolk		= "キャットフォーク"
s_catfolk_c		= "このしなやかで猫のような人型生物は、長い尻尾と尖った耳を持っている。ネコのような目は好奇心といたずら心で輝いている。"
s_catfolk_d		= [[
優美な探検家の種族であるキャットフォークは、元来仲間意識が強く、好奇心旺盛である。自分を大切に扱い、その境界線を尊重してくれる種族と仲良くなる傾向がある。物理的にも知的にも探検を好み、天性の冒険家になる傾向がある。

探検精神に突き動かされ、名声と冒険を求めて人間の土地に迷い込む者も少なくない。人間、エルフ、ドワーフ、ハーフリングなどで構成される冒険団の信頼できる同胞となったキャットフォークも複数いる。
]]
s_catfolk_eds={
[race_ed_dd1]=[[
キャットフォークは天性の探検家であり、開拓に飽きることはめったにないが、そのような開拓は単に遠い土地で新たな地平線を探すことに限定されるものではない。多くのキャットフォークは、個人の成長と発展も同様に有効な探検の道だと考えている。

ほとんどのキャットフォークは機敏で能力があり、しばしば活動的な生き物だが、一部のキャットフォークには静かな思索や研究に従事する強い傾向もある。そのような人々は、古くからある問題に対する新たな解決策を見つけたり、その時々の最も確固とした哲学的確信にさえ疑問を投げかけたりすることに興味を持つ。彼らはもともと好奇心が旺盛で、キャットフォークの文化は決して探究心を抑制するものではなく、むしろそれを育み、奨励するものである。

他の種族からは風変わりな外向的人間として見られることが多いが、キャットフォークの部族内では、些細な癖や奇抜さ、無鉄砲さを恥じることはない。

最も内向的なキャットフォーク以外は皆、注目の的になることを楽しむが、それが生まれながらの部族であれ、他のクリーチャーとの友情の絆を通じて選んだ部族であれ、自分たちの部族を犠牲にしてはならない。キャットフォークは家族や友人に寛大で忠実な傾向がある。
]],
[race_ed_dd2]=[[
ほとんどのキャットフォークは自然と共生する狩猟採集民だが、一部の部族は都市環境にうまく適応している。

文化として、キャットフォークは忠実で、寛大で、友好的である。彼らは、自分たちのニーズや欲求を達成するために協力し合う集団に属し、その集団と調和することを好む。

部族のキャットフォークは最も有能な社会メンバーがリーダーであることを好むため、どの部族にも高位の副族長からなる評議会がある。部族の長は通常、その部族で最も有能な（そして魔法的に才能のある）メンバーである。

個人の成長はキャットフォークの文化の一部であり、個人的な探求の手段としての表現も同様である。キャットフォークにはタブーがほとんどなく、無害だが奇妙な奇行をしばしば見せる。

個々人は幅広い追求と自己表現を培い、他の者が賢明でないとレッテルを貼るようなリスクを冒す。ほとんどのキャットフォークは注目の的になることを好むが、グループの結束を犠牲にすることはない。
]],
[race_ed_phy]=[[
一般的に、キャットフォークはしなやかで細身であり、ドワーフと人間の中間的な体格をしている。

明らかに人型生物だが、柔らかな上質な毛並み、切れ長の瞳孔、すらりと伸びた尻尾など、多くのネコ科動物の特徴を備えている。

耳は尖っているが、エルフのそれとは異なり、丸みを帯びた猫耳である。猫のようなひげは珍しくないが、普遍的なものではなく、髪や目の色も様々である。

彼らは他の人型生物と同じように簡単に物体を操るが、指の先は小さく鋭く、収納可能な爪になっている。この鉤爪は通常、武器として使えるほど強力ではないが、生まれつきのクセか、長年の研鑽の賜物か、致命的な効果を発揮する者もいる。
]],
[race_ed_btl]=[[
キャットフォークは衝動的に戦闘に飛び込む傾向がある。戦闘が不利になると、躊躇なく逃げ出す。
]],
[race_ed_soc]=[[
自己表現はキャットフォーク文化の重要な側面ではあるが、それは強い共同体意識と集団努力によって緩和されている。野生ではキャットフォークは狩猟採集の部族民である。個人の力の追求が部族の健康と福祉に優先することはない。この一見穏やかな種族を過小評価した種族が何人もいたが、その結束力が彼らに大きな力を与えていることに気づくのが遅すぎた。

キャットフォークは最も有能なメンバーによって率いられることを好み、通常、コンセンサスか選挙によって仲間から選ばれた副酋長からなる評議会を構成する。そして副酋長たちは、危険なときに指揮を執り、副酋長間の争いを調停する酋長を選ぶ。酋長は部族の中で最も有能なメンバーであり、多くの場合、魔法の才能に恵まれている。

より都会的で文明化された地域に定住するキャットフォークは、依然として同様の部族構造に固執しているが、しばしば部族外の友人、たとえ他種族の友人であっても、彼らの拡大した部族の一部とみなす。

冒険者集団の中では、自分が酋長としてふさわしいと思わないキャットフォークは、自分たちの文化的理想とする酋長に最も似ている人物に従うことが多い。
]],
[race_ed_rel]=[[
順応性が高く好奇心旺盛なキャットフォークは、互恵的な好意を寄せてくれるならば、ほとんどの種族と仲良くなれる。ハーフリング、人間、そして特にエルフには容易に馴染む。

キャットフォークとエルフは情熱的な性格を共有し、音楽、ダンス、物語を愛する。エルフのコミュニティはしばしばキャットフォークの部族を優しく指導するが、そのようなエルフはネコ科の友人に対して恩着せがましい態度を取らないように注意している。

ノームはキャットフォークにとって自然な仲間になる。キャットフォークはノームの奇妙で執着的な性質を楽しむからだ。キャットフォークは爬虫類であるコボルドがキャットフォークの境界を尊重する限り、コボルドに対して寛容である。キャットフォークはしばしばゴブリンやラットフォークを害獣と見なし、それらの種族が持つ群生や悪質な傾向を軽蔑する。

キャットフォークにはオークの野蛮さと自己破壊の傾向が理解できないため、オークの野性的な性質はキャットフォークの反発と同じくらい困惑をかき立てる。一方、ハーフオークはキャットフォークの興味をそそる存在であり、特にハーフオークはその野蛮な親族の有害で憎むべき性質を超えた存在になろうと努力している。
]],
[race_ed_aln]=[[
彼らの文化の中心には共同体や利他的行動の協力があり、またお人好しの好奇心や他の多くの種族の習慣に順応する意欲もあるため、ほとんどのキャットフォークは善属性へ向かう傾向がある。

キャットフォークもまた、判断力が最も得意とする美徳ではないため、大多数は混沌としている。
]],
[race_ed_adv]=[[
生まれながらの追跡者であり、狩猟採集民としての側面を持つキャットフォークは、デフォルトでレンジャーとしての職業に就くことを余儀なくされるが、そのような役割は、歌や踊り、語り部など、芸能、芸術が好きな彼らにとっては必ずしも好都合ではない。

キャットフォークの伝説には、偉大なソーサラーの英雄の豊かな伝統も語られている。放浪癖を内に秘めたキャットフォークは、しばしばウィザードやモンクになる。

キャットフォークは、探求と自己認識がさまざまな道につながることを理解しており、ほとんどすべての職業や生き方を受け入れている。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
カルース,ドレワン,フェルス,ゲラン,ニュクタン,ルーカー,ジテンベ。

<c=twa>女性名:</c>
アリャラ,ドゥリネ,ホヤ,ジリャーナ,ミラ,ミニリ,シフェレレ,ティエリ。
]],
}


-- 巨人		Giant


s_ogre="オーガ"
s_ogre_c="このゴツゴツした巨人のギョロっとした目には機知も優しさもなく、膨れ上がった顔には大きな口と不釣り合いな歯がある。"
s_ogre_fav_cls="オーガは生来混沌に傾倒しており、その体格と力強さが相まって天然のバーバリアンとなっている。実際、オーガの指導者はほとんどの場合、低レベルから中レベルのバーバリアンであり、戦闘におけるその怒りは実に恐るべきものである。荒れ狂うオーガのバーバリアンは他のオーガにインスピレーションを与える。"
s_ogre_traits=[[
<b c=tg>筋力+10、耐久力+4、 <c=tr>敏捷力-2、知力-4、魅力-4: </c></b>オーガは非常に強く頑強だが、不器用で愚か、無作法で野蛮で、耐え難い悪臭を放つ。

<b>種族ヒットダイス(HD): </b>オーガは4レベルのジャイアントから始まり、4d8のヒットダイス(HD)を得る。

<b>種族技能: </b>オーガのジャイアントレベルは7×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は登攀、聞き耳、視認である。

<b>種族特技: </b>オーガのジャイアントレベルは2つの特技を与える。

<b>武器と防具の熟練度: </b>単純武器と軍用武器、軽装鎧・中装鎧、盾に熟練している。

<b>鎧: </b>外皮ボーナス+5。
]]
s_ogre_langs=[[
<b>自動習得言語: </b>共通語とジャイアント語。
<b>ボーナス習得言語: </b>ドワーフ語、オーク語、ゴブリン語、地界語。

<c=twc>オーガはジャイアント語を話し、知力値が10以上の個体は共通語も話す。</c>
]]
s_ogre_d=[[
オーガとの遭遇の特徴である、腐敗臭や、とぼけた愚かさ、野蛮な堕落に備える冒険者はほとんどいない。オーガは、その威圧的な大きさで劇的な第一印象を与える。身長9～10フィートのオーガは、ほとんどの人型生物よりも高くそびえ、その恐ろしく太い腕と脚は、巨大で不格好な筋肉で膨れ上がっている。

オーガはひねくれた獣であり、家族の絆を固めるために近親交配をする習性があるため、他の種族よりも身体的欠陥や突然変異に悩まされる率が劇的に高い。

オーガはジャイアントの中で最も粗野で最も人口の多い種族であるが、何世代にもわたる近親交配と異種交配が横行し、ジャイアント族をあざ笑うかのような種族へと変貌を遂げた。加えて、オーガは最も行動範囲が広く、ほとんどあらゆる地形で遭遇する。
]]
s_ogre_eds={
[race_ed_dd1]=[[
オーガとの遭遇の特徴である、腐敗臭や、とぼけた愚かさ、野蛮な堕落に備える冒険者はほとんどいない。オーガは、その威圧的な大きさで劇的な第一印象を与える。身長9～10フィートのオーガは、ほとんどの人型生物よりも高くそびえ、その恐ろしく太い腕と脚は、巨大で不格好な筋肉で膨れ上がっている。

オーガはジャイアントの中で最も粗野で、最も人口の多い種族であるが、何世代にもわたる乱暴な近親交配と異種交配の結果、ジャイアント族を嘲笑するような種族になってしまった。そのため、他のジャイアント族はオーガを嫌悪し、嘲笑的な軽蔑の目でこの弱い従兄弟を扱っている。しかし、孤立した家族と社会病質的傾向を持つオーガは、このような意見をほとんど気にせず、オーガの一族は他の生物と同じように孤独なジャイアントを捕食する可能性が高い。

オーガはひねくれた獣であり、家族の絆を固めるために近親交配をする習慣があるため、他の種族よりも身体的欠陥や突然変異に悩まされる割合が劇的に高い。オーガはその奇形を、彼らが崇拝する闇の神の印とみなしている。この同じ迷信がオーガに美しい生き物を軽蔑させる。機会があれば、彼らはわざわざ最も魅力的な犠牲者を切り刻み、拷問する。

ジャイアントの中で最も数が多いことに加え、オーガは最も行動範囲が広く、ほとんどあらゆる地形で遭遇する。砂漠地帯を彷徨う褐色の肌のオーガもいれば、極寒の地を彷徨う青白い肌の毛むくじゃらのオーガもおり、森や沼地、広大な平原に生息する一族も数多くいる。
]],
[race_ed_dd2]=[[
ジャイアントの中で最も数が多いだけでなく、オーガは最も行動範囲が広く、ほとんどあらゆる地形で遭遇する。砂漠地帯を彷徨う褐色の肌のオーガもいれば、極寒の地を彷徨う青白い肌の毛むくじゃらのオーガもおり、森や沼地、広大な平原に生息する一族も数多くいる。

以下は、オーガの中でも特殊な2つのタイプである。

<b>メロウ</b>
オーガのいとこで、水棲の亜種。淡水の湖や川に生息する。水生環境にのみ生息する。

典型的なオーガはグレートクラブではなく、近接戦闘ではロングスピアを使う。

<b>オーガメイジ</b>
オーガメイジは、魔法を使わないオーガよりも知力が高く、より危険な種類です。オーガメイジは、魔法のような能力に頼り、肉体的な戦闘は必要な時にしか行いません。明らかに優れた力に直面した場合、彼らは敗北の戦いをするよりもガス状態で撤退することを好みます。

オーガメイジは約10フィートの高さがあり、最大で700ポンドの重さがあります。彼らの肌の色は明るい緑から明るい青までさまざまで、髪の毛は黒色または非常に濃い茶色です。オーガメイジはゆったりとした快適な服と軽量な鎧を好みます。

オーガメイジはジャイアント語と共通語を話す。
]],
[race_ed_dd3]=[[
オーガについては、残忍さと野蛮さ、カニバリズムと拷問の恐ろしい物語が語られている。レイプや四肢切断、屍姦、近親相姦、切断、あらゆる醜悪な殺人の話である。オーガに遭遇したことのない者は、警告としてその話を知っている。そのような遭遇を生き延びた者は、これらの物語が真実に比べれば無味乾燥なものであることを知っている。

オーガは他人の不幸を喜ぶ。より小さな種族が肉付きのよい拳で押しつぶしたり、血で赤く染まった暴力の欲望で汚したりする相手がいないとき、彼らは互いに娯楽を求め合う。オーガ社会にタブーはない。オーガの部族は、放っておけばすぐにバラバラになり、最後には最も強い者だけが生き残ると考えるだろうが、オーガが尊重するものがあるとすれば、それは家族である。

オーガの部族は家族として知られており、彼らの奇形や醜い特徴の多くは、近親相姦の一般的な慣習から生じている。部族のリーダーは父親であることが多いが、特に凶暴で支配的なオーガが母親の称号を主張する場合もある。オーガの部族は互いにいがみ合うが、それは近隣の種族を敵に回すのではなく、互いを敵に回して忙しくさせるというありがたい特徴である。しかし、オーガの中で特に凶暴で恐れられる家長が何度も台頭し、複数の家族を配下に集めることができる。

オーガが住んでいる地域は陰気で醜い場所である。なぜなら、ジャイアントは粗末に暮らし、環境と調和して生きる必要性をほとんど感じていないからである。文明とオーガの領土の境目は、追放者と絶望の絶望的な領域である。なぜなら、ここにはオーガキンが住んでいるからである。オーガは異形の子孫であり、小民族の土地に対する頻繁なオーガの襲撃の結果である。

オーガのゲームは暴力的で残酷であり、彼らが娯楽に使う犠牲者は、初日に死ねば幸運である。オーガの残酷なユーモアのセンスは、彼らの粗野な心が創造性を発揮する唯一の方法であり、オーガが考案する拷問の道具や方法は常に悪夢のようである。

オーガの大きな力と想像力の欠如は、採掘、鍛造、整地などの重労働に特に適しており、より強力なジャイアント（特にヒルジャイアントとストーンジャイアント）はしばしばオーガの家族を服従させ、そのような点で彼らに奉仕させる。
]],
[race_ed_dd4]=[[
オーガの狩りは、生き物を疲れ果てるまで走らせるか、大きな円陣を組んで獲物を中心に追い込んで屠るかのどちらかである。小さなオーガの狩猟隊が何日も鹿の群れを追いかけ、はぐれた鹿を捕らえ、将来の食用にすることもある。

オーガは人間や他の知的な獲物を狩るために、これらのテクニックのバリエーションを用いる。オーガは獲物の恐怖と絶望を楽しむため、実際の狩りは最終的な殺戮以上の喜びを与えることがある。そのため、彼らの狩りの多くは贅沢で無駄の多いものになるという不幸な副作用がある。

オーガも純粋な拷問に満足感を見出すが、彼らの技量はせっかちで、人型生物の生理的限界をよく理解していないために限界がある。オーガから見れば、この手の野蛮人の拷問行為はたいていあっという間に終わってしまうが、早く終わることで食事の時間が早まるため、ほとんどのオーガは後悔していない。
]],
[race_ed_phy]=[[
オーガの成体は身長9～10フィート、体重600～650ポンドあり、ほとんどの人型生物よりも高くそびえ立ち、その恐ろしく太い腕と脚は巨大で不格好な筋肉で膨れ上がっている。

肌の色はくすんだ黄色からくすんだ茶色まである。彼らの衣服は粗末な毛皮や皮で構成されており、それが彼らの生来の忌避臭に拍車をかけている。

オーガはひねくれた獣であり、他のどの種族よりも劇的に高い確率で身体的欠陥や突然変異に苦しんでいる。
]],
[race_ed_btl]=[[
オーガは、フェアな戦いよりも圧倒的な戦力、奇襲攻撃、そして待ち伏せを好みます。

彼らは十分な知性を持ち、まず射撃武器を撃ち、敵を弱体化させてから接近するが、オーガの盗賊集団や戦闘グループは組織化されていない個体として戦う。
]],
[race_ed_soc]=[[
オーガは通常、"ボス "として知られる強力な家長または母長が独占的に率いる、半ダースから10ダースの大人と子供で構成される家族グループを形成する。より大きな家族も存在することが知られているが、オーガは破壊的であるため、12人以上の一族を養える地域はほとんどなく、これらのグループは飢えと内紛のために解散するのが普通である。オーガの一族の中ではボスの権力は絶対的で、彼女が執行する掟だけがある。寵愛を受けたメンバーは、食事で最もおいしい料理と最高の寝具を手に入れるが、寵愛を失ったメンバーは空腹に耐えかね、厳しい殴打と度重なる虐待の対象として選別される。にもかかわらず、オーガの一族はかなり結束が固い。

オーガの家族にとって、食料と生存はともに絶え間ない問題である。この大きな獣は生き残るために膨大な量の肉を必要とするが、農業や畜産といった平凡な仕事にはほとんど忍耐がないため、略奪、強奪、殺戮によって食料を満たしている。オーガは完全に殺人に頼っているわけではなく、ハンターや罠猟師として行動する者もいる。オーガは不況時には共食いを躊躇しない。飢饉の間、病人や病弱な者は長くは生き残れないし、ライバルと思われる者はシチュー鍋を満たし、反対意見を排除するために静かに殺されるかもしれない。健康で良好な関係にある家族でさえ、ボスが空腹の状態が長く続けば、夕食の皿に乗ることになるかもしれない。
]],
[race_ed_rel]=[[
オーガはより小さな生き物を獲物と見なし、戦えば勝てないと思った場合か、交渉によってより大きな報酬が得られると確信できた場合にのみ手を止める。冒険者たちは、秘密の財宝の約束でオーガを騙して解放させたという話をする。しかし最終的には、オーガの食欲が仲間意識や将来的な報酬のことよりも勝ってしまうことを、ほとんどの策略家は発見する。

最も愚かなオーガの一族でさえ、人間の居住地に近づくと警戒するようになる。オーガは人間が脅威にさらされると団結することを知っているため、一族は社会の片隅で餌食になることが多く、小さな村や武装の不十分な旅団、孤立した農家などに攻撃を集中させる。彼らはエルフの土地を避ける傾向がある。エルフは彼らの森に入る勇気のあるオーガを殺すし、オーガは彼らの巣穴からドワーフを掘り出すことにはほとんど興味がないからである。オーガはノームやハーフリングのような小柄な人型生物を、人間に似た生き物の中で最も美味なものと見なし、しばしば夢中になって小さな獲物を追いかけるが、そのような小柄な生き物が自分たちよりも賢いかもしれないとは思いもしない。ハーフリングやノームが悪知恵を働かせて大きくて愚かなジャイアントを倒したという話はたくさんある。

オーガは過去に大軍に組み入れられたことがあるが、たいていは他のクリーチャーが食料の約束で彼らを勧誘し、過酷な懲罰で彼らを従わせた場合に限られる。強力なジャイアント（あるいはヒューマン）の将軍の旗の下、設備の整ったオーガ連隊は壊滅的な大群を形成する。オーガの強さと頭の悪い大胆不敵さは、優れた衝撃部隊となる。それでも、そのような指揮官は、建造物や住民への被害を最小限に抑えて占領したい都市に対しては、この残忍で衝動的なジャイアントを派遣しないことをすぐに学ぶ。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_troll="トロール"
s_troll_c="この背の高いクリーチャーは荒々しい緑色の皮を持っている。手には爪があり、獣のような顔には恐ろしい牙の下顎がある。"
s_troll_fav_cls="一部のトロールは他のトロールよりも狡猾で、文明人を食べるだけでは飽き足らず、執拗に狩る訓練を積んでいる。このようなトロールハンターは、人型生物の獲物を殺害し、貪り食うことに専念する恐るべきレンジャーである。トロールハンターは好みの敵を追跡するためにその匂いの能力をフルに活用し、一般的に暗闇での狩りを好む。トロールハンターは限られた呪文のレパートリーで、有害なエネルギーから身を守り、敵を動けなくする。"
s_troll_traits=[[
<b c=tg>筋力 +12、敏捷力 +4、耐久力 +12、 <c=tr>知力 -4、判断力 -2、魅力 -4: </c></b>トロールは強くてタフで機敏だが、間抜けで鈍くて醜い。

<b>種族ヒットダイス(HD): </b>トロールは6レベルのジャイアントから始まり、6d8のヒットダイス(HD)を得る。

<b>種族技能: </b>トロールのジャイアントレベルは9×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は聞き耳と視認である。

<b>種族特技: </b>トロールのジャイアントレベルには3つの特技がある。

<b>鎧: </b>外皮ボーナス+1。

<b>肉体武器: </b>2つの爪（1d6）と噛みつき（1d6）。{hlp_nwpn}

<b>特別な資質: </b><t=@pwr_rend c=fc_b>引き裂き</t>, <t=$s_hp_reg_nd c=fc_b>リジェネレイション5</t>, <t=@pwr_scent c=fc_b>嗅覚</t>。
]]
s_troll_langs=[[
<b>自動習得言語: </b>ジャイアント。
<b>ボーナス習得言語: </b>共通語とオーク語。

<c=twc>トロールはジャイアント語を話す。</c>
]]
s_troll_d=[[
トロールは信じられないほど鋭い鉤爪と驚異的な再生能力を持ち、どんな傷でもほとんど回復することができる。彼らは前かがみで、幻想的なほど醜く、驚くほど強い。鉤爪と相まって、その強さは文字通り肉を引き裂き、貪欲な食欲を養うことができる。

トロールは食欲旺盛で再生能力もあるため、恐れを知らぬ戦闘民族であり、最も近くにいる生物に真っ向から突進し、怒りの限りを尽くして攻撃する。トロールが躊躇するのは火（または酸）だけのようだが、この致命的な脅威でさえトロールの前進を止めるには十分ではない。

トロールは毎日大量の食料を消費しなければ飢餓に直面するため、ほとんどの時間を狩りに費やしている。
]]
s_troll_eds={
[race_ed_dd1]=[[
トロールは信じられないほど鋭い鉤爪と驚異的な再生能力を持ち、どんな傷でもほとんど回復することができる。彼らは前かがみで、幻想的なほど醜く、驚くほど強い。鉤爪と相まって、その強さは文字通り肉を引き裂き、貪欲な食欲を養うことができる。

トロールは食欲旺盛で再生能力もあるため、恐れを知らぬ戦士であり、手近な生物に真っ向から突進し、怒りの限りを尽くして攻撃する。トロールが躊躇するのは火と酸だけのようだが、この致命的な脅威でさえトロールの前進を止めるには十分ではない。トロールとよく戦う者は、戦いの後、どんな破片でも探し出して燃やすことを知っている。幸いなことに、この方法で再生するのはトロールの最も大きな部分だけである。

すべてのトロールはほとんどの時間を狩りに費やし、毎日大量の食料を消費しなければ飢餓に直面する。この必要性から、ほとんどのトロールは広大な縄張りを自分のものとし、ライバル同士の戦いはよくあることだ。通常は致命的なものではないが、トロールは互いの弱点を知っており、食料が不足すればその知識を利用して同族を殺すこともある。

トロールは戦闘では残酷だが、自分の子供には驚くほど優しく親切である。メスのトロールは集団で行動し、若いトロールに狩りと自活を教えるのに多くの時間を費やし、その後自分のテリトリーを見つけるために送り出す。オスのトロールは孤独に生きる傾向があり、メスとパートナーを組むのは交尾のための短い期間だけである。
]],
[race_ed_dd2]=[[
民話を信じるなら、トロールは孤独な獣であり、原野から獲物を奪ってから、国境の村や遠く離れた民家で暴れ回り、家畜も守備兵も食べ尽くし、食べ物がなくなったり、守備兵が炎で追い払ったりして初めて移動する。

しかし、レンジャーやドルイドなどの熟練冒険者たちは、こうした孤立したトロールがすべてではないことを知っている。トロールは荒野の奥深くで、冷酷なまでに現実的な女性たちに率いられた一族が旅をしながら暮らしている。

トロールが一般的に危険で利己的で邪悪な怪物であることは事実だが、トロールの文化と社会は奇妙で複雑な矛盾の塊である。トロールは若者を大切にし、部族の存続を脅かすものは凶暴に殺すか追放する。追放された者たちは、部族単位にとっても部族外の生物にとってもさらに危険な存在となる傾向があり、より大胆で貪欲になり、他のトロールを含むあらゆる生物を獲物として扱うようになる。そのような追放者がより人口の多い地域に入り込むと、彼らの破壊的な行動が一般的に語られるトロールの物語を生む。

集団で行動するトロールはより用心深く、文明を避ける傾向にあるが、それでも統一された狩猟や襲撃においては、組織化された殺戮の嵐となりうる。そして多くの部族がトロールの君主のもとに団結することができれば、トロールの轟音で地面が揺れ動き、食用になるものはすべて引き裂かれ、腹を満たすために飲み尽くされる。幸いなことに、このようなトロールの集まりは稀であり、内紛や団結していた脅威の消滅、あるいは乱獲によって燃え尽きることが多い。
]],
[race_ed_dd3]=[[
一般的な種族に加えて、いくつかの特殊なタイプのトロールが存在する。また、いくつかの種類のトロールは異なる環境（冬の土地、深い洞窟、海など）に適応する能力を持っている。異なるタイプのトロールは通常、互いに親近感を抱くことはない。

<b>トロールハンター</b>
一部のトロールは他のトロールよりも狡猾で、文明人を食べるだけでは満足せず、執拗に狩る訓練を積んでいる。このようなトロールハンターは、人型の獲物を殺して食い尽くすことに専念する恐るべきレンジャーである。

トロールハンターは匂いの能力を駆使して好みの敵を追跡し、一般に暗闇での狩りを好む。トロールハンターは限られた呪文のレパートリーで、有害なエネルギーから身を守り、敵を動けなくする。

<b>スクラッグ</b>
トロールの従兄弟であるこの種族は水棲のサブタイプを持つ。スクラッグの基本陸上速度は20フィート、遊泳速度は40フィートで、冷たい水生環境にのみ生息している。

スクラッグの再生能力は、ほとんどが水に浸かっている場合にのみ働く。

スクラッグの外見は、陸上の従兄弟たちよりも獣っぽくないが、暴力的であることに変わりはない。
]],
[race_ed_dd4]=[[
トロールの最大のモチベーションは、絶え間なく続く、かじるような空腹だ。成人したトロールは、その苛酷な代謝のために、毎日大きな豚1頭分の食事をとる必要がある。この絶え間ない消費は、トロールが他のジャイアントと一線を画す能力、つまり損傷した組織を難なく再生させる力になる。トロールは、切断された手足を数分でつなぎ直したり、新しい手足を生やしたりすることができる。

通常であればトロールは怪我をしても死ぬことはないため、戦闘では死を恐れず、生命や手足の喪失を恐れずに積極的に攻撃する。彼らはためらうことなく戦闘に身を投じ、最も近くにいる相手に向かって激しく暴れまわる。

トロールは自分が殺される可能性があることをよく知っているが、死の可能性に直面しても、それが本当に自分の身に起こるとはなかなか理解できない。炎に直面しても、炎を避けて攻撃しようとする。

再生が有効である限り、トロールを殺すことは極めて困難であるが、トロールが死ぬのに十分な時間、再生を一時的に阻害する方法や、直接的な物理的ダメージ以外の方法で殺す方法はいくつかある。数日間十分な食事をとらなかったトロールは再生能力を失い弱体化するが、一度でも十分な食事をとれば戦闘態勢に戻る。トロールを溺死させるのも効果的である。しかし、トロールの再生を無効にする最も一般的な方法は火と酸の2つであり、どちらも再生では修復できないほど肉体にダメージを与える恐ろしい傷を作る。意識を失ったトロールの切断部位や死体を燃やすことは、そのクリーチャーを永続的に殺す最良の方法である。
]],
[race_ed_phy]=[[
トロールは直立して歩くが、前かがみになって肩を落とし、常に指関節歩行寸前だ。歩き方は不規則で、疾走するときは腕がぶらぶらと地面を引きずる。一見不格好に見えるが、トロールは非常に機敏である。

典型的な大人のトロールは、身長9フィート、体重500ポンドだが、猫背の姿勢のため背が低く見えることが多い。メスはオスよりわずかに大きい。トロールのゴムのような皮はモスグリーン、緑と灰色の斑点、または腐敗した灰色である。つや消しの毛はたいてい緑がかった黒か鉄のような灰色で、下顎からは大きな牙が突き出し、漆黒の目を持つ。
]],
[race_ed_btl]=[[
トロールは食欲旺盛で再生能力もあるため、恐れを知らぬ戦闘民族であり、最も近くにいる生物に真っ向から突進し、怒りの限りを尽くして攻撃する。トロールが躊躇するのは火（または酸）だけのようだが、この致命的な脅威でさえトロールの前進を止めるには十分ではない。

トロールは死を恐れない： 躊躇することなく戦闘に身を投じ、最も近くにいる相手に向かって激しく暴れまわる。火を前にしても、炎を避けて攻撃しようとする。
]],
[race_ed_soc]=[[
オスのトロールは通常単独で行動するが、メスのトロールはより社交的で、2～4頭のグループと幼獣からなる遊牧グループを形成する。メスのトロールはオスよりかなり大きく、知能も少し高い。

メスのトロールは子供を非常に大切にし、威張り散らすオスのトロールや、脅威となる他の生き物を追い払う。しかし、メスのトロールは若いトロール同士の凶暴な争いには目をつぶり、大人になるために必要なことだと考える。

魔法をマスターした年長のメスのトロールが、一時的に集団に加わってメスの若者を観察し、魔法の適性をテストすることもある。有望な若者が成熟するまで集団にとどまることも多く、彼女の力がそちらに向いていない場合は、最悪の戦いから彼女を守る。十分に成長した幼女がグループを離れると、魔法の訓練を受ける。

メスとは異なり、ほとんどのオスのトロールは一生の大半を単独で過ごす。成熟すると独り立ちするか、大人のメスに逃げられるかのどちらかである。孤独なオスは通常、広い縄張りを見つけて狩場とし、その中心に隠れ家を作り、他のトロールや他のモンスターを追い払う。オスは通常、交尾のためだけに縄張りを離れ、しばしば戦闘で他の求婚者に勝とうとして求婚する。
]],
[race_ed_rel]=[[
トロールは一般的に、獲物を奇襲しやすい森林や岩場の多い荒野に住んでいる。彼らは他の主要な捕食者や知的生物との距離を保とうとする。

トロールフューリーとして知られるトロールのドルイドは、地域全体の健康に気を配り、侵入してくるオーガや人間、その他の外敵による新たな危険に常に最初に気づく。
]],
[race_ed_aln]=[[
トロールは単純な宗教観を持っている。彼らは通常、嵐や自然災害を司るデーモンロードを崇拝している。

信仰の司祭は、酸や火を使って意図的に自分を焼き、切り刻み、恐ろしい醜い傷跡を残す。
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_rock_throw="岩投げ"
s_rock_throw_d=[[大人のジャイアントは岩投げを得意とし、岩を投げる際の攻撃ロールに＋1の種族ボーナスを受ける。

少なくとも大型サイズ以上のジャイアントは、1つ40～50ポンドの重さの岩（小型オブジェクト）を5つの範囲まで投げることができる。範囲増分の大きさはジャイアントの種類によって異なる。巨大ジャイアントは60～80ポンド（中型オブジェクト）の岩を投げることができる。

ヒルジャイアントが投げる岩石の射程は120フィートである。

ストーンジャイアントの投げる石の射程は180フィートである。石を投げるときは両手を使う。]]

s_rock_catch="岩つかみ"
s_rock_catch_d=[[少なくとも大型サイズのジャイアントは、小型、中型、大型サイズの岩（または似たような形状の投石物）をキャッチできる。

ラウンドに1度、通常なら岩攻撃を受けるらうジャイアントが、自由行動として岩を受け止めるための反応セーヴを行なうことができる。セーヴの回数は小岩で15回、中岩で20回、大岩で25回である。投擲物が攻撃ロールに魔法的なボーナスを与えるものであれば、難易度(DC)はその分だけ増加する。

ジャイアントが岩をつかむためには、攻撃に備え、それに気づかなければならない。

ストーンジャイアントは投げられた岩を受け止めようとするとき、反応セーヴに＋4の種族ボーナスを得る。]]


s_giant="ジャイアント"
s_giant_d=[[ジャイアントは近接戦闘を好む。彼らは巨大な両手武器を好み、見事な腕前でそれを使いこなす。

ジャイアントには十分な狡猾さがあり、できることならまず範囲攻撃で敵を弱体化させる。ジャイアントが好む射撃武器は大きな岩だ。

ジャイアントはすべてジャイアント語を話す。知力値が10以上のものは共通語も話す。]]


s_gnt_h="ヒル ジャイアント"
s_gnt_h_c="この猫背のジャイアントは力強さと粗野で愚かな怒りを漂わせ、その不潔な毛皮の服は残忍で僻地の生活様式を物語っている。"
s_gnt_h_fav_cls="驚異的な強さを持ちながら知恵に乏しい無謀な獣であるヒルジャイアントは、バーバリアンクラスに適している。"
s_gnt_h_traits=[[
<b c=tg>筋力+14、耐久力+8、 <c=tr>敏捷力 -2、知力 -4、魅力 -4: </c></b>ヒルジャイアントは驚異的な強さを持つが、非常に粗野で愚かだ。

<b>種族ヒットダイス(HD): </b>ヒルジャイアントは12レベルのジャイアントから始まり、12d8のヒットダイス(HD)を得る。

<b>種族技能: </b>ヒルジャイアントのジャイアントレベルは、15×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は登攀、跳躍、聞き耳、視認である。

<b>種族特技: </b>ヒルジャイアントはジャイアントレベルで5つの特技を持つ。

<b>鎧: </b>外皮ボーナス+9。

<b>武器と防具の熟練度: </b>単純武器、軍用武器（ハンマー、メイス）、軽装鎧、中装鎧、盾に熟練している。

<b>特別な資質: </b><t=@pwr_rock_throw c=fc_b>岩投げ</t>, <t=@pwr_rock_catch c=fc_b>岩つかみ</t>。
]]
s_gnt_h_langs=[[
<b>自動習得言語: </b>ジャイアント語。
<b>ボーナス習得言語: </b>共通語、竜語、エルフ語、ゴブリン語、オーク語。

<c=twc>ヒルジャイアントはジャイアント語を話す。</c>
]]
s_gnt_h_d=[[
ヒルジャイアントは人型生物ジャイアントの中で最も遊牧民的な種族であり、襲撃や略奪のために集落から集落へと移動することを好む。

ジャイアントは信じられないほど利己的なクリーチャーだ。彼らは恐ろしい敵に向かって互いに押し合いへし合いすることで知られており、自分の身を守るためなら一族の仲間を犠牲にすることもためらわない。

孤独で悪でないヒルジャイアントは非常に稀であるが、他の人型生物社会で見かけることもある。これらの "文明化された "ヒルジャイアントは、社会の中で自分の居場所を見つけることができ、その多くは平和で何不自由ない生活を送っている。
]]
s_gnt_h_eds={
[race_ed_dd1]=[[
ヒルジャイアントは人型生物ジャイアントの中で最も遊牧民的な種族であり、襲撃や略奪のために集落から集落へと移動することを好む。

ジャイアントの一団は温帯の丘陵地帯でよく見られ、常に攻撃的であるため、この気候では危険な存在として恐れられている。

彼らは温暖な気候を好むが、襲撃が豊富で成功する限り、好みの環境から遠く離れた場所にも移動する。

彼らは全体として、信じられないほど利己的なクリーチャーであり、自分が勝つと自動的に分かっていない戦いにはめったに参加しない。ジャイアントは恐ろしい敵に向かって互いに押し合うことで知られており、自分の身を守るためなら一族の仲間を犠牲にすることもためらわない。
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
ジャイアントの肌の色は、明るい褐色から深い赤褐色まで幅広い。髪は茶色か黒で、目も同じ色をしている。

ジャイアントは毛皮を残したまま、粗末に用意した皮革を何枚も重ねて着る。彼らはめったに洗濯や修理をせず、古い皮革が擦り切れるたびに皮革を追加していく。

成獣の身長は約10-1.5フィート、体重は約1,100ポンドである。ジャイアントは200歳まで生きることができる。
]],
[race_ed_btl]=[[
ジャイアントは高い岩場から戦うことを好み、岩や岩塊で相手を殴りつつ、自分のリスクも抑えることができる。

ヒルジャイアントは戦闘に参加した当初、小さなクリーチャーに対して蹴散らし攻撃を仕掛けるのが好きだ。その後、彼らは素早く立ち上がり、巨大なクラブで振り払う。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
孤独で悪でないジャイアントは非常に稀だが、他の人型生物社会で見かけることがある。

彼らは辺境の町で労働者や兵士として働くのが最も適しており、しばしばヒルジャイアント集団と交渉する初歩的な外交官としての役割を果たす。

残念なことに、文明のために種族的な生活様式を捨てたジャイアントは、遊牧民の同胞たちから嘲笑され、しばしばその場で殺される。

それでも、"文明化 "されたヒルジャイアントたちは、社会の中で自分たちの居場所を見つけることができ、その多くは平和で何不自由ない生活を送ることができている。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
驚異的な強さを持ちながら機知に乏しい無謀な獣であるヒルジャイアントは、社会に真に受け入れられることはない。しかし、彼らは社会の端や辺境でうまくやり、力強く有益な存在を築いている。

無骨な外見と大きな体格にもかかわらず、基本的に人型生物の体型をしているため、文明的な人々との関わりは容易である。
]],
[race_ed_nam]=[[
]],
}


s_gnt_s="ストーン ジャイアント"
s_gnt_s_c="このジャイアントは、彫りの深い筋肉質の顔立ちをしており、平らで前傾した頭部は、まるで石で彫られたかのようだ。"
s_gnt_s_fav_cls="強く、無口な一匹狼、ストーンジャイアントのキャラクターはバーバリアンクラスに適している。"
s_gnt_s_traits=[[
<b c=tg>筋力+16、敏捷力+4、耐久力+8、判断力+2: </b>ストーンジャイアントは非常に強く頑強だが、柔軟で賢明でもある。

<b>種族ヒットダイス(HD): </b>ストーンジャイアントは14レベルのジャイアントからスタートし、14d8のヒットダイス(HD)を得る。

<b>種族技能: </b>ストーンジャイアントのジャイアントレベルは17×（2＋知力修正値）に等しい技能ポイントを与える。クラス技能は登攀、隠れ身、聞き耳、見破りである。ストーンジャイアントは岩場での隠れ身判定に＋8の種族ボーナスを持つ。

<b>種族特技: </b>ストーンジャイアントのジャイアントレベルは5つの特技を与える。

<b>鎧: </b>外皮ボーナス+11。

<b>武器と防具の熟練度: </b>単純武器、グレートクラブ、軽装鎧、中装鎧、盾に熟練している。

<b>特別な資質: </b><t=@pwr_rock_throw c=fc_b>岩投げ</t>, <t=@pwr_rock_catch c=fc_b>岩つかみ</t>。
]]
s_gnt_s_langs=[[
<b>自動習得言語: </b>ジャイアント語。
<b>ボーナス習得言語: </b>共通語、竜語、エルフ語、ゴブリン語、オーク語。

<c=twc>ストーンジャイアントはジャイアント語を話す。</c>
]]
s_gnt_s_d=[[
強く静かな一匹狼、ストーンジャイアントは人間の土地では特殊な存在だ。ジャイアントは標高の高い岩山の巨大な洞窟に好んで住む。他のジャイアント集団から数日以上離れて暮らすことはほとんどなく、部族間でヤギなどの家畜の群れを共有することもある。

年老いたジャイアントは、晩年になるとかなりの期間部族を離れ、どこかで隠遁生活を送るか、他の人型生物文明に溶け込もうとする傾向がある。このような自らに課した数十年の流浪の後、戻ってきた者はストーンジャイアントの長老となる。

ストーンジャイアントは、周囲の石に合わせて茶色や灰色に染めた分厚い革の衣服を好む。大人は身長約12フィート、体重約1,500ポンド、800歳まで生きることができる。
]]
s_gnt_s_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
ストーンジャイアントは可能な限り距離をとって戦うが、近接戦闘を避けられない場合は、石から削り出したギガンティッククラブを使う。

ストーンジャイアントが好む戦術は、ほとんど動かずに立って背景に溶け込み、それから前進して岩を投げ、敵を驚かせることだ。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_gnt_se="ストーン ジャイアント エルダー"
s_gnt_se_var_n="帰ってきたストーンジャイアント"
s_gnt_se_var_d="ストーンジャイアントエルダーは特殊能力を発達させたため、以下の例外を除いてストーンジャイアントのすべての種族的特徴を持っている。:"
s_gnt_se_fav_cls="ストーンジャイアントエルダーは特殊能力と高い魅力値を持っており、ソーサラークラスに非常に適している。"
s_gnt_se_traits=[[
<b c=tg>筋力+16、敏捷力+4、耐久力+8、判断力+2、魅力+6: </b>普通のストーンジャイアントと比べて、ストーンジャイアントエルダーはより多くのアーケイン的な才能を持っている。

<b>呪文に似た能力: </b>詠唱可<t=@pwr_sp_xxx c=fc_b>岩の造形</t>, <t=@pwr_sp_xxx c=fc_b>岩のお告げ</t>, <t=@pwr_sp_xxx c=fc_b>岩を泥に変えるまたは泥を岩に変える</t>それぞれ1日1回行える。セーヴ難易度(DC)は魅力ベースである。呪文の使い手レベルはキャラクターレベルと等しい。{hr_splk}
]]
s_gnt_se_hr_splk="岩の造形,岩のお告げ,そして、岩を泥に変えるまたは泥を岩に変える、のいずれか。"
s_gnt_se_d=[[
年老いたストーンジャイアントは、晩年になるとかなりの期間部族を離れ、どこかで隠遁生活を送るか、他の人型生物文明に融合しようとする傾向がある。

何十年も自らに課した追放の後、戻ってきた者たちはストーンジャイアントエルダーとなる。

このストーンジャイアントエルダーたちは、環境に関連した特殊能力を身につけ、ソーサラーとしてその能力を使うことができる。
]]


-- 精类		Fey


s_sprite	= "スプライト"
s_sprite_c	= "このしなやかで小柄なクリーチャーは、蛾のような翼と細長い耳を持つ人型生物のようだ。"
s_sprite_d	= [[スプライトは引っ込み思案なフェイだ。彼らは悪や醜悪なものと戦い、故郷を守るためにわざわざ出かけていく。スプライトは森林地帯の奥深くに集団で集まり、自然を守るという大義に賛同する。スプライトの部族全体が、その土地で重要な特定の人物や場所、クリーチャーを守護する存在であると自認している。

スプライトの体は自然に発光するが、その色や強さは自由に変えることができる。死後間もなく、スプライトの身体は単に溶けて煌めく水蒸気となる。スプライトはフェイの中でも最も小さく、身長は9インチ強、体重は1、2ポンドを超えることはほとんどない。

スプライトは呪文のような能力と小柄な武器で敵と戦う。直接対決よりも待ち伏せなどの策略を好む。]]

s_sprite_e	= [[スプライトは他のフェイよりも多くの点で原始的である。お互いに楽しく付き合うが、他のフェイに対して不信感を抱く傾向があり、人型生物や他のクリーチャーで、自分たちが明確に守ることを選んでいないものは、自分たちに悪意があると考える。動物でさえも一般的に危険視される。これはスプライトが小柄なためで、捕食者に狙われやすい。その結果、危険に対するスプライトの最初の反応は一般的に逃げることである。追っ手を遅らせたり気をそらすために呪文のような能力を使い、最終的に逃げおおせるのは飛行速度とその大きさに頼っている。

スプライト自身は比較的無教養で野蛮な性質だが、自然界のあらゆる不思議なものに対する健全な好奇心を持っている。特に古代寺院の遺跡のような、偉大だが潜在的な魔力を秘めた場所に惹かれる。この好奇心の強さから、使い魔としての役割にも異常に寛容である。5レベルの混沌にして中立の呪文の使い手で、使い魔能力向上の特技を持つ者は、スプライトを使い魔として得ることができる。]]


s_nymph		= "ニンフ"
s_nymph_c	= "長い耳が頭の上で先細りになり、その完璧な美しさが痛々しい。"
s_nymph_d	= [[ニンフは自然の美を体現しているだけでなく、野生の秘密の世界の守護者でもある。彼らは抗いがたい美しさを持っており、何気なく見ただけで、見る者をたちまち盲目にしてしまうほどだ。

ニンフの身長と体重は女性エルフほどだ。ニンフは森語と共通語を話す。

多くの者がニンフの美しさを求めて無益な死を遂げ、さらに多くの者が、ニンフとの交わりの準備ができていない心と体に、その優美さがもたらす狂気と執着によって命を落としてきた。

しかし、そのニンフ自体は残忍な存在ではありません。自然の最も清らかな場所や美しい領域の守護者として、彼女や彼女の住処を尊重する者たちに親切に接し、気に入った者には魔法の贈り物を授けることさえあります。

しかし、彼女や彼女の家を虐待したり傷つけようとする者たちは、美しさの裏には、領分を守ることのできる獰猛な保護者がいることにすぐに気づく。]]


s_pipes="パイプ"
s_pipes_d=[[サテュロスはパンパイプで様々な不思議な曲を演奏することができる。

それが演奏されると、60フィート以内のクリーチャー（サテュロスを除く）は難易度(DC)13の意志セーヴに成功するか、魅了、睡眠、恐怖の効果を受けなければならない（呪文の使い手レベル10；サテュロスが曲とその効果を選ぶ）。

セーヴ難易度(DC)は魅力ベースである。パイプの効果に対するセーヴに成功したクリーチャーは、24時間、同じパイプの影響を受けることができない。

通常、パイプを持っているサテュロスはグループの中で1人だけだ。他の者の手に渡ったパイプには特別な力はない。]]

s_satyr="サテュロス"
s_satyr_c="このハンサムでニヤリと笑う男は、ヤギのような毛むくじゃらの足と、こめかみから伸びるカールした雄羊の角を持っている。"
s_satyr_fav_cls="サテュロスは音楽を愛し、音楽の才能がある。サテュロスはその名を冠したパイプの助けを借りて、他人を魅了するための様々なメロディーの呪文を紡ぎ出すことができる。"
s_satyr_traits=[[
<b c=tg>敏捷力+2、耐久力+2、知力+2、判断力+2、魅力+2: </b>サテュロスはあまり強くないが、生まれつき優美で機敏、感覚も鋭く、あらゆる面で優れた能力を発揮する。

<b>種族ヒットダイス(HD): </b>サテュロスは5レベルのフェイから始まり、5d8のヒットダイス(HD)を得る。

<b>種族技能: </b>サテュロスのフェイレベルは8×（2＋知力修正値）に等しい技能ポイントを与える。サテュロスのクラス技能ははったり、隠れ身、知識（自然）、聞き耳、忍び足、芸能、視認である。サテュロスは隠れ身、聞き耳、忍び足、芸能、視認の判定に＋4の種族ボーナスを持つ。

<b>種族特技: </b>サテュロスのフェイレベルは2つの特技を与える。サテュロスはボーナス特技として覚醒を得る。

<b>鎧: </b>外皮ボーナス+4。

<b>肉体武器: </b>頭突き（1d6）。{hlp_nwpn}

<b>武器の熟練度: </b>単純武器とショートボウに熟練している。

<b>特別な資質: </b><t=@pwr_satyr c=fc_b>パイプ</t>, <t=@pwr_satyr c=fc_b>ダメージ減少5/冷たい鉄</t>。
]]
s_satyr_langs=[[
<b>自動習得言語: </b>森語。
<b>ボーナス習得言語: </b>共通語、エルフ語、ノーム語。

<c=twc>サテュロスは森語を話し、ほとんどの者は共通語も話す。</c>
]]
s_satyr_m=[[
サテュロスは、ファウヌスとして知られる地域もあるが、森の最も深く、最も原始的な場所に住む、快楽的で淫乱なクリーチャーである。彼らはワイン、音楽、肉欲の歓びを好み、無防備な乙女や羊飼いの少年を口説く低級悪魔や口上手として有名である。

サテュロスはしばしば森のクリーチャーたちの守護者としての役割を果たす。サテュロスはその名を冠したパイプの助けを借りて、他者を魅了するための様々なメロディーの呪文を紡ぎ出すことができる。

サテュロスの髪は赤か栗色で、蹄と角は漆黒である。サテュロスの身長と体重はハーフエルフと同じくらいである。

サテュロスは森語を話し、ほとんどの者は共通語も話す。
]]
s_satyr_d=[[
サテュロスは、ファウヌスとして知られる地域もあるが、森の最も深く、最も原始的な場所に住む、淫乱で快楽主義的なクリーチャーである。彼らはワイン、音楽、肉欲の歓びを好み、無防備な乙女や羊飼いの少年を口説く熊手や口上手として有名である。

サテュロスの肉体は魅力的で体格の良い男性のものであることがほとんどだが、サテュロスの誘惑の才能の多くは音楽の才能にある。サテュロスは、その名を冠したパイプの助けを借りて、他人を魅了するための様々なメロディーの呪文を紡ぎ出すことができる。

サテュロスは常に遊びまわるだけでなく、しばしば森のクリーチャーたちの保護者としての役割も果たす。
]]
s_satyr_eds={
[race_ed_dd1]=[[
サテュロスは半人半獣のクリーチャーで、深い森の奥深くに生息しています。彼らは酒、音楽、そして肉欲的な喜びを崇拝し、狡猾で言葉巧みな人物として知られています。無垢な乙女や羊飼いの少年たちを口説き落とし、予期せぬ妊娠や説明のつけづらい事態を残して去ることもあります。

そのような出会いから生まれた子供は常に純血のサテュロスであり、生まれて間もなく騒がしい仲間に連れ去られることが一般的です。サテュロスは他人の権利よりも自分の娯楽を重視する傾向がありますが、彼らが誘惑する相手には悪意を持ちません。

サテュロスの肉体は魅力的で体格の良い男性のものであることがほとんどだが、サテュロスの誘惑の才能の多くは音楽の才能にある。サテュロスは、その名を冠したパイプの助けを借りて、他人を魅了し、自分の気まぐれな欲望に沿わせるように設計された、多種多様な旋律の呪文を紡ぎ出すことができる。

サテュロスは絶え間ないふざけ騒ぎの他に、森の住人たちの守護者としても活動します。そして、サテュロスの情欲を怒りに変えることに成功した者は、おそらくフォーンを取り囲む危険な動物たちと直面することになるでしょう。
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
サテュロスの身体は魅力的で体格の良い男性のものであることがほとんどで、髪は赤か栗色、蹄と角は漆黒である。

サテュロスの身長と体重はハーフエルフと同じくらいだ。
]],
[race_ed_btl]=[[
サテュロスの鋭敏な感覚のおかげで、野生の環境下でそれらを驚かせることはほとんど不可能だ。逆にサテュロス自身の天性の優雅さと俊敏さから、周囲の荒野に気をつけていない旅人に気づかれずに忍び寄ることができる。

戦闘になると、素手のサテュロスは強力な頭突きで攻撃する。トラブルを予期しているサテュロスはボウとダガーで武装している可能性が高く、通常は隠れているところから矢を放ち、敵を弱らせてから接近する。 
]],
