-- 人形怪物	Monstrous Humanoid


s_powerful_charge		="強力な突撃"
s_powerful_charge_d		=[[ミノタウロスは通常、相手に向かって突進し、頭を下げて強大な角を生やすことで戦闘を開始する。

各戦闘の最初の突撃に2倍の突き刺しダメージが追加される。]]

s_natural_cunning		="天性の狡猾さ"
s_natural_cunning_d		=[[ミノタウロスは特別知能が高いわけではないが、生来の狡猾さと論理的能力を持っている。

これにより、メイズの呪文に対する免疫ができ、迷子になることがなくなり、敵を追跡できるようになる。

さらに、彼らは決して立ちすくみを受けることはない。]]

s_minotaur="ミノタウロス"
s_minotaur_c="力強い体格の人間の体と、唸り声を上げる雄牛の頭を持つこのクリーチャーは、突撃の準備をするかのように蹄を踏み鳴らす。"
s_minotaur_fav_cls=""
s_minotaur_traits=[[
<b c=tg>筋力 +8、耐久力 +4、 <c=tr>知力 -4、魅力 -2: </c></b>ミノタウロスは非常に強く丈夫だが、呪いから生まれ、歪んだ心を持ち、非常に執念深い。

<b>種族ヒットダイス(HD): </b>ミノタウロスはまず6レベルのモンスター人型生物になり、6d8のヒットダイス(HD)を得る。

<b>種族技能: </b>ミノタウロスのモンスター人型生物レベルは9×（2＋ 知力修正値）に等しい技能ポイントを与える。ミノタウロスのクラス技能は、威嚇、跳躍、聞き耳、捜索、見破りである。ミノタウロスは捜索、見破り、聞き耳の判定に＋4の種族ボーナスを持つ。

<b>種族特技: </b>ミノタウロスのモンスター人型生物レベルは3つの特技を与える。

<b>鎧: </b>外皮ボーナス+5。

<b>肉体武器: </b>突き刺し（1d8）。{hlp_nwpn}

<b>武器の熟練度: </b>グレートアックスと単純武器全般に熟練している。

<b>特別な資質: </b><t=@pwr_powerful_charge c=fc_b>強力な突撃</t>, <t=@pwr_natural_cunning c=fc_b>天性の狡猾さ</t>, <t=@pwr_scent c=fc_b>嗅覚</t>。
]]
s_minotaur_langs=[[
<b>自動習得言語: </b>共通語とジャイアント語。
<b>ボーナス習得言語: </b>オーク語、ゴブリン語、地界語。

<c=twc>ミノタウロスはジャイアント語を話す。</c>
]]
s_minotaur_d=[[
ミノタウロスは、力強い体格の人間の体と雄牛の頭を持ち、身長は7フィート以上、体重は約700ポンドもある。

ミノタウロスほど恨みを抱くものはいない。多くの文化には、最初のミノタウロスは復讐に燃えた、あるいは軽んじられた神々によって創造されたという伝説がある。神々は人間の姿をねじ曲げ、知性と美を奪い、雄牛の頭を与えて罰したのだ。

しかし、現代のミノタウロスのほとんどはこれらの伝説を軽蔑し、自分たちは神の嘲笑ではなく、バフォメットという強力で残酷なデーモンロードが作り出した神の矛だと信じている。
]]
s_minotaur_eds={
[race_ed_dd1]=[[
ミノタウロスほど恨みを抱くものはいない。何世紀も前に文明種族から軽蔑され、神の呪いによって生まれたミノタウロスは、物心ついたときから、現実の、あるいは想像上の侮辱に対する報復として、劣った人型生物を狩り、殺し、貪り食ってきた。

多くの文化には、最初のミノタウロスは復讐に燃えた、あるいは軽んじられた神々によって創造されたという伝説がある。神々は人間の姿をねじ曲げ、知性と美を奪い、雄牛の頭を与えることで人間を罰したのだ。しかし、現代のミノタウロスのほとんどはこれらの伝説を軽蔑し、自分たちは神の嘲笑ではなく、バフォメットという強力で残酷なデーモンロードが作り出した神の矛だと信じている。
]],
[race_ed_dd2]=[[
伝統的なミノタウロスの隠れ家は迷路であり、それは困惑させ混乱させるために作られた本物の迷宮であれ、都市の下水道のような偶発的な迷路であれ、洞窟やその他の地下通路のもつれのような自然発生的な迷路であれ、である。

ミノタウロスは生来の狡猾さを生かし、迷路の隠れ家を利用して、迷い込んだ敵や、迷い込んだ敵を苦しめる。絶望が本当に訪れた時、ミノタウロスは迷い込んだ犠牲者を襲うために動き出す。

群れを相手にする場合、ミノタウロスはしばしばクリーチャーを一匹逃がし、恐怖の物語を広め、他のクリーチャーを迷路に誘い込み、クリーチャー退治を期待する。もちろん、ミノタウロスにとっては、英雄になろうとする者たちはおいしい食事になる。
]],
[race_ed_dd3]=[[
ミノタウロスはまた、より強力なモンスターや悪クリーチャーに雇われ、狩りと食事が好きなようにできる限り、そのモンスターに仕えることもある。

通常、これは何か強力な物や貴重な場所を守ることを意味するが、主人の敵を狩る傭兵のような仕事もある。
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
ミノタウロスは近接戦闘を好み、その大きな力が大いに役立つ。

ミノタウロスは比較的素直な戦闘タイプで、戦闘が始まると角を使って最も近くにいる生物を恐ろしく抉り出す。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_centaur_charge		="ケンタウロスの突撃"
s_centaur_charge_d		="リーチのある武器を装備したケンタウロスは、馬に乗った騎手と同じように、突撃時に2倍のダメージを与える。"

s_centaur="ケンタウロス"
s_centaur_c="このクリーチャーは、上半身は日焼けした熟練の戦士のようであり、下半身はなめらかな軍馬のようである。"
s_centaur_fav_cls="ケンタウロスは広大な平原やエルドリッチの森の縁を歩き回る部族で暮らしている。彼らは伝説的なハンターであり、熟練した戦士である。"
s_centaur_traits=[[
<b c=tg>筋力+8、敏捷力+4、耐久力+4、判断力+2、<c=tr>知力-2: </c></b>ケンタウロスは強くたくましく、柔軟で警戒心が強いが、通常は頭が鈍く野蛮である。

<b>種族ヒットダイス(HD): </b>ケンタウロスはまず4レベルのモンスター人型生物になり、4d8のヒットダイス(HD)を得る。

<b>種族技能: </b>ケンタウロスのモンスター人型生物レベルは7×（2＋知力修正値）に等しい技能ポイントを与える。そのクラス技能は聞き耳、忍び足、視認、生存である。

<b>種族特技: </b>ケンタウロスのモンスター人型生物レベルは2つの特技を与える。

<b>鎧: </b>外皮ボーナス+3。

<b>武器と防具の熟練度: </b>単純武器と軍用武器（ヘヴィブレード、ボウ）に熟練している。

<b>特別な資質: </b><t=@pwr_centaur_charge c=fc_b>ケンタウロスの突撃</t>。
]]
s_centaur_langs=[[
<b>自動習得言語: </b>森語とエルフ語。
<b>ボーナス習得言語: </b>共通語、ノーム語、ハーフリング語。

<c=twc>ケンタウロスは一般的に森語とエルフ語を話すが、比較的知能の高い者は共通語も話す。</c>
]]
s_centaur_d=[[
伝説のハンターであり、熟練したウォリアーであるケンタウロスは、人と馬の両方の特徴を持っている。

ケンタウロスは古い種族であり、現代世界を徐々に受け入れつつある。しかしまれに、進歩的な指導者のもとで部族全体が他の人型生物社会と交易したり同盟を結んだりすることもある。

ケンタウロスの大半はいまだに広大な平原やエルドリッチの森の縁を歩き回る部族で暮らしているが、その多くは祖先の孤立主義的な生き方を捨て、より国際的な都市を歩いている。
]]
s_centaur_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
ケンタウロスは人と馬の中間だ。大きさは重馬と同じくらいだが、背が高く、体重が少し重い。

一般的に文明の片隅で見られるこのストイックな人々の外見は様々で、肌の色は一般的に深く日焼けしているように見えるが、近隣の地域に住む人間に似ており、下半身は地元の馬の色彩を借りている。

ケンタウロスの髪と目は暗い色に傾き、体つきは大柄になる傾向がある一方、体全体の大きさは下半身が馬に似ていることに影響される。したがって、ケンタウロスの平均的な身長は7フィート以上、体重は2,000ポンド以上だが、痩せた平原を疾走する馬からたくましい山のハンターまで、地域によって大きな違いがある。

ケンタウロスは通常60歳くらいまで生きる。ケンタウロスは森語とエルフ語を話す。
]],
[race_ed_btl]=[[
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
ケンタウロスは他の種族とは距離を置き、自分たちの種族とも対立する古い種族だが、徐々に現代世界を受け入れつつある。

しかしまれに、進歩的な指導者のもとで部族全体が他の人型生物の共同体と交易したり同盟を結んだりすることもある-通常はエルフだが、時にはノーム、まれにヒューマンや ドワーフとも。

多くの種族がケンタウロスを警戒しているのは、領土を持つライカンスロープの伝説や、ケンタウロスが頑固な入植者や拡張主義の国と定期的に激しく遭遇していることが主な原因である。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
ケンタウロスの大半はいまだに広大な平原やエルドリッチの森の縁を歩き回る部族で暮らしているが、その多くは祖先の孤立主義的な生き方を捨て、より国際的な都市を歩いている。

このような自由奔放なケンタウロスはしばしばのけ者にされ、部族からも疎まれる。
]],
[race_ed_nam]=[[
]],
}


s_medusa	= "メデューサ"
s_medusa_c	= "このスレンダーで魅力的な女性は、不思議な光を放つ目を持ち、頭髪には蛇が生えている。"
s_medusa_d	= [[メデューサは髪の毛の代わりに蛇を持つヒューマンに似たクリーチャーである。30フィート以上の距離であれば、メデューサは蛇のような髪を隠すものを身に着けていれば、容易に美しい女性と見間違う。頭や顔を隠す服を着ている場合は、さらに近い距離でヒューマンと見間違う。

典型的なメデューサの身長は5～6フィートで、体重は人間と同じくらいである。メデューサは共通語を話す。

メデューサは、その石化する視線の範囲内に対象が入るまで、その本性を偽ろうとし、策略やはったりを駆使して対象に危険がないように思わせる。メデューサは、視線をそらした相手や視線に耐えた相手には通常の武器で攻撃し、隣接する相手には毒蛇で攻撃する。]]--A medusa is indistinguishable from a normal human at distances greater than 30 feet (or closer, if its face is concealed). The creature often wears garments that enhance its body while hiding its face behind a hood or veil.

s_medusa_e	= [[メデューサは石化する視線を使うために、顔を隠す嘘や変装を使って相手に近づくが、獲物をもてあそぶのが好きで、遠くから矢を放って敵を罠にはめることもある。

犠牲者を石化させて複雑な装飾を施し、沼地の隠れ家のアクセントにする者もいるが、たいていのメデューサは、新たな敵にその存在を事前に知られないよう、以前の争いの痕跡を隠すことに注意を払っている。

都市にいるメデューサはたいていローグであり、荒野にいるメデューサはしばしばレンジャーや 追跡者になりすます。しかし、最も悪名高く伝説的なメデューサは、バードやクレリックとしてレベルを上げた者たちである。

魅力と知力が高い都会のメデューサは、シーフギルドやその他の犯罪的な裏社会に関わっていることが多い。メデューサは盲目のクリーチャーや知能の高いアンデッドと同盟を結ぶことがあるが、どちらもその石のような視線には免疫がある。

呪文を唱えるメデューサはしばしば神託や予言の役割を果たし、たいていは伝説的な力や悪名高い歴史を持つ人里離れた場所に住んでいる。そのような予言者のメデューサはその役割を大いに喜び、適切な贈り物とお世辞を贈られれば、彼らが提供する極意はかなり役に立つことがある。

もちろん、このような強力なクリーチャーの隠れ家には、彼らを怒らせた人たちの像がたくさん飾られている。

すべての知られているメデューサはメスです。まれに、メデューサは男性の人型生物を配偶者として保持することを決めるかもしれませんが、通常は愛の霊薬などの魔法の助けを借りて行われ、常に彼女の囚人を石化させないように注意します－少なくとも彼女が彼の付き合いに飽きるまで。]]


s_harpy		= "ハーピー"
s_harpy_c	= "ぼろぼろの翼と爪のある足を除けば、このクリーチャーは野性的な風貌の女性に似ている。"
s_harpy_d	= [[ぼろぼろの翼と爪のある足を除けば、ハーピーは野性的な風貌の女性に似ている。

ハーピーは魔法の歌で不運な旅人に取り込み、言いようのない苦しみに導くのが好きだ。ハーピーは新しい "おもちゃ "で遊び終わった時だけ、彼らを殺して食べることで苦しみから解放する。

ハーピーは犠牲者から盗んだ装飾品や装身具を身につける傾向がある。間近で見ると、このクリーチャーは食べ尽くされた犠牲者の悪臭を放ち、まだ虜になっていないクリーチャーを近づけさせることはめったにない。このため、多くのハーピーは香水や香油を身に着けている。

ハーピーの姿は土地によって千差万別だ。ハゲワシと女性が合体したようなものもいれば、タカやハヤブサの威厳ある模様を羽毛に持つものもいる。世界の孤立した熱帯地域では、オウムのようなカラフルな羽を持つハーピーも稀に見られる。]]

s_harpy_e	= [[しばしば凶暴で堕落したクリーチャーとみなされるが、ハーピーはクリーチャーがどう考え、どう行動するかを知っている。この理解は、好物を見つける際に有利に働く。

野生のクリーチャーはその魅惑的な歌の犠牲になりやすいが、この下劣な鳥女たちは、複雑な感覚をスパイスにした食事を好む。安易な獲物は退屈な食事になる。

最終的には野蛮で、自分たちの行動を反省することもないが、多くのハーピーは人型生物社会の近くに住み、食事になりそうなクリーチャーとの交渉を楽しんでいる。


<b>ハーピーの射手</b>
残酷なハンターであり放浪の山賊であるハーピーの射手は、射撃戦に特化したファイターとして訓練を積んできた。ハーピーの射手はしばしば傭兵となり、最も高値で落札された者と契約する。雇われていないときは、路上強盗団として、商人のキャラバンに保護費を支払わせることで生計を立てている。]]


s_hag		= "ハグ"
s_hag_d		= [[ハグはそれぞれ外見や作法が異なるが、多くの点で共通している。いずれも、その獰猛なパワーと素早さとは裏腹に、屈曲した姿をしている。

ハグはとてつもなく強い。生まれつき呪文に耐性があり、自ら魔法をかけることができる。ハグたちはしばしば集まって群れを作る。通常、各タイプのハグが1匹ずついるハグ団は、個々のメンバー以上の力を使うことができる。

ハグはジャイアント語と共通語を話す。]]


-- 异界生物	Outsider


s_celestial_creature	= "セレスチャル クリーチャー"
s_celestial_creature_d	= [[セレスチャルクリーチャーは善の領域である上層界に住むが、物質界にいる存在に似ている。彼らは地上の存在よりも威厳があり、より美しい。

セレスチャルクリーチャーはしばしばメタリックカラー（通常は銀、金、プラチナ）をまとっている。彼らはハーフセレスチャルと間違われることがあるが、これはセレスチャルが非セレスチャルクリーチャーと交配することで生まれる、より強力なクリーチャーである。]]


s_fiendish_creature		= "フィーンディッシュ クリーチャー"
s_fiendish_creature_d	= [[フィーンディッシュクリーチャーは低次元、つまり悪の領域に棲むが、物質界にいる存在に似ている。彼らは地上の存在よりも恐ろしい外見をしている。]]


s_half_celestial	= "ハーフ セレスチャル"
s_half_celestial_d	= [[どのような形であれ、ハーフセレスチャルは金色の肌、輝く目、天使のような翼、あるいは高次の性質を示す何らかのサインを持ち、常に美しく、感覚を楽しませる。]]


s_half_fiend	= "ハーフ フィーンド"
s_half_fiend_d	= [[どのような形であれ、半魚人は常に見るもおぞましく、黒い鱗、角、赤く光る目、バットの羽、腐臭、あるいは悪に染まっていることを示す何らかの明らかな兆候を持っている。]]


s_angel		= "エンジェル"
s_angel_d	= [[エンジェルは天界の種族、すなわち善良な来訪者であり、善属性の超自然的な次元に生息している。

エンジェルはどのような善属性であってもよい。属性に関係なく、エンジェルは決して嘘をついたり、ごまかしたり、盗んだりしない。彼らはすべての取引において非の打ちどころのない高潔さを持ち、しばしば天界の中で最も信頼でき、外交的であることを証明する。

エンジェルは皆、美しい容姿に恵まれているが、実際の外見は千差万別だ。

エンジェルは天上語(セレスチャル)、地獄語(インファーナル)、竜語を話すが、タングズ 能力があるため、ほとんどのクリーチャーと話すことができる。]]


s_archon	= "アーコン"
s_archon_d	= [[アーコンはセレスチャルの種族、すなわち善の来訪者であり、秩序善の属性で超自然的な次元に生息する。

アーコンは天上語(セレスチャル)、地獄語(インファーナル)、竜語を話すが、そのタングズ能力によりほとんどのクリーチャーと話すことができる。]]


s_demon		= "デーモン"
s_demon_d	= [[デーモンは混沌にして悪に満ちた平原に生息するクリーチャーの種族である。彼らは獰猛を擬人化したような存在であり、どんなクリーチャーであろうと、たとえ他のデーモンであろうと、ただそれを楽しむためだけに攻撃する。

デーモンは奈落語(アビサル)、天上語(セレスチャル)、竜語を話す。]]


s_devil		= "デビル"
s_devil_d	= [[デビルは秩序にして悪属性に属したした次元の悪魔である。

多くのデビルは恐怖のオーラに包まれており、それを使って強力な集団を分断し、相手を別々に倒す。

呪文のような能力を持つデビルは、そのイリュージョン能力を使って敵をできるだけ欺き、混乱させる。お気に入りのトリックは、幻影の援軍を作り出すことである。敵は、脅威がただの作り物なのか、それとも本当に招来されたデビルが戦いに加わっているのか、完全に確信することはできない。

デビルは地獄語(インファーナル)、天上語(セレスチャル)、竜語を話す。]]


s_planetouched		= "プラネット タッチ"
s_planetouched_d	= [[プラネットタッチとは、自分の血統を来訪者（通常は悪魔や天界人）に遡ることができる人物を表す一般的な言葉である。

超自然的な存在を受け継ぐことの影響は、何世代にもわたって続く。半神や半妖ほど劇的に変化するわけではないが、プラネットタッチにはいくつかの特別な性質が残っている。

エイシマーとティーフリングは最も一般的なプラネットタッチの種族です。エイシマーは、天界の血を引く人間であり、ティーフリングは家系に悪魔の血が流れている人間です。]]


s_aasimar		= "アーシマール"
s_aasimar_c		= "この超絶的な美女は、見た目はヒューマンだが、不思議な落ち着きと慈悲深さを発している。"
s_aasimar_d		= [[アーシマールは通常、背が高く、容姿端麗で、概して快活である。銀色の髪、金色の目、不自然に強い視線など、その血統を示唆する身体的特徴を持つ者もいる。

ほとんどのアーシマールは善に忠実である。悪と闘い、他者を正しい方向に導こうとする。時折、セレスチャルのように復讐心に燃え、裁きを下すこともあるが、それはまれである。]]
s_aasimar_fav_cls="アーシマールは通常、正々堂々とした戦いを好む。しかし、特に邪悪な敵に対しては、死力を尽くして戦う。"
s_aasimar_traits=[[
<b c=tg>判断力+2、魅力+2: </b>アーシマールは洞察力に富み、自信にあふれ、人柄もいい。

<b>技能: </b>視認判定と聞き耳判定に＋2の種族ボーナス。]]
.."\n\n"..xs_lbl("s_res_ace_5")
.."\n\n".."<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_lt_3 c=fc_b>日中</t>1日1回使用する。呪文の使い手レベルはキャラクターレベルに等しい。"
s_aasimar_langs=[[
<b>自動習得言語: </b>共通語と天上語(セレスチャル)。
<b>ボーナス習得言語: </b>竜語、ドワーフ語、エルフ語、ノーム語、ハーフリング語、森語。

<c=twc>アーシマールは共通語と天上語(セレスチャル)を話す。</c>
]]
s_aasimar_eds={
[race_ed_dd1]=[[
アーシマールとは、先祖にセレスチャルやその他の善の来訪者の血をかなり受け継いでいるヒューマンのことである。常に善というわけではないが、アーシマールは悪よりもむしろ親切な行為に傾倒し、天界に関連する信仰や組織に傾倒する。

アーシマールの血統は何世代にもわたって眠っていることがあり、一見ヒューマンに見える両親の間に生まれた子供に突然現れることがある。ほとんどの社会では、アーシマールの誕生は吉兆と解釈されているが、一部のアーシマールはその評判を利用し、恐ろしい残虐行為や卑劣な行為で他人の期待を残酷に裏切る。"疑わしきは罰せず "とは、こうした邪悪なアーシマールの信条であり、彼らはしばしば高潔な市民や偽りの英雄として二重生活を送り、その腐敗をうまく隠している。ありがたいことに、こうした少数派は例外である。
]],
[race_ed_dd2]=[[
アーシマールとは、先祖にかなりの量のセレスチャルやその他の善な来訪者の血を引くヒューマンのことである。アーシマールは常に善というわけではないが、それは彼らにとって自然な傾向であり、善の信仰やセレスチャルに関連する組織に引き寄せられる。

アーシマールの血筋は何世代にもわたって隠れていることもあるが、一見ヒューマンに見える両親の間に生まれた子供に突然現れることもある。ほとんどの社会では、アーシマールの誕生は吉兆と解釈されている。

アーシマールの外見は、その特異な血統を示す些細な身体的特徴を除けば、ほとんどヒューマンである。典型的なアーシマールの特徴は、金属のように輝く髪、特殊な目や肌の色、あるいは金色の光輪である。
]],
[race_ed_phy]=[[
アーシマールは、その特異な血統を示す些細な身体的特徴を除けば、ほとんどヒューマンに見える。

典型的なアーシマールの特徴として、金属のように輝く髪、宝石をちりばめたような瞳、艶やかな肌色、あるいは金色に輝く後光などが挙げられる。
]],
[race_ed_btl]=s_aasimar_fav_cls,
[race_ed_soc]=[[
アーシマールは真の意味で独自の社会を持っているとは言えない。人類の分派として、彼らは周囲の社会規範を取り入れるが、ほとんどの者は不正の是正や苦しみの救済に取り組む社会の要素に惹かれることに気づく。

そのため、暴君的な社会では法の裏をかくこともあるが、アーシマールは必要なときには慎重かつ狡猾になり、抑圧者の注意を他にそらすような偽装をすることができる。

堕落したアーシマールは一匹狼であったり、犯罪に関与していることを隠すために秘密結社を作ったりするが、正義のアーシマールは多くの場合、善良な組織、特に教会や修道会に属している。
]],
[race_ed_rel]=[[
アーシマールは人間社会で最も一般的であり、最も快適です。特に、その血統がより遠く、天界の祖先の跡がほとんど見られない者に当てはまります。

なぜ人類が他の種族よりもセレスチャルを強く感じるのかは不明だが、人類固有の適応能力と変化への親和性が、アーシマールを別個の種族として進化させたのかもしれない。おそらく、他の種族が持つ固有の人種的特質は、あまりに深く育まれ、あまりに強く存在し、変化に対してあまりに抵抗があるのだろう。他の種族が高次元の住人とどのような交際をしたにせよ、そのようなカップリングの子孫は極めてまれで、真の意味で繁殖したことはない。

しかし、一般的にヒューマンの社会を好む傾向があるとはいえ、アーシマールは事実上どんな環境にも馴染むことができる。彼らは社交的で気品があり、人当たりが良い。ハーフエルフとはうまくやっていけるが、ハーフオークはアーシマールのきれいすぎる言葉や顔に我慢がならない。エルフの廷臣たちはアーシマールを素直でないと見なし、失態を克服するために生まれつきの魅力に頼っていると批判することもある。おそらく既知の種族の中で、ノームはアーシマールを最も魅力的に感じ、その多様な外見と天空の遺産にまつわる神秘性を強く評価している。
]],
[race_ed_aln]=[[
アーシマールは善であることが多いが、これは必ずしも万能ではなく、正義に背を向けたアーシマールは底知れぬ堕落の淵に落ちることもある。

しかしほとんどの場合、アーシマールは名誉、武勇、守護、治癒、避難の神々や、家庭、共同体、家族といったシンプルで平凡な信仰を好む。また、芸術、音楽、伝承の道を歩み、美と学問の中に真実と知恵を見出す者もいる。
]],
[race_ed_adv]=[[
アーシマールは人間社会に馴染めず、何か大きな運命に引き寄せられるように冒険家になることが多い。

クレリックとパラディンが最も多いが、バードやソーサラーもアーケイン魔法を好む者には珍しくない。アーシマールのバーバリアンは稀であるが、そのような部族に生まれた場合、しばしば指導的立場に上り詰め、一族に天空のトーテムを受け入れるよう奨励する。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アリティアン,ベルティン,セルナン,クロンウィアー,エラン,イラミン,モードリル,オクリン,パラント,トゥラル,ウィラン,ザイガン。

<c=twa>女性名:</c>
アーケン,アルシノエ,ダヴィーナ,ドリンマ,イメサ,マソジ,ニジェーナ,ニラムール,オンドレア,リアラ,ヴァルティラ。
]],
}


s_tiefling		= "ティーフリング"
s_tiefling_c	= "この小柄な男は剣を抜くと不敵に笑う。小さな角と有刺鉄線の尻尾が、彼がヒューマン以上の何かであることを明らかにしている。"
s_tiefling_d	= [[多様性に富み、しばしば人型生物社会から軽蔑されるティーフリングは、悪魔の血に染まったヒューマンである。

他の種族が彼らを信用することはほとんどなく、この共感性の欠如がティーフリングの堕落した血に滲む邪悪さ、堕落、憤怒を抱かせる原因となっている。

そのような暗い欲望を押し殺すための闘いを、壮大なヒロイズムへの動機づけとみなす少数派もいる。]]
s_tiefling_fav_cls="ティーフリングは卑劣で繊細、そして概して策略家である。待ち伏せして攻撃することを好み、できることなら正々堂々と戦うことを避ける。"
s_tiefling_traits=[[
<b c=tg>敏捷力+2、知力+2、 <c=tr>魅力-2: </c></b>ティーフリングは身も心も素早いが、本質的に変わり者だ。

<b>技能: </b>はったりと隠れ身の判定に＋2の種族ボーナスを得る。]]
.."\n\n"..xs_lbl("s_res_cef_5")
.."\n\n".."<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_dk_2 c=fc_b>ダークネス</t>1日1回使用する。呪文の使い手レベルはキャラクターレベルに等しい。"
s_tiefling_langs=[[
<b>自動習得言語: </b>共通語と地獄語(インファーナル)。
<b>ボーナス習得言語: </b>竜語、ドワーフ語、エルフ語、ノーム語、ゴブリン語、ハーフリング語、オーク語。

<c=twc>ティーフリングは共通語と地獄語(インファーナル)を話す。</c>
]]
s_tiefling_eds={
[race_ed_dd1]=[[
ヒューマン以上でもありヒューマン未満でもあるティーフリングは、ヒューマンとフィーンドとの間の子どもである。異世界の血を引き、それに見合った特徴を持つティーフリングは、反動的な恐怖から敬遠され、軽蔑されることが多い。

ほとんどのティーフリングは、その呪いを生み出すカップリングが何世代も前に起こったため、自分の悪魔のような親を知ることはない。その穢れは長く持続し、しばしば出生時に、あるいは時に人生の後半に、望まぬとはいえ強力な恩恵として現れる。

ティーフリングは悪魔的な外見と冥界の起源を持っていますが、ヒューマンと同じく運命を選択する能力があります。多くの者が自らの暗黒の遺産を受け入れ、悪魔の力に味方する一方で、他の者は自らの暗い嗜好を拒絶します。彼らの血の力がほとんどのティーフリングを怒り、破壊、そして憤怒へと誘いますが、サキュバスの子孫でさえ聖人になり、ピットフィーンドの孫でさえ知らずのうちに英雄となることがあります。
]],
[race_ed_dd2]=[[
ティーフリングとは、先祖にデーモンやデビルなどの悪の来訪者の血を引く人間のことである。その奇妙な外見と不自然な物言いからしばしば迫害され、ほとんどのティーフリングはその本性を偽るか、文明社会の片隅や裏側で生きることを余儀なくされる。彼らは生まれながらにして悪なわけではないが、特に成長する過程で "普通の "人々の手によって苦しめられることが多いため、悪の道を見つけるのは容易である。

ティーフリングは、その奇妙な血統を示すいくつかの身体的特徴を除けば、ほとんどヒューマンに見える。 
]],
[race_ed_phy]=[[
ティーフリングは2人として同じ姿をしていない。彼らの血管を流れるフィーンドの血は一貫性がなく、さまざまなフィーンドの特徴を付与する。

あるティーフリングは、小さな角、有刺鉄線の尾、奇妙な色の目を持つ人間のように見えるかもしれないし、別のティーフリングは、牙の口、小さな翼、鉤爪を現すかもしれない。

一般的に、これらの性質はティーフリングの血統を生んだフィーンドに由来するものだが、それでもヒューマンとフィーンドの混血が正気で人間的な法則に支配されることはほとんどなく、ティーフリングに生まれる幅広い柔軟性は不思議なもので、奇妙に美しいものからまったく恐ろしいものまで様々なものがある。
]],
[race_ed_btl]=s_tiefling_fav_cls,
[race_ed_soc]=[[
物質界のティーフリングは、自分たちで集落や領地を作ることはほとんどない。その代わりに、彼らは生まれた土地や定住することを選んだ土地の片隅で暮らしている。ほとんどの社会ではティーフリングは異常か呪いであると見なされているが、招来されたフィーンドと頻繁に交流があり、特にデーモンや デビル、その他の邪悪な来訪者を崇拝することが合法か義務であるような文化圏では、ティーフリングはより人口が多く、受け入れられ、フィーンドの支配者の祝福として大切にされることさえある。

ティーフリングは同族を目にすることはめったにないため、通常は人間の両親の文化や作法をそのまま取り入れる。他の次元では、ティーフリングは同族の飛び地を形成する。ティーフリングの形態や哲学の多様性は、種族間の対立の本質的な原因であり、徒党や派閥が絶えず形成され、最も日和見的で悪賢い者だけが優位に立てる、常に移り変わる階層構造の中にある。共通の血統を持つ者か、生まれながらにして利己的で狡猾で邪悪な本性から自分の世界観を切り離すことに成功した者だけが、他の同族の中で真の受容、仲間意識、共通の基盤を見出すことができる。
]],
[race_ed_rel]=[[
ティーフリングは他のほとんどの種族からかなりの偏見にさらされており、彼らはティーフリングをフィーンドの産物、悪の種、怪物、世界にかけられた長引く呪いとみなしている。

文明的な種族は彼らを敬遠したり、疎外したりすることがあまりにも多い。一方、怪物的な種族は、強制されたり屈服させられたりしない限り、彼らを恐れ、拒絶するだけである。しかし、ハーフエルフ、ハーフオーク、フェッチリング、そして最も奇妙なことにアーシマールは、彼らを同胞とみなす傾向がある。

ティーフリングは生来悪の存在であるという思い込みが広く浸透しているが、それは根拠のないものであるため、非常に国際的な国や物質界の影響を受けた国を除き、多くの者が物質界のほとんどの文化に容易に溶け込むことができない。
]],
[race_ed_aln]=[[
ティーフリングはその悪魔的な遺産と偏見の陰湿な影響にもかかわらず、どのような属性にもなりうる。彼らの多くは精神につきまとう暗い欲望の餌食となり、内なる悪のささやきの誘惑に屈するが、一方で自らの出自を断固として拒否し、善行を行うことで邪悪な誘惑や他者からの否定的な思い込みと積極的に戦う者もいる。しかし、ほとんどの者は、この世界で自分自身の道を見つけようと努力するが、その際、非常に非道徳的で中立な見方をする傾向がある。

多くのクリーチャーはティーフリングが悪魔や悪霊を崇拝していると思い込んでいるが、彼らの宗教観はその肉体と同様に多様である。個々のティーフリングはあらゆる神々を崇拝するが、宗教を敬遠することもある。すべてのティーフリングの精神につきまとう暗いささやきに屈した者は、あらゆる強力な悪魔に仕える。
]],
[race_ed_adv]=[[
ティーフリングが故郷と呼ぶ人間社会に溶け込むことはほとんどない。逃亡の手段として冒険生活に引き込まれた彼らは、より良い生活を手に入れること、血の穢れからの解放を証明すること、あるいは自分たちを恐れ拒絶する世界に罰を与えることを望んでいる。

ティーフリングは熟練したローグ、強力なウィザード、特に強力なソーサラーになる。内なる邪悪に屈した者は、しばしば悪の力を持つ強力なクレリックとなる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
バル,デリサール,マルドレク,モロス,サルヴィン,ショーモス,テメリス,ヴォーレン,ゾーレン。

<c=twa>女性名:</c>
アリズサ,インドランナ,カシドラ,キララ,メリサン,モルドレン,ニーシャ。
]],
}


s_pc_elm_a="シルフ"
s_pc_elm_a_c="この青白くひょろっとした女性は、存在しない風に髪を揺らし、今にも霧の中に消えてしまいそうだ。"
s_pc_elm_a_fav_cls="シルフは策略を好み、どんな危険な状況からも抜け出す能力を兼ね備えているため、ローグ、シーフ、スパイとしての生活に完璧に適している。平均的なシルフの内気で気弱な表皮の下には、有能で計算高く、常に競争相手を見極め、与えられた部屋から最も効果的な出口を分析する心がある。"
s_pc_elm_a_traits=[[
<b c=tg>敏捷力+2、知力+2、 <c=tr>耐久力-2: </c></b>シルフは素早く洞察力に富んでいるが、小柄で繊細だ。]]
.."\n\n"..xs_lbl("s_res_ace_5")
.."\n\n"..xs_lbl("s_res_spl_air_race_1")
.."\n\n"..[[
<b>技能: </b>隠れ身、聞き耳、変装、情報収集の判定に＋2の種族ボーナスを与える。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_litn c=fc_b>ライトニングボルト</t>, <t=@pwr_sp_displacement c=fc_b>ディスプレースメント</t>, <t=@pwr_sp_cats_grace c=fc_b>キャッツグレイス</t> 1日1回使用する。呪文の使い手レベルはキャラクターのレベルに等しい。
]]
s_pc_elm_a_langs=[[
<b>自動習得言語: </b>共通語と風界語。
<b>ボーナス習得言語: </b>水界語、ドワーフ語、エルフ語、ノーム語、ハーフリング語、火界語、地界語。

<c=twc>シルフは共通語と風界語を話す。</c>
]]
s_pc_elm_a_d=[[
シルフはヒューマンの血とエレメンタルの血を混ぜ合わせたものである。

イフリート、オーレッド、ウンディーネと同様に、彼らは特定の元素支配を持つ強力なエレメンタルソーサラーになることができます。

彼らは美しくしなやかで、盗み聞きが得意な傾向がある。
]]
s_pc_elm_a_eds={
[race_ed_dd1]=[[
ジンのようなエアエレメントを持つ存在と人間の子孫から生まれたシルフは、内気で引っ込み思案な種族で、強い好奇心に支配されている。

シルフは群衆の中に紛れ込み、周囲の人々を盗み聞きしながら気づかれないように過ごす。彼らはこの趣味を「風の声を聞く」と呼び、多くのシルフにとってそれは強迫観念となる。

シルフはその有能で計算高い知性と、盗み聞きから得た知識を頼りに危険から身を守る。
]],
[race_ed_dd2]=[[
シルフは、ジンのようなエアエレメンタルの存在を家系に持つヒューマンである。彼らは青白く、華奢に見えるほど痩せている傾向があるが、その痩せた身体は見た目よりも回復力がある。シルフを注意深く観察している人は、窓のない部屋の中であっても、シルフの行くところどこにでも風がついてくるように見えることに気づくことがある。怒りや激情に駆られると、シルフの周囲を風が取り囲み、髪を束ねたり、棚から小物を落としたりする。シルフの多くは、その青白い肉体に、青や灰色のタトゥーのような小さな渦巻き模様のような複雑な印があり、その中でも最も特殊なシルフの髪は、まるで生きている霧でできているかのように、ねじれたり巻いたりしている。

人間としてのシルフは、内気で引っ込み思案な傾向があり、群衆に紛れ込んだり、会いたくない相手を巧みに避けたりする。しかし、シルフの多くは他者への好奇心が旺盛で、自分の興味をそそる人物をスパイしたり、盗み聞きしたりする（この趣味はしばしば "風の声を聞く "と呼ばれる）。このような裏工作の好きさと、どんな危険な状況からも抜け出す能力を併せ持つシルフは、ローグ、シーフ、スパイとしての生活に完璧に適している。平均的なシルフの内気で気弱な表皮の下には、有能で計算高い精神があり、常に競争相手を見極め、与えられた部屋から最も効果的な出口を分析する。
]],
[race_ed_phy]=[[
シルフは青白く、華奢に見えるほど痩せている傾向があるが、その痩せた体は見た目以上に回復力があることが多い。

シルフの多くは、努力次第で簡単にヒューマンになりすますことができるが、皮膚に渦巻く複雑な青い印がエレメンタルの先祖であることを明らかにしている。

シルフはまた、どこへ行くにも微風がついてくるなど、その血統を示すより微妙な兆候も持っている。これらの兆候は、シルフが激しい情熱や怒りを経験すると顕著になり、突風がシルフの髪をなびかせたり、熱い風が棚から小物を叩き落としたりする。
]],
[race_ed_soc]=[[
シルフは通常、ヒューマンの両親から生まれ、人間の習慣に従って育てられる。ほとんどのシルフは人間社会で育つと注目されるのを嫌うので、成人してすぐに家を出るのが普通である。しかし、完全に文明を捨てることはまれで、その代わりに、大衆の中で（スパイとして）気づかれずにいられるような新しい都市や集落を見つけることを好む。

他のシルフに気づかれずに出くわしたシルフは、即座にその親族に執着し、相手のことをスパイして可能な限り知るようになる。すべての長所と短所を検討し、あらゆる可能性のある結果に対する計画を立てた後で、初めてそのシルフはもう一人のシルフに自己紹介する。

まれに、2匹のシルフが同時にお互いの存在を発見することがある。その後に続くのは、一種の猫とネズミのゲームであり、お互いが優位に立とうと相手をスパイする複雑なダンスである。このようにして出会ったシルフは、いつも切っても切れない友人か、難敵のどちらかになる。
]],
[race_ed_rel]=[[
シルフは他の種族のことを詮索するのは好きだが、実際に付き合う趣味はほとんどない。

シルフは、のんびりとした傾向を共有するエルフとはある程度の関係を築けるが、エルフのプライバシー感覚を侵害することで、せっかくの関係を台無しにしてしまうことが多い。

ドワーフはシルフを激しく不信視しており、彼らは気まぐれで信頼できないとみなしている。

彼らはハーフリングと優れた協力関係を築き、背の低い民の勇気と人付き合いの技能に頼って、自らの欠点をカバーする。

シルフは、イフリートの苛立たしい反応を面白がっている。
]],
[race_ed_aln]=[[
シルフは法律や伝統をほとんど顧みない。そのような厳格さは、シルフが愛するもの、すなわち策略や秘密主義そのものを禁止することが多いからである。これはシルフが法に反対しているという意味ではなく、秩序であろうとなかろうと、目的を達成するために最も都合のよい手段を用いるという意味である。したがって、ほとんどのシルフは中立な立場にある。

シルフはミステリーカルトや、極意、旅行、知識を重視する神々に惹かれる。
]],
[race_ed_adv]=[[
物事の真相を突き止めたいという先天的な衝動が、多くのシルフを冒険生活に駆り立てる。

謎の痕跡に出くわしたシルフは、あらゆる証拠を見つけ出し、あらゆる手がかりを追いかけ、問題の核心を見つけるまで決して満足することはないだろう。

そのようなシルフは、他人のことに首を突っ込むことで多くの敵を作り、たいていは悪巧みの才能や ウィザードの力を借りて身を守る。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アカーシュ,エイダン,ハヌーン,シイヴァル,バサーム。

<c=twa>女性名:</c>
イナム,キーヤ,リシ,ナバ,ラダヤ,テナ。
]],
}


s_pc_elm_f="イフリート"
s_pc_elm_f_c="この筋骨隆々で獰猛な肌の男は、炎のような髪と眉間に斑点があり角を持っている。"
s_pc_elm_f_fav_cls="炎を操る能力を持つイフリートは、他の種族にはない強力な炎のソーサラーであり、炎を操るウォーリアーである。"
s_pc_elm_f_traits=[[
<b c=tg>+敏捷力 2、+魅力 2、 <c=tr>判断力-2: </c></b>イフリートは情熱的で素早い反面、せっかちで破壊的でもある。]]
.."\n\n"..xs_lbl("s_res_f_5")
.."\n\n"..xs_lbl("s_res_spl_fire_race_1")
.."\n\n"..[[
<b>技能: </b>跳躍、軽業、威嚇、はったりの判定に+2の種族ボーナスを得る。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_burning_hands c=fc_b>バーニングハンズ</t>, <t=@pwr_sp_fire_ball c=fc_b>ファイアーボール</t>, <t=@pwr_sp_rage2 c=fc_b>激怒</t>1日1回使用する。呪文の使い手レベルはキャラクターレベルに等しい。
]]
s_pc_elm_f_langs=[[
<b>自動習得言語: </b>共通語と火界語。
<b>ボーナス習得言語: </b>水界語、風界語、ドワーフ語、エルフ語、ノーム語、ハーフリング語、地界語。

<c=twc>イフリートは共通語と火界語を話す。</c>
]]
s_pc_elm_f_d=[[
イフリートはヒューマンから派生した種族で、火の平原に住む奇妙な住人である。

彼らの身体的特徴や性格は、その激しい出自を裏切ることが多く、落ち着きがなく、独立心が強く、威圧的な傾向がある。

炎を操る能力を持つイフリートは、他の種族にはない強力な炎のソーサラーであり、炎を操るウォーリアーである。
]]
s_pc_elm_f_eds={
[race_ed_dd1]=[[
イフリートのような火のエレメントを持つ存在を祖先に持つイフリートは、情熱的で気まぐれな種族である。

山火事のように、イフリートは動き続けなければ燃え尽きる。イフリートは炎を崇拝するだけでなく、炎のさまざまな側面を擬人化し、炎のダイナミックで変化し続けるエネルギーと、破壊的で無慈悲な性質の両方を体現している。
]],
[race_ed_dd2]=[[
イフリートは、火のエレメントを持つ存在を祖先に持つヒューマンである。イフリートは尖った耳を持ち、眉間には赤や斑点のある角が生え、髪は炎のように揺らめき波打つ。

イフリートはみな、ある意味では火狂である。あらゆる形の炎を崇拝する彼らは、情熱的で素早い行動をとる傾向があり、争いの際には先制攻撃を仕掛ける傾向がある。イフリートは一般的に、命令に従わせることができる力の弱い手下か、イフリートのバランスをとることができる冷静沈着な人物を仲間に求める。
]],
[race_ed_phy]=[[
イフリートの外見は、彼らの祖先であるエレメンタルと同じように多種多様である。多くはとがった耳を持ち、眉間には赤や斑点のある角が生え、髪は炎のように揺らめき波打つ。磨かれた真鍮のような肌や、炭のような色をした鱗が手足を覆っている者もいる。

イフリートは鮮やかなオレンジや赤を基調とした露出度の高い仰々しい服を好み、できれば派手なジュエリーと組み合わせたい。
]],
[race_ed_soc]=[[
イフリートは人間社会に生まれることがほとんどで、独自の社会を形成することはほとんどない。

都市で育った者は、ほとんどの場合、大人になる前に投獄されるか、追放される。ほとんどの者は、文明社会に適合するにはあまりにも熱血漢で独立心が強く、放火癖があるため、地元当局に気に入られないのだ。

イフリートは本能的に周囲を捜索し、征服しようとする衝動に駆られるため、遊牧民社会や部族社会に生まれた者は、部族のリーダーとしての地位を容易に得ることができる。
]],
[race_ed_rel]=[[
気立てのいいイフリートでさえ、他の個人を自分の思うように利用する道具とみなす傾向があり、そのため、彼らを魅了したり、屈服させたりできる人種と最もうまくやっていく。

ハーフエルフやノームはイフリートの策略に巻き込まれることが多いが、ハーフリング、ハーフオーク、ドワーフはイフリートの支配的な性格に憤慨することが多い。

不思議なことに、イフリートはエルフと信じられないほど親密な絆を結ぶことがある。彼らの冷静で飄々とした性格は、イフリートの衝動性を打ち消しているようだ。

ほとんどのイフリートはシルフとの交際を拒むが、他のエレメンタルを持つ種族とは平和的な関係を築いている。
]],
[race_ed_aln]=[[
イフリートは、一方では独立心が旺盛で、他方では威圧的で要求が厳しいという二面性を持っている。彼らはしばしば道徳的に貧しいと非難されるが、彼らの問題行動が真の悪意によって動機づけられていることはほとんどない。イフリートは通常、秩序にして中立か混沌にして中立であり、真なる中立に陥る者は少数である。

イフリートの多くは神の教えに従う心構えに欠けており、組織化された信仰によって課される厳格さに憤慨している。イフリートが礼拝（たいていは火にまつわる神を崇める）をするときは、熱心で献身的な信者であることを証明する。
]],
[race_ed_adv]=[[
イフリートが冒険をするのは、スリルを味わうためや、価値ある敵を相手に腕試しをするためでもあるが、何よりも力を求めて冒険をするのだ。

イフリートはひとたびある仕事に没頭すると、目の前の危険を顧みることなく、ひたすらそれを追い求める。その猪突猛進さが災いして、イフリートはしばしばソーサラーやバードの魔法に頼ることになる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アジャ,デナト,エフィット,エルム,ジャリジ,マケジ,ウラ。

<c=twa>女性名:</c>
アライ,エトワ,マカン,カリ,サミ,ゼタヤ。
]],
}


s_pc_elm_w="ウンディーネ"
s_pc_elm_w_c="この青い髪、青い肌の男は、流れるような優雅さで動く。耳はひれのようで、手足には網がある。"
s_pc_elm_w_fav_cls="ウンディーネは水に親和性があるため、特にドルイドに向いている。"
s_pc_elm_w_traits=[[
<b c=tg>敏捷力+2、判断力+2, <c=tr>筋力-2: </c></b>ウンディーネは鋭敏で機敏だが、力には力で対抗するのではなく、順応する傾向がある。]]
.."\n\n"..xs_lbl("s_res_c_5")
.."\n\n"..xs_lbl("s_res_spl_water_race_1")
.."\n\n"..[[
<b>技能: </b>水泳、鑑定、治療、交渉判定に種族ボーナス2。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_heal c=fc_b>キュアウーンズ</t>, <t=@pwr_sp_bless c=fc_b>ブレス</t>, <t=@pwr_sp_aid c=fc_b>エイド</t> 1日1回使用する。呪文の使い手レベルはキャラクターのレベルに等しい。
]]
s_pc_elm_w_langs=[[
<b>自動習得言語: </b>共通語と水界語。
<b>ボーナス習得言語: </b>風界語、ドワーフ語、エルフ語、ノーム語、ハーフリング語、火界語、地界語。

<c=twc>ウンディーネは共通語と水界語を話す。</c>
]]
s_pc_elm_w_d=[[
イフリート、オーレッド、シルフといった従兄弟たちと同様、ウンディーネは異次元のエレメントに触れたヒューマンである。

彼らはエレメンタルウォーターの子孫であり、陸上でも水中でも同じように優雅である。

ウンディーネは適応力があり、寒さに強く、水の魔法に親和性がある。
]]
s_pc_elm_w_eds={
[race_ed_dd1]=[[
ウンディーネは、水の次元に住むクリーチャーを祖先とするヒューマンである。ウンディーネの肉体は湖、海の色に似ているからである。海人の血を引く者であれ、水のメフィットの血を引く者であれ、すべてのウンディーネはその祖先を通じて自分自身を定義する。ウンディーネはその個体差を才能として認識し、固有の血統が持つ超自然的な側面を最大限に探求する。

ウンディーネは誇り高い種族で、外見上はほとんど恐れを感じさせない。ウンディーネの仲間内ではお人好しで少々遊び好きだが、ウンディーネ以外の種族と一緒にいるときは、やや控えめで真面目な振る舞いをする。感情のコントロールに優れており、数分のうちに冷静な状態から激怒した状態にまで、またすぐに戻ることができる。その行動を常軌を逸したものと呼ぶ人もいるかもしれないが、ウンディーネは他の種族よりも外見的にメロドラマチックなだけである。確かに、彼らは不機嫌ではないし、挑発なしに怒ったり、興奮したり、感情的になることもない。親しい友人に対しては、独占欲が強すぎると感じる人もいるが、大切な人を非常に大切にする一面もある。

ウンディーネは水辺に住み着く傾向があり、たいていは温暖な気候にいる。陸上生活者ではあるが、かなりの時間を水の中で過ごす。そのため、服装は質素で、風雨から身を守れる程度のものしか身につけず、靴を履く者はほとんどいない。首にアクセサリーをつけることは避け、髪は後ろに流してきつく結ぶ。これは、泳いでいるときに髪や他のものが邪魔になったり邪魔になったりするのを防ぐためだ。同様に、武術のクラスを目指すウンディーネは、水中だけでなく陸上でも効率よく扱える武器を選ぶ。
]],
[race_ed_dd2]=[[
ウンディーネは、その祖先にマリードなどの水の元素の存在が含まれる人間です。

ウンディーネの場合、水の次元とのつながりは、彼らの色合いに最も顕著に現れます。彼らの肌や髪の色は、湖や海のような色合いを模倣する傾向があります。すべてのウンディーネは透明な青い目を持ち、肌や髪の色は淡い青白から海の深い青や緑まで様々です。
]],
[race_ed_phy]=[[
ウンディーネの肌色は、淡いターコイズブルーから深いブルー、シーグリーンまで幅広いバリエーションを見せる。ウンディーネのまっすぐで太い髪は、肌と同じような色をしているが、やや暗い色をしている。すべてのウンディーネの目は青く澄んでいる。

肉体的にはウンディーネは人間に最も似ており、その体格は全体的な身長と体型に関して人間の多様性を示している。

色彩を除けば、彼らの種族的特徴として最も残っているのは、ヒレのような耳と網状の手足である。
]],
[race_ed_soc]=[[
ウンディーネは自らをユニークな種族と定義し、ウンディーネの子孫を残すことができる。ウンディーネはヒューマンとの交配が可能だが、自分たちだけで行動する傾向があり、水辺や、場合によっては浮遊集落の近くに小さな集落を形成する。ウンディーネの集落での婚姻は一般的で、子供たちは共同で育てられる。

典型的なウンディーネの集落は、合議によって任命された役人からなる小規模な評議会の指導のもとに生活している。評議員の地位は無期限に維持できるが、評議員のパフォーマンスに不満のある集落は辞任を求めることができる。

ウンディーネの文化には、独立した集落の特定の祖先の影響を受けて、かなりの地域的多様性が存在する。また、ウンディーネは自分の集落以外のウンディーネと結婚することもあるため、ひとつの集落に住むすべてのウンディーネが同じ祖先を持つとは限らない。
]],
[race_ed_rel]=[[
ウンディーネは特定の種族に対する偏見を持たない。彼らのコミュニティは主に交易に依存しているため、多様な来訪者や外国人と交流する機会が多い。ウンディーネと近隣の水域の両方に十分な配慮がなされるのであれば、他種族の居住区に近所を作ることに何の抵抗もない。しかし、そのような場合でも、ウンディーネのコミュニティは自治を維持するためにできることをする。

ウンディーネはエルフやノームと非常に仲が良い。これらの種族はしばしば森林の湖や小川を保護する任務を分担する。同様に、善または中立の水棲人型生物とも好意的に交流し、多くの共通の利益を共有する。彼らは人間やドワーフと最も自由に物々交換を行い、金属や布などの資源を得る。
]],
[race_ed_aln]=[[
ほとんどのウンディーネは中立である。ウンディーンの主な関心は人々の福祉にあり、そのため彼らの道徳的関心は共同体や自分自身に向けられる。この中立的な考え方のおかげで、ウンディーネ以外の種族とも広く交流し、交易を行うことができる。

深い信仰心はないが、ウンディーネは超自然的な祖先や水そのものと強い精神的なつながりを持っている。非世俗的な道を追求する者たちは、ほとんどの場合、祖先の神々や、水の何らかの側面を持つ神々を崇拝する。
]],
[race_ed_adv]=[[
時折、ウンディーネは冒険生活を求めて仲間を離れることがある。水そのものがそうであるように、ウンディーネの中にも単に動きたくなる者がいて、冒険は彼らに旅暮らしの十分な口実を与えてくれる。

ウンディーネ社会では、追放は犯罪に対する一般的な罰である。他の選択肢がほとんどないため、亡命者の多くは新しい居場所を求めて冒険に出る。

ウンディーネは水に親和性があるため、特にドルイドに向いている。一方、ウンディーネのソーサラーは通常、水生生物の血統を持っている。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アヴェン,ダラク,ギブ,ジャマッシュ,マアコール,オンディール,ラディッド,シラダーズ。

<c=twa>女性名:</c>
アフザラ,バーラー,カラ,イリャニ,マーリン,ニルグネ,パリ,ラダベ,ウルダナ。
]],
}


s_pc_elm_e="オーレッド"
s_pc_elm_e_c="この大柄なウォーリアーはずっしりと重く、角ばった彫像のように見える。"
s_pc_elm_e_fav_cls="オーレッドは、その驚異的な強さと自己鍛錬のおかげで、良いモンクやファイターになる。"
s_pc_elm_e_traits=[[
<b c=tg>筋力+2、判断力+2、<c=tr>魅力-2: </c></b>オーレッドは強く、堅実で、安定していて、ストイックだ。]]
.."\n\n"..xs_lbl("s_res_a_5")
.."\n\n"..xs_lbl("s_res_spl_earth_race_1")
.."\n\n"..[[
<b>技能: </b>登攀、視認、生存、集中の判定に＋2の種族ボーナスを与える。

<b>呪文のような能力: </b>詠唱可<t=@pwr_sp_shield_other c=fc_b>シールドアザー</t>, <t=@pwr_sp_stoneskin c=fc_b>ストーンスキン</t>, <t=@pwr_sp_bears_endurance c=fc_b>ベアーズエンデュランス</t>1日1回使用する。呪文の使い手レベルはキャラクターレベルに等しい。
]]
s_pc_elm_e_langs=[[
<b>自動習得言語: </b>共通語と地界語。
<b>ボーナス習得言語: </b>水界語、風界語、ドワーフ語、エルフ語、ノーム語、ハーフリング語、火界語、地下共通語。

<c=twc>オーレッドは共通語と地界語を話す。</c>
]]
s_pc_elm_e_d=[[
ヒューマンの祖先に大地の次元のクリーチャーの血が混ざったクリーチャーであるオーレッドは、石のように強く堅固である。 

頑固で堅実な性格のため、ドワーフ以外のほとんどの種族とうまくやっていくのは難しい。

オーレッドは石と大地の生の力を操ることができる優れたウォーリアーやソーサラーになる。
]]
s_pc_elm_e_eds={
[race_ed_dd1]=[[
オーレッドは、その血統に地の元素の存在が含まれることがあり、しばしばシャイターンジニーなどの存在です。

ストイックで瞑想的なオーレッドは、簡単には動じないが、行動を起こすとほとんど止められない種族である。引っ込み思案な性格のため、世界の大半の人々には謎に包まれているが、人里離れた山の隠れ家で彼らを探し求める人々は、オーレッドが物静かで頼りになり、仲間を守ってくれることに気づく。
]],
[race_ed_dd2]=[[
オーレッドは、祖先のどこかに大地のエレメンタルビーイング（多くの場合、シャイタンの精霊）の影響を受けたヒューマンである。オーレッドは強靭で堅固な体格をしており、灰色、茶色、黒、白など、肉や髪の色と同じアースカラーを好んで身につける。まれに、オーレッドの石のような形質は、その性質に疑いの余地がないほど強く、岩の突起のようなものが肌や髪から結晶のトゲのように突き出ている。

オーレッドはストイックで瞑想的な傾向があり、怒るのは遅いが興奮すると恐ろしい。戦闘以外では、物静かで頼りがいがあり、仲間を守る傾向がある。
]],
[race_ed_phy]=[[
オーレッドはたくましく、がっしりとした体格をしており、肌や髪の色は黒、茶、灰色、白といった石のような色合いをしている。

オーレッドは皆、どことなく土っぽく見えるが、中には、磨かれたオニキスのように輝く肌、肉から突き出た岩のような突起、輝く宝石のような目、水晶のトゲのような髪など、元素を受け継いでいることを顕著に示す者もいる。

アースカラーを基調とした服装が多く、活発な運動に適した実用的な衣服を身につけ、複雑な宝飾品よりも生花やシンプルな宝石など自然のアクセントを好む。
]],
[race_ed_soc]=[[
人類の下級な分派であるオーレッドには、独自の社会が確立されていない。その代わり、ほとんどのオーレッドは人間の社会で両親の習慣を学んで育つ。

大人のオーレッドは、他の種族の間では隠者で一匹狼という評判が高い。都市生活の喧騒に馴染む者はほとんどおらず、人里離れた山の頂上や、人里離れた洞窟の地下深くで、静かに思索にふける日々を好む。

ヒューマンの生活により寛容なオーレッドは、しばしば市警に加わるか、責任ある立場で地域社会に奉仕する方法を見つける。
]],
[race_ed_rel]=[[
オーレッドは、共通点の多いドワーフと一緒にいると心地よく感じる。

彼らはノームを奇妙すぎると感じ、多くのハーフリングを生意気すぎると感じるので、これらの種族全般を避ける。

オーレッドはハーフオークやハーフエルフと喜んで付き合い、性格の不一致は避けられないものの、他の部分人類種族に親近感を覚える。

エレメンタルに触れる種族の中で、オーレッドには友人は少ないが真の敵はいない。
]],
[race_ed_aln]=[[
オーレッドは、おそらく他の何よりも、自分たちのやり方を確立しており、彼らの日常を乱すことは静かな不賛成をもって迎えられる。

オーレッドは友人を非常に大切にするが、狭い知人の輪の外の人々の幸福には特に関心がないようだ。そのため、ほとんどのオーレッドは秩序にして中立である。

宗教的な生活は、大地を愛する人々にとって容易なものだ。彼らは修道会の静かで瞑想的な生活を好み、ほとんどの場合、大地や自然に関連する神々の崇拝に身を捧げる。
]],
[race_ed_adv]=[[
オーレッドは、最初は冒険をためらう。故郷を離れることを嫌い、新しい経験によるショックにうまく対処できない。通常、オーレッドを行動に駆り立てるには、外からの何らかの力が必要であり、多くの場合、家、生活、友人を脅かすことによってである。しかし、一旦その脅威に対処すると、オーレッドは冒険生活に慣れ、その後も冒険生活を続けることが多い。

オーレッドは、その驚異的な強さと自己鍛錬のおかげで、良いモンクや ファイターになる。
]],
[race_ed_nam]=[[
<c=twa>男性名:</c>
アンダナン,ジェイダブ,メンティス,オレット,シトゥンダン,ウルター。

<c=twa>女性名:</c>
ベスタナ,エチャネ,ガティヤラ,イリーチェ,ナイセネ,パシェ。
]],
}


s_heat="ヒート"
s_heat_d="アーザーの体は非常に熱く、そのため素手攻撃は火属性の追加ダメージを与える。金属製の武器もこのヒートを伝導する。"

s_azer="アーザー"
s_azer_c="熱がこのずんぐりした真鍮色の肌を持つ人型生物の近くの空気を揺らしている。その頭と肩は炎のたてがみで燃えている。"
s_azer_fav_cls="金属製の武器や道具にヒートを通すことができるアーザーは、非金属製の武器を使うことはほとんどなく、通常、範囲攻撃ではなく近接戦闘を行う。"
s_azer_traits=[[
<b c=tg>筋力+2、敏捷力+2、耐久力+2、知力+2、判断力+2、 <c=tr>魅力-2: </c></b>愛想がなく寡黙だが、アーザーはあらゆる面で優れたパフォーマンスを発揮する。

<b>種族ヒットダイス(HD): </b>アーザーは2レベルの来訪者からスタートし、2d8のヒットダイス(HD)を得る。

<b>種族技能: </b>アーザーの来訪者レベルは5×（8＋知力修正値）に等しい技能ポイントを与える。クラス技能は鑑定、登攀、クラフト、隠れ身、跳躍、聞き耳、捜索、視認である。

<b>種族特技: </b>アーザーの来訪者レベルは1つの特技を与える。

<b>鎧: </b>外皮ボーナス+6。

<b>武器と防具の熟練度: </b>単純武器、ウォーハンマー、軽装鎧、中装鎧、盾に熟練している。

<b>特別な資質: </b><t=@pwr_heat c=fc_b>ヒート</t>, <t=@pwr_imm_f c=fc_b>イミュニティトゥファイア</t>, <t=@pwr_vul_c c=fc_b>バルナビリティトゥコールド</t>, <t=@pwr_spl_res_13 c=fc_b>呪文耐性13以上</t>。
]]
s_azer_langs=[[
<b>自動習得言語: </b>共通語と火界語。
<b>ボーナス習得言語: </b>奈落語(アビサル)、水界語、風界語、天上語(セレスチャル)、地獄語(インファーナル)、地界語。

<c=twc>アーザーは火界語と共通語を話す。</c>
]]
s_azer_d=[[
アーザーは火の元素界に住むドワーフのような存在である。真鍮、青銅、銅のキルトを身にまとい、火界語と共通語を話す。アーザーは見慣れない目にはお互いによく似ているように見える。身長は4フィートだが、体重は200ポンドもある。

アーザーは、全員が自分の立場をわきまえた社会で暮らしている。アーザー人は青銅と真鍮の要塞で労働に励み、イフリートとの長く煮えたぎる戦争に常に備えている。

伝説の都市ブラスは、50万人を超えるアーザー人口を誇る。これらの不運なアーザーたちのほとんどは、イフリートの主人に隷属する生活を送っている。

真鍮の都を出たアーザーは、他の惑星の大都市で商品を作ったり、品物を売ったり、酒場を経営したりして、自由に生活している。
]]
s_azer_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
アーザーは戦闘の際、頭の広い槍やよく練られたハンマーを使う。素手の場合は敵に組み付こうとする。

金属製の武器や道具にヒートを通すことができるアーザーは、非金属製の武器を使うことはほとんどなく、通常、範囲攻撃ではなく近接戦闘を行う。

非友好的で寡黙だが、アーザーが大好きな宝石を敵から奪うため以外には、戦いを挑むことはめったにない。

脅かされれば死にものぐるいで戦うが、捕虜を自ら取ることに価値を見出す。アーザーは頻繁に捕虜を捕らえ、要塞に連れ帰り、1年1日の労働を強いる。
]],
[race_ed_soc]=[[
アーザーは、全員が自分の居場所を知っている社会に住んでいる。特定の職務、通常は父親か母親の職業に生まれ、アーザーは生涯その職務を続ける。

カースト制度は、アーザーの社会をさらに秩序立てている。疑問の余地なく支配する貴族は、カーストの象徴として装飾の施された真鍮のキルトを着用し、商人や事業主は頑丈なブロンズを着用する。銅のキルトは、使用人、職人、労働者からなる労働者階級を示す。

伝説の都市ブラスは、50万人を超えるアーザー人口を誇る。これらの不運なアーザーたちのほとんどは、イフリートの主人に隷属する生活を送っている。

奴隷にされたアーザーは、契約を待つか、主人が死ぬか倒されることを願いながら、何の疑問も持たずに職務を遂行する。この種族には秩序への献身が強く燃え盛っており、奴隷にされたアーザーたちの中には、自分の親族を管理する主人として行動する者もいるほどだ。

真鍮の都を出たアーザーは、他の次元の大都市で商品を作ったり、品物を売ったり、酒場を経営したりして、自由に生活している。
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}

s_genie			="ジーニー"
s_genie_d		=[[ジーニーはエレメンタルの次元に住むヒューマンのような存在である。彼らはその強さ、狡猾さ、幻影魔法の巧みさで有名である。

ジーニーは敵を出し抜き、出し抜くことを好む。また別の日に戦えるというのであれば、逃げることも辞さない。捕らわれの身となった場合、命と自由の代償として財宝や便宜を提供する。]]

