s_elm_a2		="エアエレメンタル"	s_elm_a2_d=[[エアエレメンタルは風界語を話すが、自分から話すことはほとんどない。

<b c=tw>戦闘</b>
その素早いスピードにより、エアエレメンタルは広大な戦場や長時間の空中戦で重宝される。

<b c=tw>エアエレメンタルサイズ</b>
<b c=tw>エレメンタル	高さ	重量</b>
小型	4フィート。	1ポンド。
中型	8フィート。	2ポンド。
大型	16フィート。	4ポンド。
巨大	32フィート。	8ポンド。
偉大	36フィート。	10ポンド。
古代	40フィート。	12ポンド。]]

s_elm_e2		="アースエレメンタル"	s_elm_e2_d=[[物質界に招来されたアースエレメンタルは、それが呼び出された土、石、貴金属、宝石の種類に関係なく構成される。

アースエレメンタルは地界語を話すが、それを選択することはほとんどない。

<b c=tw>戦闘</b>
アースエレメンタルの動きは遅いが、容赦のない敵である。人間が地表を歩くのと同じくらい簡単に、固い地面や石の上を移動することができる。しかし泳ぐことはできず、水域の周りを歩くか、水域の下の地面を通らなければならない。アースエレメンタルは水底を移動することもできるが、そうしないことを好む。

<b c=tw>アースエレメンタルサイズ</b>
<b c=tw>エレメンタル	高さ	重量</b>
小型	4フィート。	80ポンド。
中型	8フィート。	750ポンド。
大型	16フィート。	6,000ポンド。
巨大	32フィート。	48,000ポンド。
偉大	36フィート。	54,000ポンド。
偉大	40フィート。	60,000ポンド。]]

s_elm_f2		="ファイアエレメンタル"	s_elm_f2_d=[[ファイアエレメンタルは水やその他の不燃性の液体には入れない。ファイアエレメンタルが踏み越えるか跳躍しない限り、水域は侵入不可能な障壁となる。

ファイアエレメンタルはイグナ語を話すが、自分から話すことはほとんどない。

<b c=tw>戦闘</b>
ファイアエレメンタルは獰猛な敵で、敵を直接、残忍に攻撃する。物質界のクリーチャーや物体を燃やして灰にすることに喜びを感じる。

<b c=tw>ファイアエレメンタル サイズ 		火炎セーヴ難易度(DC)</b>
<b c=tw>エレメンタル	高さ	重量</b>
小型	4フィート。	1ポンド。	11
中型	8フィート。	2ポンド。	14
大型	16フィート。	4ポンド。	17
巨大	32フィート。	8ポンド。	22
偉大	36フィート。	10ポンド。	24
古代	40フィート。	12ポンド。	26]]

s_elm_w2		="ウォータエレメンタル"	s_elm_w2_d=[[ウォータエレメンタルは、それを呼び出した水域から180フィート以上離れることはできない。

ウォータエレメンタルはアクア語を話すが、それを選択することはほとんどない。

<b c=tw>戦闘</b>
ウォータエレメンタルは大きな水域での戦いを好み、波の下に姿を消し、相手の背後で突然うねり出すことができる。

<b c=tw>ウォータエレメンタルサイズ</b>
