小型	4フィート。	34ポンド。
中型	8フィート。	280ポンド。
大型	16フィート。	2,250ポンド。
巨大	32フィート。	18,000ポンド。
偉大	36フィート。	21,000ポンド。
古代	40フィート。	24,000ポンド。]]

s_air_mastery	="エアマスタリー"		s_air_mastery_d		="空中のクリーチャーは、エアエレメンタルに対する攻撃ロールとダメージロールに-1のペナルティを受ける。"
s_earth_mastery	="アースマスタリー"	s_earth_mastery_d	="アースエレメンタルは、自分と敵の両方が地面に触れている場合、攻撃ロールとダメージロールに＋1のボーナスを得る。相手が空中にいるか水中にいる場合、エレメンタルはこれらのロールに-4のペナルティを受ける。"
s_water_mastery	="ウォータマスタリー"	s_water_mastery_d	="ウォータエレメ ンタルと対戦相手の両方が水に触れている場合、攻撃と ダメージのロールに+1のボーナスを得る。相手かエレメンタルが地面に触れている場合、エレメンタル はこれらのロールに-4のペナルティを受ける。エレメンタルは小型の船(エレメンタルのヒットダイス(HD)1つにつき長さ5 フィート)を簡単に横転させ、大型の船(ヒットダイス(HD)1つにつき長さ10フィート)を止めることができる。大型船（1ヒットダイス(HD)につき全長20フィート）でさえ、半分の速度まで減速させることができる。"
s_earth_push	="押す"				s_earth_push_d		="アースエレメンタルは機会攻撃を誘発させることなく突進技能を開始できる。アースマスタリーで与えられる戦闘修正はエレメンタルの戦闘技能判定にも適用される。"
s_earth_glide	="地中滑走"		s_earth_glide_d		="アースエレメンタルは、魚が水の中を泳ぐのと同じくらい簡単に、石や土、あるいは金属以外のほとんどあらゆる種類の土の中を滑るように進むことができる。穴を掘ってもトンネルや穴は残らないし、波紋やその他の痕跡も残さない。"
s_fire_burn		="燃焼"				s_fire_burn_d		="ファイアエレメンタルの叩きつけ攻撃は殴打ダメージに加え、エレメンタルの炎の体による火炎ダメージを与える。ファイアエレメンタルの叩きつけ攻撃を受けた者はまた、反応セーヴ（難易度(DC)=10＋エレメンタルのヒットダイス(HD)/2＋耐久力修正値）に成功しなければ炎に包まれる。炎は1d4ラウンド燃え続ける。燃えているクリーチャーは移動アクションで炎を消すことができる。肉体武器や素手攻撃でファイアエレメンタルと当たったクリーチャーは、エレメンタルの攻撃に当たったのと同じように 火炎ダメージを受け、反応セーヴに成功しない限り火に包まれる。"
s_water_drench	="ずぶ濡れ"			s_water_drench_d	="エレメンタルの接触は、松明、キャンプファイヤー、露出したランタン、その他の非魔法的な起源の火を消す。クリーチャーは触れた魔法の炎をディスペルマジックとして消すことができる（呪文の使い手レベルはエレメンタルのヒットダイス(HD)に等しい）。"
s_water_skls	="技能"			s_water_skls_d		="ウォータエレメンタルは、何か特別な行動を行なったり危険を避けたりするための水泳判定に＋8の種族ボーナスを持つ。注意散漫であっても、危険にさらされていても、水泳判定は常にテイク10できる。泳いでいる間、直線上を泳ぐのであれば、疾走するアクションを使用できる。"
s_air_whirlwind	="旋風"		s_air_whirlwind_d	=""
s_water_vortex	="渦巻き"			s_water_vortex_d	=""

-- 异怪		Aberration
s_naga			="ナーガ"
s_naga_d		=[[すべてのナーガは長い蛇のような体を輝く鱗で覆われ、多かれ少なかれヒューマンの顔をしている。体長は10フィートから20フィート、体重は200ポンドから500ポンドである。ナーガの目は明るく聡明で、ほとんど催眠術のような内なる光を放っている。

ナーガは他の戦闘形態よりも呪文を好みます。彼らはほとんど常に自らが守る巣穴にいて、よく知っているため、ほとんどの遭遇を自分たちの望みに合わせて配置することができます。]]

-- 龙		Dragon
s_true_dragon	="トゥルードラゴン"
s_true_dragon_d	=[[トゥルードラゴンの種類は、他のクリーチャーとは異なり、一般的には二つの大きなカテゴリーに分類されます。クロマティックとメタリックです。

クロマティックドラゴンは黒、青、緑、赤、白で、どれも邪悪で非常に獰猛だ。

メタリックドラゴンとは、真鍮、青銅、銅、金、銀のことで、いずれも善で、たいていは気高く、賢者から非常に尊敬されている。

すべてのトゥルードラゴンは年齢を重ねるにつれて、より多くの能力とより大きなパワーを得る。(ドラゴンの体長は孵化時の数フィートから、長老の地位を得た後の100フィート以上に及ぶ。特定のドラゴンのサイズは年齢や種類によって異なる。

すべてのドラゴンは竜語を話す。]]
s_true_dragon_e	=[[ドラゴンの代謝作用は非常に効率的な炉のように機能し、無機物さえも代謝することができます。一部のドラゴンはそのような食べ物を好むようになっています。

ドラゴンの種類によって目標や理想は異なるが、どのドラゴンも貪欲である。彼らは富をため込むことを好み、コインの山を集め、できるだけ多くの宝石、宝玉、魔法のアイテムを集める。大きな財宝を持つものは、その財宝から長く離れることを嫌い、巣から出るのはその近辺をパトロールするか、食料を調達するときだけである。ドラゴンにとって、宝はいくらあっても足りない。見ているだけでも楽しいし、彼らはその輝きに酔いしれる。ドラゴンはその宝をベッドにするのが好きで、自分の体に合わせて隅々まで形を整える。ドラゴンが長老に成長する頃には、何百もの宝石やコインがその皮に埋め込まれているかもしれない。]]

s_half_dragon	="ハーフドラゴン"
s_half_dragon_d	=[[ハーフドラゴンのクリーチャーは、ドラゴンの血を受け継いでいない同種のクリーチャーよりも常に手強く、その外見はその性質を裏切る鱗、細長い特徴、爬虫類のような目、誇張された歯と爪を持っている。翼を持つこともある。]]

-- 动物		Animal
s_rat			="ラット"
s_rat_d			=[[この雑食性のげっ歯類は、ほとんどどこでも繁栄する。戦いに直面すると、ラットはたいてい逃げる。噛むのは最後の手段だ。]]

s_rat_x			="ダイア ラット"
s_rat_x_c		="この不潔なネズミは小型犬ほどの大きさだ。粗い毛皮で覆われ、長くかさぶたのような尻尾を持ち、2つの目が光っている。"
s_rat_x_d		=[[凶暴なネズミは雑食性の腐肉食動物だが、巣や縄張りを守るために攻撃する。巨大ネズミの群れは恐れを知らず、鋭い切歯で噛みつき、噛み砕きながら襲ってくる。ダンジョンや都市の下水道でもよく見られる脅威である。

凶暴なネズミは体長4フィート、体重50ポンド以上に成長する。凶暴なネズミは小型犬ほどの大きさである。粗い毛皮で覆われ、長くかさぶたのような尻尾を持ち、2つの目が光っている。]]

s_cat			="キャット"
s_cheetah		="チーター"
s_leopard		="レパード"
s_lion			="ライオン"
s_lion_x		="ダイア ライオン"
s_tiger			="タイガー"
s_tiger_x		="ダイア タイガー"

s_dog			="ドッグ"
s_dog_ride		="ライディング ドッグ"
