s_wolf			="ウルフ"
s_wolf_c		="この力強い狼は、鋭い黄色い目で獲物を観察し、鋭い白い歯に舌を出す。"
s_wolf_d		=[[狼はその粘り強さと狡猾さで知られる群れのハンターである。単独または群れで放浪する狼は、食物連鎖の頂点に立つ。狼の群れは縄張り意識が強く、狩りの範囲が非常に広いため、広範囲をカバーする。

狼の広い前足には、雪の上を移動するのに役立つように、つま先の間にわずかな網目があり、その毛皮は厚く耐水性があり、色は灰色から茶色、種類によっては黒色まである。前足には臭腺があり、移動の際に地面の目印となり、道案内を助けるだけでなく、群れの仲間に自分の居場所を知らせる。

一般的に、狼の肩の高さは2フィート半から3フィート、体重は45ポンドから150ポンドで、メスの方がやや小さい。

好きな戦術は、敵の正面に対して数人を送り込み、残りの集団は側面や背後から回り込んで攻撃することだ。]]

s_wolf_x		="ダイア ウルフ"
s_wolf_x_c		="この巨大な黒い狼は馬ほどの大きさで、その牙はナイフのように大きく鋭い。"
s_wolf_x_d		=[[通常の狼を巨大化させた凶暴な狼は、狼の最も原始的な姿を表している。これらのクリーチャーは通常の狼と同じ基本的な行動をとるが、はるかに攻撃的である。凶暴な狼は群れで攻撃することを好み、可能な限り敵を取り囲んで側面から攻撃する。凶暴な狼は効率的な群れハンターであり、捕まえられるものは何でも殺す。

凶暴な狼はしばしばジャイアントの狩りのお供や、凶暴な番人として活躍する。凶暴な人型生物や森の番人の中には、訓練された凶暴な狼を馬代わりに使う者もいる。

普通の狼よりも色が濃く、凶暴な狼の被毛は黒や深い斑点のあるグレーに向かう傾向がある。凶暴な狼の成獣は通常、体長約9フィート、体重約800ポンドである。凶暴な狼は馬ほどの大きさで、牙はナイフのように大きく鋭い。]]-- Dire wolves are mottled gray or black, about 9 feet long and weighing some 800 pounds.

