s_dire_animal	="ダイア アニマル"
s_dire_animal_d	=[[ダイアアニマルは普通の動物よりも大きく、タフで、意地悪な動物である。どの種類も野性的、前時代的、あるいは悪魔的な外見を持つ傾向がある。]]

s_dinosaur		="ディノサウルス"
s_dinosaur_d	=[[ディノサウルスにはさまざまな大きさや形がある。大きなディノサウルスは地味な色をしているが、小さなディノサウルスはカラフルな模様をしている。ほとんどのディノサウルスは、小石のような肌の質感を持っている。

ディノサウルスはその大きさと速さをフルに活かします。迅速な肉食ディノサウルスは獲物を待ち伏せし、隠れてカバーの中に潜り込んでから突撃の射程に入り、攻撃に突入します。草食ディノサウルスはしばしば敵を踏み越えて踏み潰します。]]

-- 魔法兽	Magical Beast
s_basilisk		="バシリスク"
s_basilisk_c	="この四角い爬虫類のような怪物は8本の脚を持ち、背中からは骨のような突起が突き出ていて、目は淡い緑色の炎で光っている。"
s_basilisk_d	=[[バジリスクは爬虫類の怪物で、ただ見つめるだけでクリーチャーを石化する。

バジリスクは通常、くすんだ茶色の体に黄色っぽい下腹部を持っている。鼻の上に短く曲がった角がある個体もいる。大人のバジリスクの体長は、尾を除いて約6フィート（約5～7フィート）になる。クリーチャーの体重は約300ポンドである。

バジリスクは視線攻撃に頼り、相手が手の届くところに来たときにのみ噛みつく。足は8本あるが、代謝が遅いため比較的動きが鈍く、不必要にエネルギーを消費することはない。バジリスクと戦わずに逃げる侵入者には、バジリスクは本気で追いかけないであろう。

これらのクリーチャーは、小型の哺乳類、鳥類、爬虫類など、ほとんどの時間を獲物を待ち伏せて過ごす傾向がある。]]
s_basilisk_e	=[[”大蛇の王”と呼ばれるバジリスクは、実は蛇ではなく、意地悪な性格でクリーチャーを石に変える能力を持つ8本足の爬虫類である。コカトリスのように、最初のバジリスクはヘビが産み、雄鶏が孵化させた卵から孵ったという民間伝承があるが、バジリスクの生理学的には、この主張の信憑性はほとんどない。

バジリスクは森林から砂漠まで、ほぼあらゆる陸地環境に生息し、彼らの皮膚は周囲に適応して反映されます。砂漠に住むバジリスクは茶色や褐色の色合いをしている一方、森に住むバジリスクは明るい緑色の場合があります。彼らは洞窟、穴、または他の避難所で巣を作り、これらの巣はしばしば人々や動物の姿をした像が置かれています。それは、バジリスクに遭遇して不運な人々や動物が石化してしまった姿を模しています。

バジリスクは石化したクリーチャーを消化する能力を持っており、その胃酸が石を溶かして栄養分を抽出するが、そのプロセスは遅く非効率的であるため、怠け者で動きが鈍い。その結果、バジリスクは獲物を追いかけたり、視線を避ける者を追いかけたりすることはほとんどなく、隠密と不意打ちの要素を頼りに、安全と食料を確保している。バジリスクは、普段の食事である小型の哺乳類、鳥類、爬虫類を待ち伏せているとき以外は、隠れ家で眠って過ごす。バジリスクを捕獲したり、その近くに宝物を隠したりする勇気のある者は、バジリスクが自然な保護者であり番犬であることに気づく。

大人のバジリスクの体長は13フィートで、その半分が長い尾で占められており、体重は300ポンドもある。鼻に短く曲がった角が生えていたり、頭頂に骨でできた小さな紋章を王冠のように載せている品種もいる。普段は単独で行動し、交尾と産卵のためだけに集まってくるクリーチャーだが、特に危険な地域では、小さな集団が身を守るために団結し、侵入者を集団で攻撃することもある。

理由は不明だが、ウィーゼルやフェレットはバジリスクの凝視に免疫があり、親が狩りをしている間にバジリスクの巣に忍び込み、子供を食べることがある。バジリスクの血は一般的な石を他の物質に変えることができるという伝説もあるが、これは石化したクリーチャーや 身体の一部が魔法で復元されたと目撃者が誤解したケースである可能性が高い。]]

s_liz_l		="ショッカー リザード"
s_liz_l_c	="この犬のような大きさのトカゲは、頭の左右に2本の角があり、鱗には稲妻の火花が散っている。"-- green scales
s_liz_l_d	=[[ショッカーリザードは、下面が淡い灰色か青色で、背中が黒っぽくなる。背中と尾には青黒い模様がある。

ショッカーリザードは肩の高さが約1フィート、体重は約25ポンドである。この犬サイズのクリーチャーには、頭の左右に2本の角があり、雷の火花を散らしたようなウロコがある。

ショッカーリザードは戦闘において電気能力に頼る。トカゲはショックで相手を気絶させた後、あるいはショックがまったく効いていないように見えるときにのみ噛みつく傾向がある。一匹の時は、ショックを与えた後に逃げますが、他のショッカーリザードが近くにいる場合、彼らは全員が仲間の放電を捕え、敵にショックを与えようとします。]]
s_liz_l_e	=[[ショッカーリザードは、体長3フィートの体の裏側は淡い黄色で、他の部分は鮮やかな緑色のうろこをしており、体重は約25ポンドである。ショッカーリザードは集団生活を好む傾向があり、他のトカゲの近くにいると電気的能力がパワーアップする。

ショッカーリザードの群れは通常、水源の近くにいる。群れがある場所に定住すると、トカゲは非常に縄張り意識が強くなり、自分たちの邪魔をするものは何でも攻撃するようになる。一匹でいるショッカーリザードは臆病でためらいがちな生き物だが、何匹も集まると、自分の数倍の大きさのクリーチャーを殺すことができる恐ろしい敵になる。

ショッカーリザードは戦闘においてその電気能力に頼っており、ショックで相手を気絶させた後、あるいはショックがまったく効いていないように見えたときにのみ噛みつく傾向がある。一匹のショッカーリザードはショックを与えると逃げるが、他のショッカーリザードが近くにいると、仲間の放電に照準を合わせ、敵に致命的なショックを与えようとする。

多くの人がショッカーリザードを捕獲して飼いならそうと試みているが、これはしばしば困難で骨の折れる仕事である。単独で飼育されているショッカーリザードは、飼育者がトカゲの相手をするために毛づくろいをしたり、一緒に遊んだりする時間を多く取らない限り、すぐに枯れて死んでしまう傾向がある。ペアや多頭飼育の場合、ショッカーリザードは成長するが、電気に強いため、飼育者自身が電気に強くない場合、管理が難しくなる。]]

-- 虫类		Vermin
s_ant_g		="ジャイアント アント"
s_ant_g_c	="ポニーほどの大きさの細い6本足のアリが、大あごを鳴らして毒針を垂らしながら構えている。"
s_ant_g_d	=[[ジャイアント アントは最も丈夫で適応力のある蟲の一種である。

ジャイアント アントはポニーほどの大きさがある。兵士と労働者ジャイアント アントの体長は約6フィートで、クイーン ジャイアント アントは9フィートにもなる。

ジャイアント アントも通常サイズのアリと同様に勤勉だ。彼らの巣は一般的に数千という単位で構成されているわけではないが、大きくなった巣の大きさはそれを補って余りある。]]

s_spider_mons	="モンストラス スパイダー"
s_spider_mons_c	="人間ほどの大きさのクモが、漏斗状の巣の奥から静かに這い出てくる。"
s_spider_mons_d	=[[すべてのモンストラス スパイダーは攻撃的な捕食者で、毒のある咬み傷で獲物を制圧したり殺したりする。

モンストラス スパイダーには一般的に、狩猟型と巣紡ぎ型の2種類がいる。狩猟型は歩き回り、巣紡ぎ型は通常獲物を捕らえようとする。狩猟型クモは巣を紡いで隠れ家として使うことができるが、巣紡ぎ型のように巣を武器として使うことはできない。]]

-- 植物		Plant

-- 泥形怪物	Ooze

-- 不死生物	Undead
s_skeleton		="スケルトン"
s_skeleton_d	=[[スケルトンとは、死者の骨の造形物であり、邪悪な主人の命令に従う心なき自動人形である。

骸骨は、殺されたときに着ていた衣服や鎧の朽ちた残骸以上のものを身にまとっていることはめったにない。

骸骨は命令されたことしかしない。自ら結論を出すことはできないし、イニシアチブを取ることもない。この制限のため、その指示は常にシンプルでなければならない。

骸骨は破壊されるまで攻撃する。]]

s_zombie	="ゾンビ"
s_zombie_d	=[[ゾンビは暗く不吉な魔法によって生き返った死体だ。

知能がまったくないため、新しく作られたゾンビに与えられる指示は非常にシンプルでなければならない。]]

s_ghost		="ゴースト"
s_ghost_d	=[[ゴーストは、何らかの理由で墓の中で安らかに眠ることができない知的生命体の残骸である。

幽霊は生前の肉体の姿によく似ているが、霊的な姿は多少変化している場合もある。]]

s_ghoul		="グール"
s_ghoul_c	="この人型生物のクリーチャーには長く鋭い歯があり、青白い肉が飢えた体躯にぴったりと張り付いている。"
s_ghoul_d	=[[グールは墓場に出没し、死体を食べるアンデッドである。伝説によれば、最初のグールは、不自然な飢えによって死から引きずり戻された人肉食のヒューマンか、あるいは生前に親族の腐敗した遺体を食べて腐敗病で死んだ（そして生まれ変わった）ヒューマンであるとされているが、このアンデッド死体漁りの真の出所は不明である。

グールは文明の端（墓地やその近く、あるいは都市の下水道）に潜んでいる。腐敗した死体を好み、味を良くするために犠牲者をしばらく埋葬することが多いが、空腹であれば新鮮な殺生物を食べる。ほとんどの地上のグールは原始的な生活をしているが、噂では地下深くに古代の残酷な神々を崇拝する司祭や飢餓を司る奇妙なデーモンロードに率いられたグールの都市があるという。これらの "文明化された "グールも、その食習慣においておぞましくはない。実際、整然と並べられたグールの宴席という概念は、おそらく棺桶から新鮮な食事を取るという概念よりももっとおぞましい。]]

s_lich		="リッチ"
s_lich_d	=[[リッチとはアンデッドの術師のことで、通常はウィザードかソーサラーだが、クレリックや他の術師の場合もあり、魔力を使って不自然に寿命を延ばしている。

リッチは痩せこけた骸骨のような人型生物で、枯れ果てた肉が恐ろしく目立つ骨にぴったりと張り付いている。その目はとうの昔に腐敗のために失われているが、空っぽの眼窩の中で明るい深紅の光がピンポイントで燃えている。

リッチは共通語と、生前知っていたその他の言語を話す。

<b>リッチのキャラクター</b>
リッチになる過程は言いようのない邪悪なものであり、意思のあるキャラクターのみが引き受けることができる。リッチは生前のクラス能力をすべて保持している。

<b>リッチのフィラクタリー</b>
リッチになるために不可欠なのは、キャラクターが生命力を蓄える魔法のフィラクタリーを作ることである。リッチはそれぞれ自分のフィラクタリーを作らなければならない。

最も一般的なフィラクタリーは、魔法の言葉が書き込まれた羊皮紙が封入された小さな金属製の箱である。指輪やお守りなど、他の形のフィラクタリーも存在する。

原則として、リッチを確実に排除する唯一の方法はそのフィラクタリーを破壊することである。フィラクタリーを探し出して破壊しない限り、リッチは見かけ上死んでから1d10日後に再び復活する。]]

s_vampire	="ヴァンパイア"
s_vampire_d	=[[吸血鬼は生前と同じように見えるが、その特徴はしばしば硬化して凶暴になり、オオカミのような捕食者のような顔つきになる。

リッチと同様、彼らはしばしば華美と退廃を受け入れ、貴族を装うこともある。

ヒューマンのような外見をしているが、吸血鬼は影を作らず、鏡にも映らないので、すぐに見分けがつく。

吸血鬼は生前知っていた言語を話す。]]
s_vampire_e	=[[<b>ヴァンパイアの弱点</b>
吸血鬼はそのパワーの割に、いくつかの弱点を持っている。

<b>ヴァンパイアを追い払う:</b>吸血鬼はニンニクの強烈な臭いに耐えられず、ニンニクのある場所には立ち入らない。同様に、鏡や強く示された聖なるシンボルにも反発する。これらのものは吸血鬼に害を与えるわけではなく、単に吸血鬼を寄せ付けないだけである。反動を受けた吸血鬼は、鏡や聖なるシンボルを持つクリーチャーから少なくとも5フィート離れなければならず、その遭遇の間、そのアイテムを持つクリーチャーに触れたり近接攻撃を行なったりすることはできない。

吸血鬼はまた、流水を渡ることができないが、棺桶の中で休んでいるときや船に乗っているときは流水を渡ることができる。

彼らは、権限を持つ誰かに招かれない限り、家やその他の建物に入ることはまったくできない。公共の場には自由に立ち入ることができる。

<b>ヴァンパイアを殺す:</b>ヴァンパイアのヒットポイント(HP)を0以下にすると無力化されるが、破壊されるわけではない。しかし、ある種の攻撃はヴァンパイアを殺すことができる。

吸血鬼は直射日光を浴びると衰弱する： その吸血鬼は移動アクションか攻撃アクションを1回しかとれず、脱出できなければ次のラウンドに完全に破壊される。

同様に、吸血鬼を流水に浸すと、3ラウンド目の浸水終了時に破壊されるまで、各ラウンドごとにヒットポイント(HP)の3分の1が奪われる。

木の杭を吸血鬼の心臓に打ち込むと、怪物は即座に殺される。しかし、体を破壊しない限り、杭を抜けば生き返る。

よく使われる戦術は、クリーチャーの頭を切り落とし、その口に聖なるウエハース（またはそれに相当するもの）を詰めることだ。]]

s_vampire_spawn		="ヴァンパイア スポーン"
s_vampire_spawn_d	=[[ヴァンパイア スポーンは、吸血鬼が人間を殺したときに生まれるアンデッドクリーチャーである。生みの親と同様に、子種も棺と墓の土に縛られたままである。ヴァンパイア スポーンは生前とほぼ同じ姿をしているが、その特徴はしばしば捕食者のような顔つきで硬化している。

ヴァンパイア スポーンは共通語を話す。

ヴァンパイア スポーンは人間と交戦する際に人間離れした力を発揮し、強力な打撃で敵を打ちのめし、岩や壁にぶつける。また、気体形態と飛行能力を使い、相手の最も脆弱な場所を攻撃する。

ヴァンパイア スポーンは、吸血鬼を撃退または殺害するすべての攻撃や効果に弱い。]]

-- 构装体	Construct
s_golem		="ゴーレム"
s_golem_d	=[[ゴーレムは魔法で作られた、大きな力を持つ自動人形である。ゴーレムを作るには、強大な魔法と元素の力が必要となる。

ゴーレムの原動力は大地の次元の精霊である。ゴーレムを作成する過程で、不本意な精神は人工の肉体に縛り付けられ、ゴーレムの作成者の意志に従わされる。

ゴーレムは戦闘において粘り強く、また驚異的な強さを持つ。ゴーレムはほとんどの魔法や超自然的効果に対する免疫を持っている。心が無いため、創造主からの命令なしには何もしない。彼らは明確に指示に従い、戦略や戦術をとることはできない。戦闘においては無感情であり、挑発することもできない。]]
s_golem_e	=[[ゴーレムの創造者は、ゴーレムが60フィート以内にいて創造者を見聞きできるならば、ゴーレムに命令できる。命令されていない場合、ゴーレムは通常、最後の命令に可能な限り従うが、攻撃された場合は攻撃を返す。

作成者はゴーレムに簡単な命令を与えて、不在時の行動を支配することができる。ゴーレムの生みの親はゴーレムに他の人（その人はゴーレムを他の人の支配下に置くかもしれない、など）の命令に従うように命じることができるが、ゴーレムの生みの親はゴーレムに自分だけに従うように命じることで、いつでも自分の創造物に対する支配を再開することができる。]]

s_inevitable	="イネヴァタブル"
s_inevitable_d	=[[イネヴァタブルとは、宇宙の自然法則を強制することだけを目的とした構築物である。

各タイプのイネヴァタブルは、特定の種類の違反を見つけ、罰するように設計されており、基本原則に違反した個人やグループを追い詰める。必然性が生まれると、最初の使命を受け、違反者を見つけて適切な罰を与える。その刑は通常死刑であるが、一部の不可避的存在は、その代わりに悪事を働いた者への賠償を主張し、その遵守を確実にするためにギアスや正義の印を用いる。

観察モードに入っている間、イネヴァタブルは人ごみの中で目立つ傾向があるが、注目されていることには気づいていないようだ。その姿はさまざまだが、すべての必然性は金と銀の時計仕掛けのクリーチャーで、生身のクリーチャーなら筋肉があるはずの場所に歯車とピストンがある。彼らの目は金色の輝きを放っている。

ほとんどの構造体とは異なり、イネヴァタブルには知力値があり、思考し、学習し、記憶することができる。

セレスチャルは奈落語(アビサル)、天上語(セレスチャル)、地獄語(インファーナル)、そして最初の目標の母国語を話す。]]
s_inevitable_e	=[[イネヴァタブルは、最初の一歩からして、完全に目標に集中します。追跡が冷え切っていたり、任務が絶望的であっても、努力を続けます。イネヴァタブルは獲物を追い求める際には一心不乱ですが、無実の者には手を出さないように命令されています。ただし、その獲物の共犯者は公平なターゲットとされます。このため、彼らのプログラム内で時々葛藤が生じることがあります。

イネヴァタブルは、自らの存在が脅かされるまで、割り当てられた違反者に完全に焦点を合わせ、他の戦闘参加者を完全に無視します。イネヴァタブルは進行を妨げる者に対して攻撃を行うかもしれませんが、それが自らの獲物に再び戦闘を開始できる地点を越えることはありません。イネヴァタブルは自己防衛を非常に重視しており、その存在を致命的と認識した者が攻撃すれば、同じく致命的な力で応戦します。

イネヴァタブルは任務を完遂するためなら喜んで自らを犠牲にするが、自殺願望はない。敗北が目前に迫ると、撤退し、互角に戦える方法を模索する。決断力があり忍耐強い敵である。任務達成に役立つなら他者と同盟を結ぶが、同盟者を長く維持するのは難しい。]]

-- 其他		Others
s_lycanthrope	="ライカンスロープ"
s_lycanthrope_d	=[[ライカンスロープとは、動物に変身できる人型生物やジャイアントのことである。

自然の姿では、ライカンスロープは他の種族と同じように見えるが、自然のライカンスロープや長い間苦しんできたライカンスロープは、動物の姿を思わせる特徴を持つか、身につける傾向がある。

動物の姿のライカンスロープは、通常の動物を強力にしたような姿をしているが、よく見るとその目（暗闇で赤く光ることが多い）には、不自然な知性の輝きがかすかに見える。

ライカンスロープ症は病気のように広がることがある。ライカンスロープが普通の人型生物やジャイアントとして生まれ、ライカンスロープに傷つけられた後にライカンスロープに感染することもある。そのようなクリーチャーは罹患ライカンスロープと呼ばれる。それ以外のライカンスロープは生まれながらにしてライカンスロープであり、ナチュラルライカンスロープと呼ばれる。

一般的なライカンスロープには、ワーウルフ、ワーラット、ワーベア、ワータイガー、ワーボアがいる。]]
s_lycanthrope_e	=[[人型生物（またはジャイアント）の姿のライカンスロープは、他の同類が好む戦術や武器を用いるが、やや攻撃的な傾向がある。ライカンスロープは嗅覚や 低照度下での視覚を含む獣型の感覚を持ち、獣型の動物に対する深い共感（およびコミュニケーション能力）を持つ。戦闘でダメージを受けたライカンスロープは怒りに圧倒され、無意識のうちに動物の姿に変わってしまうことがある。

動物の姿をしたライカンスロープは、その姿に似た動物のように戦います。ただし、その噛みつきにはライカンスロープの病気を伴います。ライカンスロープは、非常に巧妙で強く、銀製の武器にしか打ち破られないダメージ減少能力を持っています。

ナチュラルライカンスロープ（またはその病気を自覚した罹患者）は、ハイブリッド形態を取ることができます。これは、その人型と動物型の特徴が混在した形態です。ハイブリッドには手があり、武器を使用することができますが、同時に歯と爪で攻撃することもできます。ハイブリッドは噛みつきによってライカンスロープ病を広めることができ、動物形態と同じダメージ減少能力を持っています。]]


s_u_tps			= "クリーチャーの種類"
s_u_tps_d		= [[各クリーチャーは、その能力を大まかに定義する1つのタイプを持つ。クリーチャーによっては1つ以上のサブタイプを持つものもある。

クリーチャーは、その違いを説明する特別な能力や性質がなければ、そのサブタイプのルールに違反することはできない--テンプレートはしばしば、クリーチャーのタイプを大きく変えることができる。


クリーチャーの種類の各説明は、以下に概説するように、同じ一般的な形式で構成されている。


<b>ヒットダイス(HD)（またはヒットダイ、HD）</b>
単数形では、ヒットポイント(HP)を生み出すために振るダイスのことである。耐久力値などの要素もあるが、ヒットダイス(HD)はクリーチャーのヒットポイント(HP)を測る重要な参考として使われる。

複数形では、相対的なパワーの尺度であり、キャラクターレベルと同義である。ただし、クラスを持たないクリーチャー（あるいは特定の複雑なクリーチャー）は、この尺度をヒットダイス(HD)の数に置き換える必要がある。


<b>基本攻撃ボーナス（BAB）</b>
クリーチャーの種類に基づき、クリーチャーの基本攻撃ボーナスはそのヒットダイス(HD)の合計に等しくなる（ファイターの場合）、あるいは3/4に等しくなる（クレリックの場合）、あるいは1/2に等しくなる（ウィザードの場合）。


<b>グッドセーヴ</b>
クリーチャーの種類によって得意なセーヴは異なる。1つ以上のセーヴが他のものより高い。しかし、すべてのセーヴを得意とするクリーチャータイプも少数存在する。


<b>ヒットダイス(HD)あたりの技能ポイント</b>
クリーチャーはヒットダイス(HD)を得るごとに、x＋知力修正値（最低1）に等しい技能ポイントを得、最初のヒットダイス(HD)の技能ポイントは4倍になる。

しかし前提として、クリーチャーは知力値を持っており、そうでなければヒットダイス(HD)あたり0点の技能ポイントを得る。とあるクリーチャーは心が無く、技能ポイントも特技も得られない。


<c=twa>(完全を期すため、ゲームにまだ登場していないものも含め、ルールに登場するクリーチャータイプはすべて以下に参考として示した)。</c>]]


s_u_sub_tps		= "クリーチャーのサブタイプ"
s_u_sub_tps_d	= [[クリーチャーの中には1つ以上のサブタイプを持つものがある。サブタイプはクリーチャーに追加の能力や性質を加える。

<c=twa>(完全を期すため、まだゲームに登場していないものも含めて、ルールにあるクリーチャーのサブタイプをすべて以下に参考として示す)。</c>]]


s_ut_hum_hd		= "人型生物のヒットダイス(HD)"
s_ut_hum_hd_d	= [[ヒットダイス(HD)が1の人型生物は、その人型生物のヒットダイス(HD)の特徴を、プレイヤーキャラクターまたはNPCのクラスの特徴と交換する。

この種の人型生物は1レベルのウォーリアーとして登場するが、これは平均的な戦闘能力と貧弱なセーヴィングスローを持つことを意味する。

ヒットダイス(HD)が1以上の人型生物は、人型生物タイプの特徴を活かす唯一の人型生物である。]]


-- z_u_tp
u_tps_text={

[uc_hum]={n="人型生物"	,d=[[人型生物は通常、2本の腕、2本の脚、1つの頭、あるいはヒューマンのような胴体、腕、頭を持っている。

人型生物は超自然的な能力や特別な能力をほとんど、あるいは全く持っていないが、そのほとんどが言葉を話すことができ、通常は発達した社会を持っている。

通常は小型か中型である。すべての人型生物クリーチャーはサブタイプも持つ。

<b>特徴:</b>
— ヒットダイス(HD): d8、またはキャラクタークラスによる。
— 基本攻撃ボーナス:総ヒットダイス(HD)の3/4。
— グッドセーヴ:反応（通常;人型生物のグッドセーヴは異なる場合がある）。
— ヒットダイス(HD)あたりの技能ポイント：2 + 知力修正値、またはキャラクタークラスによる。

<b>特性:</b>
— すべての単純武器に熟練しているか、あるいはキャラクターのクラスによって熟練している。
— 鎧を着用している場合、そのタイプの鎧と、よりライトタイプの鎧すべて、および盾に習熟する。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_gnt]={n="ジャイアント"	,d=[[ジャイアントとは大きな力を持つ人型生物のクリーチャーで、通常は少なくとも大型のサイズである。

ジャイアントはすべてジャイアント語を話す。知力値が10以上の者は共通語も話す。

<b>特徴:</b>
— ヒットダイス(HD)：d8
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ：頑健。
— ヒットダイス(HD)あたりの技能ポイント：2＋知力修正値。

<b>特性:</b>
— 低照度視力。
— 単純武器、軍用武器、肉体武器のすべてに熟練している。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_fey]={n="フェイ"	,d=[[フェイとは、超自然的な能力を持ち、自然や他の力、場所とのつながりを持つクリーチャーのことだ。フェイは通常人型生物の形をしている。

<b>特徴:</b>
— ヒットダイス(HD):d6。
— 基本攻撃ボーナス:総ヒットダイス(HD)の1/2。
— グッドセーヴ:反応と意志。
— ヒットダイス(HD)あたりの技能ポイント：6＋知力修正値。

<b>特性:</b>
— 低照度視力。
— すべての単純武器と、任意の使用武器に熟練しています。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_hmm]={n="人怪"	,d=[[人怪は人型生物に似ているが、怪物的あるいは動物的特徴を持つ。彼らはしばしば魔法的な能力も持っている。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス: 総ヒットダイス(HD)。
— グッドセーヴ:反応と意志。
— ヒットダイス(HD)あたりの技能ポイント:2＋知力修正値。

<b>特性:</b>
— 夜目60フィート。
— すべての単純武器と、任意の使用武器に熟練しています。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_out]={n="来訪者"	,d=[[来訪者は少なくとも部分的に、物質界以外の何らかの面のエッセンス（物質である必要はない）で構成されている。

クリーチャーの中には、最初は他のタイプとしてスタートし、より高い（あるいはより低い）霊的存在の状態に達したときに来訪者になるものもいる。

典型的な来訪者には、エンジェル、デビル、ジニーなどがいる。プラネットタッチは典型的な生粋の来訪者である。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス：総ヒットダイス(HD)。
— グッドセーヴ:頑健、反応、意志。
— ヒットダイス(HD)あたりの技能ポイント:8+知力修正値。

<b>特性:</b>
— 夜目60フィート。
— 他のクリーチャーと違い、来訪者は魂と肉体が一体となっている。来訪者が殺された時、魂は解放されない。魂を肉体に戻す通常の呪文は、非ネイティブの来訪者には効かない。魂を元に戻すには、別の強力な魔法効果を必要とする。
— 単純武器、軍用武器、あらゆる武器を使いこなす。
— 鎧を着用している場合、そのタイプの鎧と、より軽い鎧、さらに盾に習熟する。
— 呼吸は必要だが、食べたり眠ったりする必要はない（望めばできるが）。来訪者は食べ、眠り、呼吸をする。]]},


[uc_elm]={n="エレメンタル"	,d=[[エレメンタルとは、空気、土、火、水という古典的な4元素のうちの1つからなる存在である。エレメンタルは存在を構成する元素の化身である。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ:頑健（地、水）または反応（空、火）。
— ヒットダイス(HD)あたりの技能ポイント:2＋知力修正値。

<b>特性:</b>
— 夜目60フィート。
— 毒、睡眠効果、麻痺、気絶に対する免疫がある。
— クリティカルや側面攻撃は受けない。
— 他のほとんどのクリーチャーとは異なり、エレメンタルは二重性を持たない。エレメンタルが殺されたとき、魂は解放されない。魂を肉体に戻す呪文はエレメンタルには効かない。エレメンタルを生き返らせるには、もっと強力な別の魔法効果を必要とする。
— 肉体武器にのみ習熟しており、一般的に人型の形態の場合は、すべての単純武器およびどのような任意の使用武器にも習熟しています。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食べてはいけない、寝てはいけない、呼吸してはいけない。]]},


[uc_abr]={n="異形"	,d=[[異形とは、奇妙な解剖学的構造、奇妙な能力、異質な考え方、あるいはその3つの組み合わせのことである。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス:総ヒットダイス(HD)の3/4。
— グッドセーヴ:意志。
— ヒットダイス(HD)あたりの技能ポイント:2+知力修正値。

<b>特性:</b>
— 夜目60フィート。
— 肉体武器に習熟する。一般的な人型生物であれば、すべての単純武器と任意の使用武器に習熟する。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_dgn]={n="ドラゴン"	,d=[[ドラゴンは爬虫類のような生き物で、通常は翼を持ち、魔法や特殊能力を持つ。

<b>特徴:</b>
— ヒットダイス(HD):d12。
— 基本攻撃ボーナス：総ヒットダイス(HD)。
— グッドセーヴ:頑健、反応、意志。
— ヒットダイス(HD)あたりの技能ポイント:6+知力修正値。

<b>特性:</b>
— 夜目力60フィート、低照度視力。
— 魔法による睡眠効果と麻痺効果に免疫がある。
— 肉体武器にのみ習熟しています。ただし、人型生物の形態を持つ場合（または人型生物の形態を取ることができる場合）、すべての単純武器およびどのような任意の使用武器にも習熟しています。
— 鎧に熟練していません。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_ani]={n="動物"	,d=[[動物とは、生きている人型生物以外のクリーチャーのことで、通常は脊椎動物であり、魔法的な能力を持たず、生まれつき言語や文化を持たない。

これらのクリーチャーは通常、本能のままに行動し、食物や繁殖といった単純な欲求に突き動かされている。ほとんどの動物は、捕食者であっても、自分や自分の子供が脅かされない限り攻撃しない。

動物は細かな推理はできないが、動物使いの技能を使えば、動物を手なずけて特定の芸を教えることは可能である。

草食動物のなかには、通常攻撃に肉体武器を使用しないものがいる。そのため、肉体武器は二次攻撃として扱われる。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ:頑健と反応（ダイアアニマルは3つすべてのセーヴを持つ;特定の動物は異なるセーヴを持つ）。
— ヒットダイス(HD)あたりの技能ポイント:2＋知力修正値。

<b>特性:</b>
— 知力値が1か2（知力値が3以上のクリーチャーは動物になれない）。
— 低照度視力。
— 属性 常に中立である。動物は人間の道徳観には支配されない。
— 財宝:通常、財宝は持っていない。持っている場合、その財宝はモンスターが殺したクリーチャーがかつて所有していたものである。
— 肉体武器にのみ習熟しています。非戦闘的な草食動物は、肉体武器を副次的な攻撃として使用します。このような攻撃は、クリーチャーの攻撃ロールに対して-5のペナルティが適用され、動物は攻撃のダメージ調整として自身の筋力修正値の1/2しか受けません。
— 戦闘の訓練を受けていない限り、鎧は着用しない。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_anm]={n="魔獣"	,d=[[魔獣は動物に似ているが、知力値が2より高くなることがある。魔獣は通常、超自然的な能力や並外れた能力を持つが、時には単に奇妙な外見や習性を持つこともある。

<b>特徴:</b>
— ヒットダイス(HD):d10。
— 基本攻撃ボーナス：総ヒットダイス(HD)。
— グッドセーヴ:頑健と反応。
— ヒットダイス(HD)あたりの技能ポイント:2＋知力修正値。

<b>特性:</b>
— 夜目60フィート、低照度視力。
— 肉体武器にのみ熟練しています。
— 鎧に熟練していません。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_bug]={n="蟲"	,d=[[このタイプには、昆虫、クモ類、その他の節足動物、ミミズ、および同様の無脊椎動物が含まれる。

これらのクリーチャーは本能のままに行動し、食物や繁殖といった単純な欲求に突き動かされている。特記されている場合を除き、害獣が攻撃するのは空腹時か脅威を感じたときだけである。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス:総ヒットダイス(HD)の3/4。
— グッドセーヴ:頑健。
— ヒットダイス(HD)あたりの技能ポイント：2＋知力修正値。ほとんどの害獣は心が無く、技能ポイントも特技も得られない。

<b>特性:</b>
— 心を持たない: 知力値がなく、すべての精神に作用する効果に免疫がある。
— 夜目60フィート。
— 属性 常に中立である。蟲は人間の道徳観には支配されない。
— 財宝：通常、財宝は持っていない。持っている場合、その財宝はモンスターが殺したクリーチャーがかつて所有していたものである。
— 肉体武器にのみ熟練している。
— 鎧に熟練していません。
— 食べて、寝て、呼吸する必要がある。]]},


[uc_plt]={n="植物"	,d=[[このタイプは植物クリーチャーを構成する。庭や野原に生えているような普通の植物は判断力と魅力の値を欠いており、たとえ生きていてもクリーチャーではなく物体であることに注意すること。

<b>特徴:</b>
— ヒットダイス(HD):d8。
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ:頑健。
— ヒットダイス(HD)あたりの技能ポイント:2+知力修正値。一部の植物クリーチャーは心を持たず、技能ポイントも特技も得られない。

<b>特性:</b>
— 低照度視力。
— すべての精神に影響を及ぼす効果に免疫がある。
— 毒、睡眠効果、麻痺、変身、および気絶効果への免疫。
— クリティカルヒットの対象にはならない。
— 肉体武器にのみ熟練している。
— 鎧に熟練していません。
— 食事と呼吸は必要だが、眠ることはない。]]},


[uc_ooz]={n="ウーズ"	,d=[[ウーズは食べるためだけに生きる無定形または変幻自在のクリーチャーで、通常は心が無い。

世界中の地下に生息し、洞窟、遺跡、ダンジョンなどを生死にかかわらず有機物を求めて探し回る。

ウーズは遭遇したクリーチャーに攻撃します。彼らは疑似足や単に自らの体で相手を包み込み、その体から分泌される酸によって獲物を捕まえたり消化したりします。

<b>特徴:</b>
— ヒットダイス(HD):d10。
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ: なし。
— ヒットダイス(HD)あたりの技能ポイント:2+知力修正値。ほとんどのウーズは心が無く、技能ポイントも特技も得られない。

<b>特性:</b>
— 心を持たない:知力値がなく、すべての精神に作用する効果に免疫がある。
— 盲目（ただし、盲視特性を持ちます）、視線攻撃、視覚効果、幻影、および視覚に依存する他の攻撃形態に対する免疫を持つ。
— ブラインドサイト（優れた):ウーズの全身は、60フィート以内の匂いや振動によって獲物を感知できる原始的な感覚器官です。
— 毒、睡眠、麻痺、変身、魅了に対する免疫がある。
— 一部のウーズは物体に酸ダメージを与える能力を持つ。その場合、ダメージ量は接触1ラウンドにつき10+ウーズのヒットダイス(HD)の1/2+ウーズの耐久力修正値に等しい。
— クリティカルや側面攻撃は受けない。
— 肉体武器にのみ熟練している。
— 鎧に熟練していません。
— 食事と呼吸は必要だが、眠る必要はない。]]},


[uc_und]={n="アンデッド"	,d=[[アンデッドとは、霊的あるいは超自然的な力によって生かされている、かつて生きていたクリーチャーのことである。

<b>特徴:</b>
— ヒットダイス(HD):d12。
— 基本攻撃ボーナス：総ヒットダイス(HD)の1/2。
— グッドセーヴ:意志。
— ヒットダイス(HD)あたりの技能ポイント：4+知力修正値。多くのアンデッドは心が無く、技能ポイントも特技も得られない。

<b>特性:</b>
— 耐久力値がない。
— 夜目60フィート。
— すべての精神に影響を及ぼす効果に免疫がある。
— 毒、睡眠、麻痺、気絶、病気、死の効果に対する免疫がある。
— 頑健セーヴを必要とするあらゆる効果に対する免疫（その効果が物体にも作用するか、無害である場合を除く）。
— クリティカルヒット、非致死ダメージ、能力吸収、生命力吸収の影響を受けない。身体能力値（筋力、敏捷力、耐久力）に対するダメージや疲労、消耗の効果を受けない。
— 知力値がない場合、自力でダメージを回復することはできない。負のエネルギーはアンデッドを癒すことができる。ファストヒーリングの特殊能力はクリーチャーの知力値に関係なく機能する。
— レイズデッドやそれに類する呪文や能力の影響を受けない。
— 集中判定に魅力修正を使用する。
— 肉体武器、単純武器、任意の使用武器に精通している。
— 鎧を着用している場合、そのタイプの鎧と、より軽いタイプの鎧、さらに盾に習熟する。
— 食事を摂らず、睡眠を取らず、呼吸をしない。]]},


[uc_cst]={n="人造"	,d=[[人造は、動く物体または人工的に構築された生物です。

<b>特徴:</b>
— ヒットダイス(HD):d10。
— 基本攻撃ボーナス：総ヒットダイス(HD)の3/4。
— グッドセーヴ: なし。
— ヒットダイス(HD)あたりの技能ポイント:2+知力修正値。ほとんどの人造は心が無く、技能ポイントも特技も得られない。

<b>特性:</b>
— 耐久力値がない。
— 夜目60フィート、低照度視力。
— すべての精神に影響を及ぼす効果に免疫がある。
— 毒、睡眠、麻痺、気絶、病気、死の効果、ネクロマンシーの効果に対する免疫がある。
— 頑健によるセーヴを必要とするあらゆる効果に対する免疫（その効果が物体にも作用するか、無害である場合を除く）。
— クリティカルヒット、非致死ダメージ、能力ダメージ、能力吸収、疲労、消耗、生命力吸収の影響を受けない。
— 自力でダメージを回復することはできないが、ある種の効果に晒すことで修復できることが多い。尚ファストヒーリングの特殊能力を持つ人造は、その能力の恩恵を受ける。
— 生きていないのだから、人造をよみがえらせたり、復活させたりすることはできない。
— その体は生きていない物質の塊であるため、人造を破壊することは難しい。以下の表に示すように、サイズに応じてボーナスヒットポイント(HP)を得る。
	人造サイズ	ボーナスヒットポイント(HP)
	微細			—
	矮小			—
	極小			—
	小型			10
	中型			20
	大型			30
	巨大			40
	特大			60
	極大			80
— 肉体武器にのみ熟練しています。ただし、一般的に人型の形態を持つ場合、任意の使用武器にも習熟しています。
— 鎧に熟練していません。
— 食事、睡眠、呼吸を行いません。]]},
}

-- z_u_sub_tp
u_sub_tps_text={
[ust_hum]={n="ヒューマン"		,d="このサブタイプはヒューマンおよびヒューマンに関連するクリーチャーに適用される。"},
[ust_elf]={n="エルフ"			,d="このサブタイプはエルフと、ハーフエルフのようなエルフに関係するクリーチャーに適用される。\n\nエルフのサブタイプを持つクリーチャーは低照度視力を持つ。"},
[ust_dwf]={n="ドワーフ"		,d="このサブタイプはドワーフおよびドワーフに関係するクリーチャーに適用される。\n\nドワーフのサブタイプを持つクリーチャーは60フィートの夜目を持つ。"},
[ust_gnm]={n="ノーム"		,d="このサブタイプはノームとノームに関連するクリーチャーに適用される。\n\nノームのサブタイプを持つクリーチャーは低照度視力を持つ。"},
[ust_hfl]={n="ハーフリング"		,d="このサブタイプはハーフリングおよびハーフリングに関連するクリーチャーに適用される。"},
[ust_orc]={n="オーク"			,d="このサブタイプはオークと、ハーフオークなどオークに関連するクリーチャーに適用される。\n\nオークのサブタイプを持つクリーチャーは60フィートの夜目と光感受性を持つ（ハーフオークは光感受性を持たない）。"},
[ust_gob]={n=s_goblinoid	,d=s_goblinoid_d},
[ust_gnl]={n=s_gnoll		,d=s_gnoll_d	},
[ust_cat]={n=s_catfolk		,d=s_catfolk_d	},
[ust_rep]={n="爬虫類"	,d="これらのクリーチャーは鱗を持ち、通常は体温が低いです。\n\n爬虫類のサブタイプは一連の人型生物種族を表現するために使われるのであって、本当に爬虫類であるすべての動物やモンスターを表現するわけではない。"},
[ust_aqu]={n="水棲"		,d="これらのクリーチャーは常に泳ぐ速度を持っているため、水泳判定を行わなくても水中を移動できる。\n\n水棲クリーチャーは水中で呼吸できる。水陸両用の特別な性質を持っていない限り、空気も吸えない。"},
[ust_aug]={n="変性種"	,d="クリーチャーは、その元のタイプを変える何かが起こるたびにこのサブタイプを受ける。\n\nこのサブタイプを生まれつき持つクリーチャーもいれば、後天的にこのサブタイプを持つクリーチャーもいる。\n\n拡張サブタイプは常にクリーチャーの元のタイプと対になる。拡張サブタイプを持つクリーチャーは通常、現在のタイプの特性を持ち、元のタイプの特徴を持つ。"},
[ust_fir]={n="火"			,d="火サブタイプを持つクリーチャーは火に対する免疫を持っている。これは冷気に対する脆弱性を持ち、防御セーヴィングスローが許可されているかどうかや、防御が成功したか失敗したかにかかわらず、冷気から通常の半分のダメージを受けることを意味する。"},
[ust_col]={n="冷気"			,d="冷気サブタイプを持つクリーチャーは冷気に対する免疫を持っている。火に対する脆弱性を持ち、これはセーヴィングスローが許可されているかどうか、セーヴィングが成功か失敗かにかかわらず、火から通常の半分のダメージを受けることを意味する。"},
[ust_air]={n="風"			,d="このサブタイプは通常、空気のエレメンタル次元につながりを持つエレメンタルや来訪者に使われる。\n\n空気のクリーチャーは常に飛行速度を持っており、通常は完璧な操縦性を持っている。"},
[ust_wtr]={n="水"		,d="このサブタイプは通常、水のエレメンタル次元とのつながりを持つエレメンタルや来訪者に用いられる。\n\n水クリーチャーは常に泳ぐ速度を持っており、水泳判定を行わなくても水中を移動できる。\n\n水クリーチャーは水中で呼吸ができ、通常は空気も吸える。"},
[ust_eth]={n="地"		,d="このサブタイプは通常、大地のエレメンタル次元につながりを持つエレメンタルや来訪者に用いられる。\n\n土のクリーチャーは通常、穴を掘る速度を持っており、ほとんどの土のクリーチャーは固い岩を掘ることができる。"},
[ust_goo]={n="善"			,d="通常、善属性の外層次元出身の来訪者だけに適用されるサブタイプである。\n\nこのサブタイプを持つクリーチャーのほとんどは属性も善であるが、属性が変化してもサブタイプは維持される。\n\n属性に依存する効果はすべて、このサブタイプを持つクリーチャーに、そのクリーチャーの実際の属性が何であろうと、そのクリーチャーがよい属性を持っているかのように影響する。クリーチャーは実際の属性に応じた効果も受ける。\n\n善サブタイプを持つクリーチャーは、その肉体武器とそのクリーチャーが振るう武器が善属性であるかのようにダメージ減少を克服する。"},
[ust_evl]={n="悪"			,d="通常、悪な指向を持つ外層次元出身の来訪者だけに適用されるサブタイプである。\n\nこのサブタイプを持つクリーチャーのほとんどは属性も悪であるが、属性が変化してもサブタイプは保持される。\n\n属性に依存する効果はすべて、このサブタイプを持つクリーチャーに、そのクリーチャーの実際の属性が何であろうと、そのクリーチャーが悪の属性を持っているかのように影響する。クリーチャーは実際の属性に応じた効果も受ける。\n\n悪のサブタイプを持つクリーチャーは、その肉体武器とそのクリーチャーが振るう武器が悪属性のであるかのようにダメージ減少を克服する。\n\n悪の来訪者はフィーンドとも呼ばれる。"},
[ust_law]={n="秩序"		,d="通常、秩序属性の外層次元出身の来訪者だけに適用されるサブタイプである。\n\nこのサブタイプを持つクリーチャーのほとんどは秩序の属性を持つが、属性が変化してもサブタイプは維持される。\n\n属性に依存する効果はすべて、このサブタイプを持つクリーチャーに、そのクリーチャーの実際の属性が何であろうと、そのクリーチャーが秩序の属性を持っているかのように影響する。クリーチャーは実際の属性に応じた効果も受ける。\n\n秩序サブタイプを持つクリーチャーは、その肉体武器とそのクリーチャーが振るう武器が秩序属性であるかのようにダメージ減少を克服する。"},
[ust_cho]={n="混沌"		,d="通常、混沌属性の外層次元出身の来訪者のみに適用されるサブタイプである。このサブタイプを持つクリーチャーのほとんどは混沌の属性を持つが、属性が変化してもサブタイプは維持される。\n\n属性に依存する効果はすべて、このサブタイプを持つクリーチャーに、そのクリーチャーの実際の属性が何であろうと、そのクリーチャーが混沌の属性を持っているかのように影響する。クリーチャーは実際の属性に応じた効果も受ける。\n\n混沌のサブタイプを持つクリーチャーは、その肉体武器とそのクリーチャーが振るう武器が混沌属性であるかのようにダメージ減少を克服する。"},
[ust_nat]={n="原住"		,d="来訪者のみに適用されるサブタイプである。これらのクリーチャーは死すべき先祖を持つか、物質界と強いつながりを持ち、他の生物と同様に蘇生、転生、復活することができる。\n\nこのサブタイプを持つクリーチャーは物質界出身である（これがサブタイプの名前の由来である）。\n\n真の来訪者とは異なり、ネイティブの来訪者には食事と睡眠が必要だ。"},
[ust_ext]={n="他次元界"	,d="クリーチャーが、そのクリーチャーが生まれ育った次元以外の次元にいるときに適用されるサブタイプである。平面を移動するクリーチャーは、次元から次元へと移動する際にこのサブタイプを得たり失ったりすることができる。\n\n関連する記述は、クリーチャーとの遭遇が物質界で行われることを前提としており、物質界をホーム次元としていないクリーチャーはすべて次元外サブタイプを持つ（ただし、ホーム次元では持たない）。\n\nすべてのエクストルーパークリーチャーは、その説明文に書かれているホーム次元を持っている。エクストルーパー次元と書かれていないクリーチャーは物質界の出身であり、物質界を離れるとエクストルーパー次元のサブタイプを得る。\n\nどのクリーチャーも、アストラル界やエーテル界や遷移界のような推移面にいるときには、外界サブタイプを持たない。"},


[ust_ang]={n=s_angel		,d=s_angel_d.."\n\n"..[[
<b>特性:</b>
— 夜目力60フィート、低照度視力。
— 酸、冷気、石化に免疫がある。
— 耐電気10、耐火10。
— 毒に対するセーヴに+4の種族ボーナス。
— プロテクトオーラ（超自然):悪クリーチャーによる攻撃や効果に対して、この能力はエンジェルから20フィート以内の誰にでもACに+4の偏向ボーナスとセーヴィングスローに+4の抵抗ボーナスを提供します。それ以外の場合、この能力は悪に対する魔法陣と20フィートの半径を持つ小さな無敵の球体の効果として機能します（呪文の使い手レベルはエンジェルのヒットダイス(HD)に等しい）。このオーラは解除することができますが、エンジェルは次のターンに自由アクションとして再び作成することができます。（魔法陣からの防御的な利益はエンジェルの統計ブロックに含まれていません。)
— 万能語（超自然）:すべてのエンジェルは、エンジェルのヒットダイス(HD)に等しいキャスターレベルの万能言語呪文を使用しているかのように、言語を持つすべてのクリーチャーと話すことができます。この能力は常に発動しています。]]},


[ust_arc]={n=s_archon		,d=s_archon_d.."\n\n"..[[
<b>特性:</b>
— 夜目力60フィート、低照度視力。
— 電気と石化に対する免疫がある。
— 毒に対するセーヴに+4の種族ボーナス。
— 威嚇のオーラ（超自然）:戦ったり怒ったりするアーコンは正義のオーラに包まれる。アーコンの半径20フィート以内にいる敵対クリーチャーは、その効果に抵抗するためには意志によるセーヴに成功しなければならない。セーヴの難易度(DC)はアーコンの種類によって異なり、魅力ベースで、+2の種族ボーナスを含む。失敗した者は24時間、あるいはオーラを発生させたアーコンに命中するまで、攻撃、AC、セーヴに-2のペナルティを受ける。効果に抵抗したり、効果を解除したクリーチャーは、24時間の間、同じアーコンのオーラの影響を再び受けることはできない。
— 悪に対する魔法陣（超自然）：悪に対する魔法陣の効果は常にアーコンを取り囲む（呪文の使い手レベルはアーコンのヒットダイス(HD)に等しい）。(この魔法陣による防御効果はアーコンの統計ブロックには含まれない）。
— テレポート（超自然）:クリーチャーは自分自身と50ポンドまでの物しか運べないが、大テレポートを呪文（呪文の使い手レベル14）のように意志で使うことができる。
— 万能言語（超自然）:すべてのアーコンは、万能呪文を使用しているかのように、言語を持つすべてのクリーチャーと話すことができます（キャスターレベルは14レベル）。この能力は常に発動しています。]]},


[ust_shp]={n="変身生物"	,d=[[変身生物は1つ以上の別の姿をとる超自然的能力を持つ。多くの魔法効果が何らかの変身を可能にしており、変身できるクリーチャーすべてが変身生物のサブタイプを持つわけではない。

<b>特性:</b>
— そのクリーチャーの肉体武器、単純武器、そのクリーチャー任意の武器に熟練する。
— 鎧を着用している場合、そのタイプの鎧と、よりライトタイプの鎧、さらに盾に習熟する。]]},


[ust_inc]={n="非実体"	,d=[[非実体クリーチャーは肉体を持たない。それは他の非実体クリーチャー、魔法の武器、または魔法の武器として攻撃するクリーチャー、呪文、呪文のような能力、超自然的能力によってのみ傷つけられる。魔法以外の攻撃形態にはすべて免疫がある。呪文や魔法武器による攻撃を受けても、肉体を発生源とするあらゆるダメージ（正のエネルギー、負のエネルギー、マジックミサイルのような力による効果、ゴースト接触武器による攻撃を除く）を50％の確率で無視する。魔法攻撃ではないが、聖水は非実体のアンデッドに影響を与えることができるが、聖水が命中しても50％の確率で非実体のクリーチャーには影響を与えない。

非実体クリーチャーは外皮ボーナスを持たないが、魅力ボーナスに等しい偏向ボーナスを持つ（通常魅力値がボーナスを持たないクリーチャーであっても、常に少なくとも+1）。

非実体のクリーチャーは固体の物体に入るか通り抜けることができますが、その物体の外側に隣接していなければならず、したがって、自分より大きな空間を持つ物体を完全に通り抜けることはできません。非実体のクリーチャーは現在の位置に隣接したスクエア内に存在するクリーチャーや物体の存在を感知することができますが、敵からは非実体のクリーチャーが物体の内部にいる場合、完全に遮蔽されています（50％のミスチャンスがあります）。非実体のクリーチャーが物体の外側から遠くを見て通常攻撃するためには、その非実体のクリーチャーは出現しなければなりません。物体の内部にいる非実体のクリーチャーは完全な隠蔽を持ちますが、物体の外部のクリーチャーに攻撃するときには、隠蔽しかありません。したがって、外部のクリーチャーは準備したアクションで攻撃することができます。非実体のクリーチャーは、力の効果を通過することができません。

非実体のクリーチャーの攻撃は、外皮、鎧、および盾を貫通します（無視します）が、偏向ボーナスや力の効果（例：メイジアーマー）は通常通りに機能します。非実体のクリーチャーは、水中でも空中と同様に容易に通過し、活動します。非実体のクリーチャーは落下したり落下ダメージを受けたりすることはありません。非実体のクリーチャーは足払い攻撃や組みつき攻撃を行うことができませんし、足払いや組みつきに巻き込まれることもありません。実際、彼らは相手やその装備を動かしたり操作する物理的な行動を取ることはできませんし、そのような行動の対象にもなりません。非実体のクリーチャーは重量がなく、重量によって起動するトラップを起動しません。

非実体のクリーチャーは忍び足し、それが望まない場合は聞き耳を立てても聞くことはできません。彼らには筋力値がないため、彼らのダメージロールは常に敏捷力ボーナスが適用されます。匂いや盲視などの非視覚的な感覚は、非実体のクリーチャーに対しては無効または部分的にしか効果がありません。非実体のクリーチャーは方向感覚を持ち、見えない場合でも完全な速度で移動することができます。]]},


[ust_swm]={n="スウォーム"	,d=[[スウォームとは、1体のクリーチャーとして行動する細長い、小さい、あるいは小さなクリーチャーの密集した塊のことである。スウォームは小集団であれば特に危険ではないが、十分な数が集まれば恐ろしい敵となる。

バットのスウォーム、センチピードのスウォーム、ヘルワスプのスウォーム、ロウカスのスウォーム、ラットのスウォーム、スパイダーのスウォームなど、さまざまなクリーチャーがスウォームとして大量発生する。スウォームのタイプは構成クリーチャーの性質（多くは動物か蟲）によって異なるが、すべてのスウォームはスウォームのサブタイプを持つ。

スウォームはここに書かれているものを除き、そのタイプ の特性を持つ。スウォームは単一のヒットダイス(HD)とヒットポイント(HP)、単一の統率力修正、単一のスピード、単一のアーマークラスを持つ。また、単一のクリーチャーとしてセーヴィングスローを行なう。

スウォーム1体は、（飛行を持たないクリーチャーで構成されている場合）1辺が10フィートの正方形か（飛行を持つクリーチャーで構成されている場合）1辺が10フィートの立方体を占めるが、その射程はクリーチャーと同様に0フィートである。

攻撃するためには、相手のスペースに移動し、機会攻撃を誘発する。

獲物の上を這い回るので、どのサイズのクリーチャーでも同じ空間を占めることができるが、10フィートの空間を持つクリーチャーであることに変わりはない。

スウォームは機会攻撃を行なうことはないが、機会攻撃を誘発させることはある。

スウォームは敵のいるマスや敵のいないマスを支障なく移動できるが、その場合は機会攻撃を誘発する。

10フィートの空間を持つ他のクリーチャーとは異なり、スウォームは形を作ることができる。それは任意の4つの連続した正方形を占めることができ、そのクリーチャーの1体を含むのに十分な大きさの空間を通り抜けることができる。スウォームはそのクリーチャーを構成するのに十分な大きさの亀裂や穴を通り抜けて移動できる。

極小クリーチャーのスウォームは、300体の飛行を持たないクリーチャーか、1,000体の飛行を持つクリーチャーで構成される。
矮小クリーチャーのスウォームは、1,500体の飛行を持たないクリーチャーか、5,000体の飛行を持つクリーチャーで構成される。
微細クリーチャーのスウォームは、飛んでいるかどうかに関わらず、10,000体のクリーチャーで構成される。

飛行クリーチャー以外のクリーチャーのスウォームには、通常10フィート四方に収まるクリーチャーの数よりも多くのクリーチャーが含まれる。なぜなら、スウォームのクリーチャーは密集しており、移動するときや攻撃するときには互いや獲物の上を這い回るのが一般的だからである。より大きなスウォームは単一のスウォームの倍数で表される。大きなスウォームは完全に形を変えることができるが、通常は連続したままである。巨大なスウォームは、実際には近接した数十のスウォームで構成される。

<b>特性:</b>
微細クリーチャーで構成されたスウォームは、すべての武器によるダメージを受けない。
極小クリーチャーで構成されたスウォームは、斬撃や貫通武器からのダメージが半分になる。
スウォームには明確な表も裏もなく、解剖学的な特徴もないため、クリティカルヒットや側面攻撃を受けることはない。
スウォームは足払いしたり、組みつきしたり、突進したりすることはできず、相手も組みつきすることはできない。
スウォームは特定のクリーチャーの数を対象とする呪文や効果（ディスインテグレートなどの単一対象呪文を含む）に対して免疫を持つが、スウォームが知力値と集団意識を持っている場合、精神効果は例外となる。
スウォームのヒットポイント(HP)を0以下にするとスウォームは解散するが、その時点まで受けたダメージによって攻撃力や抵抗力が低下することはない。スウォームがダメージによってよろめいたり瀕死の状態になったりすることはない。
スウォームは、拡散武器や多くの招来呪文のような、範囲に影響を及ぼす呪文や効果から受けるダメージの半分を受ける。
矮小や微細のクリーチャーで構成されたスウォームは、突風呪文によって生じるような強風の影響を受けやすい。スウォームに対する風の効果を判定する目的で、スウォームはその構成クリーチャーと同じサイズのクリーチャーとして扱う。非致死的ダメージによって意識を失ったスウォームは混乱して分散し、そのヒットポイント(HP)が非致死的ダメージを上回るまで再起しない。

スウォームの弱点: スウォームは物理攻撃で戦うのが非常に難しい。しかし、以下のような特殊な弱点もある。
点火した松明を即席武器として振り回すと、1ヒットにつき1d3ポイントの火属性のダメージを与える。
炎や霜のような特殊能力を持つ武器は、その武器の通常のダメージがスウォームに影響しない場合でも、ヒットするたびにそのエネルギーダメージをフルに与える。
点火したランタンは投擲武器として使用でき、割れた場所に隣接するマスにいるクリーチャーすべてに1d4点の火属性のダメージを与える。


スウォームアタック: スウォームサブタイプを持つクリーチャーは通常の近接攻撃を行なわない。その代わり、移動終了時にその空間を占めるクリーチャーに自動ダメージを与え、攻撃ロールは必要ない。スウォーム攻撃は攻撃ボーナスを持たず、カバーや援護によるミスチャンスの対象にもならない。

スウォームが与えるダメージ量は、以下のようにヒットダイス(HD)に基づく。
スウォームヒットダイス(HD)	スウォームの基本ダメージ
1–5			1d6
6–10			2d6
11–15			3d6
16–20			4d6
21+			5d6

スウォームの攻撃は、別段の指定がない限り非魔法的です。スウォームの攻撃のダメージを0にするために十分なダメージ減少、非実体性、および他の特殊能力は、通常、クリーチャーにスウォームからのダメージに対する免疫（あるいは少なくとも抵抗力）を与えます。一部のスウォームは、通常のダメージに加えて酸、毒、吸血、またはその他の特殊な攻撃を持つこともあります。


スウォームは自分のいるマスにいるクリーチャーに脅威を与えず、スウォーム攻撃で攻撃の機会を与えません。ただし、彼らが占める敵のスクエアは敵を散漫にさせ、以下に述べるように影響を与えます。

注意散漫（特殊能力）:スウォームのダメージを受けやすいクリーチャーで、そのマスにスウォームがいる状態でターンを開始したものは、1ラウンドの間吐き気を催す。頑健セーヴ（難易度(DC)10＋スウォームのヒットダイス(HD)の1/2＋スウォームの耐久力修正値）でこの効果を無効化できる。スウォームの範囲内で呪文を唱えたり、呪文に集中したりするには、集中判定（難易度(DC)20＋呪文レベル）が必要である。忍耐と集中を必要とする技能を使用するには、難易度(DC)20の集中判定が必要である。]]},
}